80		private TypeUpdateResult apply(MethodNode mth, SSAVar ssaVar, ArgType candidateType, TypeUpdateFlags flags) {
81			try {
82				if (candidateType == null || !candidateType.isTypeKnown()) {
83					return REJECT;
84				}
85				if (Consts.DEBUG_TYPE_INFERENCE) {
86					LOG.debug("Start type update for {} to {}", ssaVar.toShortString(), candidateType);
87				}
88				TypeUpdateInfo updateInfo = new TypeUpdateInfo(mth, flags, args);
89				TypeUpdateResult result = queueTypeUpdate(updateInfo, ssaVar.getAssign(), candidateType, null);
90				if (result == null) {
91					result = runUpdate(updateInfo);
92				}
93				if (result == REJECT) {
94					return result;
95				}
96				if (updateInfo.isEmpty()) {
97					return SAME;
98				}
99				if (Consts.DEBUG_TYPE_INFERENCE) {
100					LOG.debug("Applying type {} to {}:", candidateType, ssaVar.toShortString());
101					updateInfo.getSortedUpdates().forEach(upd -> LOG.debug("  {} -> {} in {}",
102							upd.getType(), upd.getArg().toShortString(), upd.getArg().getParentInsn()));
103				}
104				updateInfo.applyUpdates();
105				return CHANGED;
106			} catch (JadxOverflowException e) {
107				throw e;
108			} catch (Exception e) {
109				throw new JadxRuntimeException("Type update failed for variable: " + ssaVar + ", new type: " + candidateType, e);
110			}
