113		private TypeUpdateResult runUpdate(TypeUpdateInfo updateInfo) {
114			TypeUpdateResult result = REJECT;
115			while (true) {
116				TypeUpdateRequest request = updateInfo.pollNextRequest();
117				if (request == null) {
118					return result;
119				}
120				InsnArg updateArg = request.getArg();
121				ArgType updateType = request.getCandidateType();
122				TypeUpdateResult newResult;
123				if (request.isDirect()) {
124					newResult = requestUpdate(updateInfo, updateArg, updateType);
125				} else {
126					newResult = updateTypeForArg(updateInfo, updateArg, updateType);
127				}
128				updateInfo.saveCallback(request);
129				if (newResult == null) {
130					// no result: continue
131				} else {
132					// propagate result back through callbacks
133					result = processCallbacks(updateInfo, newResult);
134				}
135			}
