138		private static TypeUpdateResult processCallbacks(TypeUpdateInfo updateInfo, TypeUpdateResult result) {
139			TypeUpdateResult current = result;
140			while (true) {
141				TypeUpdateRequest cbReq = updateInfo.pollNextCallback();
142				if (cbReq == null) {
143					return current;
144				}
145				ITypeUpdateCallback callback = Objects.requireNonNull(cbReq.getCallback());
146				current = callback.updateCallback(current);
147				if (current == null) {
148					// no result, put callback back into queue
149					// so it can be executed once result is calculated
150					updateInfo.saveCallback(cbReq);
151					return null;
152				}
153				if (current == REJECT) {
154					updateInfo.rollbackUpdate(cbReq.getArg());
155				}
156				// proceed to next callback
157			}
