203		private @Nullable TypeUpdateResult verifyType(TypeUpdateInfo updateInfo, InsnArg arg, ArgType candidateType) {
204			if (candidateType == null) {
205				throw new JadxRuntimeException("Null type update for arg: " + arg);
206			}
207			if (updateInfo.isProcessed(arg)) {
208				return CHANGED;
209			}
210			ArgType currentType = arg.getType();
211			TypeUpdateFlags typeUpdateFlags = updateInfo.getFlags();
212			if (Objects.equals(currentType, candidateType)) {
213				if (!typeUpdateFlags.isIgnoreSame()) {
214					return SAME;
215				}
216			} else {
217				if (candidateType.isWildcard()) {
218					if (Consts.DEBUG_TYPE_INFERENCE) {
219						LOG.debug("Wildcard type rejected for {}: candidate={}, current={}", arg, candidateType, currentType);
220					}
221					return REJECT;
222				}
223	
224				TypeCompareEnum compareResult = comparator.compareTypes(candidateType, currentType);
225				if (compareResult.isConflict()) {
226					if (Consts.DEBUG_TYPE_INFERENCE) {
227						LOG.debug("Type rejected for {}: candidate={} in conflict with current={}", arg, candidateType, currentType);
228					}
229					return REJECT;
230				}
231				if (compareResult == TypeCompareEnum.UNKNOWN && typeUpdateFlags.isIgnoreUnknown()) {
232					return REJECT;
233				}
234				if (arg.isTypeImmutable() && currentType != ArgType.UNKNOWN) {
235					// don't changed type
236					if (compareResult == TypeCompareEnum.EQUAL) {
237						return SAME;
238					}
239					if (Consts.DEBUG_TYPE_INFERENCE) {
240						LOG.debug("Type rejected for {} due to conflict: candidate={}, current={}", arg, candidateType, currentType);
241					}
242					return REJECT;
243				}
244				if (compareResult == TypeCompareEnum.WIDER_BY_GENERIC && typeUpdateFlags.isKeepGenerics()) {
245					if (Consts.DEBUG_TYPE_INFERENCE) {
246						LOG.debug("Type rejected for {}: candidate={} is removing generic from current={}", arg, candidateType, currentType);
247					}
248					return REJECT;
249				}
250				if (compareResult.isWider() && !typeUpdateFlags.isAllowWider()) {
251					if (Consts.DEBUG_TYPE_INFERENCE) {
252						LOG.debug("Type rejected for {}: candidate={} is wider than current={}", arg, candidateType, currentType);
253					}
254					return REJECT;
255				}
256				if (candidateType.containsTypeVariable()) {
257					// reject unknown type vars
258					ArgType unknownTypeVar = root.getTypeUtils().checkForUnknownTypeVars(updateInfo.getMth(), candidateType);
259					if (unknownTypeVar != null) {
260						if (Consts.DEBUG_TYPE_INFERENCE) {
261							LOG.debug("Type rejected for {}: candidate: '{}' has unknown type var: '{}'", arg, candidateType, unknownTypeVar);
262						}
263						return REJECT;
264					}
265				}
266			}
267			return null;
268		}
269	
270		private TypeUpdateResult updateTypeForSsaVar(TypeUpdateInfo updateInfo, SSAVar ssaVar, ArgType candidateType) {
271			TypeInfo typeInfo = ssaVar.getTypeInfo();
272			ArgType immutableType = ssaVar.getImmutableType();
273			if (immutableType != null && !Objects.equals(immutableType, candidateType)) {
274				if (Consts.DEBUG_TYPE_INFERENCE) {
275					LOG.info("Reject change immutable type {} to {} for {}", immutableType, candidateType, ssaVar);
276				}
277				return REJECT;
278			}
279			if (!inBounds(updateInfo, ssaVar, typeInfo.getBounds(), candidateType)) {
280				return REJECT;
281			}
282			var updateCallback = new ArgsListUpdateCallback<>(this, updateInfo, ssaVar.getUseList(), candidateType, true);
283			updateCallback.setFinalResultCallback(result -> {
284				if (result == REJECT) {
285					// rollback update for all registers in current SSA var
286					updateInfo.rollbackUpdate(ssaVar.getAssign());
287					ssaVar.getUseList().forEach(updateInfo::rollbackUpdate);
288				}
289				return result;
290			});
291			return queueDirectTypeUpdate(updateInfo, ssaVar.getAssign(), candidateType, updateCallback);
292		}
293	
294		private TypeUpdateResult requestUpdate(TypeUpdateInfo updateInfo, InsnArg arg, ArgType candidateType) {
295			if (updateInfo.isProcessed(arg)) {
296				return CHANGED;
297			}
298			updateInfo.requestUpdate(arg, candidateType);
299			InsnNode insn = arg.getParentInsn();
300			if (insn == null) {
301				return SAME;
302			}
303			ITypeListener listener = listenerRegistry.get(insn.getType());
304			if (listener == null) {
305				return CHANGED;
306			}
307			if (Consts.DEBUG_TYPE_INFERENCE) {
308				LOG.debug("Run listener for insn: {}, arg: {}, type: {}", insn.getType(), arg, candidateType);
309			}
310			return listener.update(updateInfo, insn, arg, candidateType);
311		}
312	
313		boolean inBounds(Set<ITypeBound> bounds, ArgType candidateType) {
314			for (ITypeBound bound : bounds) {
315				ArgType boundType = bound.getType();
316				if (boundType != null && !checkBound(candidateType, bound, boundType)) {
317					return false;
318				}
319			}
320			return true;
321		}
322	
323		private boolean inBounds(TypeUpdateInfo updateInfo, SSAVar ssaVar, Set<ITypeBound> bounds, ArgType candidateType) {
324			for (ITypeBound bound : bounds) {
325				ArgType boundType;
326				if (updateInfo != null && bound instanceof ITypeBoundDynamic) {
327					boundType = ((ITypeBoundDynamic) bound).getType(updateInfo);
328				} else {
329					boundType = bound.getType();
330				}
331				if (boundType != null && !checkBound(candidateType, bound, boundType)) {
332					if (Consts.DEBUG_TYPE_INFERENCE) {
333						LOG.debug("Reject type '{}' for {} by bound: {} from {}", candidateType, ssaVar, boundType, bound);
334					}
335					return false;
336				}
337			}
338			return true;
339		}
340	
341		private boolean checkBound(ArgType candidateType, ITypeBound bound, ArgType boundType) {
342			TypeCompareEnum compareResult = comparator.compareTypes(candidateType, boundType);
343			switch (compareResult) {
344				case EQUAL:
345					return true;
346	
347				case WIDER:
348					return bound.getBound() != BoundEnum.USE;
349	
350				case NARROW:
351					if (bound.getBound() == BoundEnum.ASSIGN) {
352						return !boundType.isTypeKnown() && checkAssignForUnknown(boundType, candidateType);
353					}
354					return true;
355	
356				case WIDER_BY_GENERIC:
357				case NARROW_BY_GENERIC:
358					// allow replace object to same object with known generic type
359					// due to incomplete information about external methods and fields
360					return true;
361	
362				case CONFLICT:
363				case CONFLICT_BY_GENERIC:
364					return false;
365	
366				case UNKNOWN:
367					LOG.warn("Can't compare types, unknown hierarchy: {} and {}", candidateType, boundType);
368					comparator.compareTypes(candidateType, boundType);
369					return true;
370	
371				default:
372					throw new JadxRuntimeException("Not processed type compare enum: " + compareResult);
373			}
374		}
375	
376		private boolean checkAssignForUnknown(ArgType boundType, ArgType candidateType) {
377			if (boundType == ArgType.UNKNOWN) {
378				return true;
379			}
380			boolean candidateArray = candidateType.isArray();
381			if (boundType.isArray() && candidateArray) {
382				return checkAssignForUnknown(boundType.getArrayElement(), candidateType.getArrayElement());
383			}
384			if (candidateArray && boundType.contains(PrimitiveType.ARRAY)) {
385				return true;
386			}
387			if (candidateType.isObject() && boundType.contains(PrimitiveType.OBJECT)) {
388				return true;
389			}
390			if (candidateType.isPrimitive() && boundType.contains(candidateType.getPrimitiveType())) {
391				return true;
392			}
393			return false;
394		}
