396		private Map<InsnType, ITypeListener> initListenerRegistry() {
397			Map<InsnType, ITypeListener> registry = new EnumMap<>(InsnType.class);
398			registry.put(InsnType.CONST, this::sameFirstArgListener);
399			registry.put(InsnType.MOVE, this::moveListener);
400			registry.put(InsnType.PHI, this::allSameListener);
401			registry.put(InsnType.AGET, this::arrayGetListener);
402			registry.put(InsnType.APUT, this::arrayPutListener);
403			registry.put(InsnType.IF, this::ifListener);
404			registry.put(InsnType.ARITH, this::arithListener);
405			registry.put(InsnType.NEG, this::suggestAllSameListener);
406			registry.put(InsnType.NOT, this::suggestAllSameListener);
407			registry.put(InsnType.CHECK_CAST, this::checkCastListener);
408			registry.put(InsnType.INVOKE, this::invokeListener);
409			registry.put(InsnType.CONSTRUCTOR, this::invokeListener);
410			return registry;
411		}
412	
413		private TypeUpdateResult invokeListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
414			BaseInvokeNode invoke = (BaseInvokeNode) insn;
415			if (isAssign(invoke, arg)) {
416				// TODO: implement backward type propagation (from result to instance)
417				return SAME;
418			}
419			if (invoke.getInstanceArg() == arg) {
420				IMethodDetails methodDetails = root.getMethodUtils().getMethodDetails(invoke);
421				if (methodDetails == null) {
422					return SAME;
423				}
424				TypeUtils typeUtils = root.getTypeUtils();
425				Set<ArgType> knownTypeVars = typeUtils.getKnownTypeVarsAtMethod(updateInfo.getMth());
426				Map<ArgType, ArgType> typeVarsMap = typeUtils.getTypeVariablesMapping(candidateType);
427	
428				ArgType returnType = methodDetails.getReturnType();
429				List<ArgType> argTypes = methodDetails.getArgTypes();
430				int argsCount = argTypes.size();
431	
432				Supplier<ArgType> getReturnType;
433				Function<Integer, ArgType> getArgType;
434				if (typeVarsMap.isEmpty()) {
435					// generics can't be resolved => use as is
436					getReturnType = () -> returnType;
437					getArgType = argTypes::get;
438				} else {
439					// resolve types before apply
440					getReturnType = () -> typeUtils.replaceTypeVariablesUsingMap(returnType, typeVarsMap);
441					getArgType = argNum -> typeUtils.replaceClassGenerics(candidateType, argTypes.get(argNum));
442				}
443				return new InvokeUpdateCallback(this, updateInfo, invoke, argsCount, knownTypeVars, getReturnType, getArgType)
444						.runQueue();
445			}
446			return SAME;
447		}
448	
449		private TypeUpdateResult sameFirstArgListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
450			InsnArg changeArg = isAssign(insn, arg) ? insn.getArg(0) : insn.getResult();
451			if (updateInfo.hasUpdateWithType(changeArg, candidateType)) {
452				return CHANGED;
453			}
454			return queueTypeUpdate(updateInfo, changeArg, candidateType, null);
455		}
456	
457		private TypeUpdateResult moveListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
458			if (insn.getResult() == null) {
459				return CHANGED;
460			}
461			boolean assignChanged = isAssign(insn, arg);
462			InsnArg changeArg = assignChanged ? insn.getArg(0) : insn.getResult();
463	
464			// allow result to be wider
465			TypeCompareEnum cmp = comparator.compareTypes(candidateType, changeArg.getType());
466			boolean correctType = cmp.isEqual() || (assignChanged ? cmp.isWider() : cmp.isNarrow());
467	
468			return queueTypeUpdate(updateInfo, changeArg, candidateType, result -> {
469				if (result == SAME && !correctType) {
470					if (Consts.DEBUG_TYPE_INFERENCE) {
471						LOG.debug("Move insn types mismatch: {} -> {}, change arg: {}, insn: {}",
472								candidateType, changeArg.getType(), changeArg, insn);
473					}
474					return REJECT;
475				}
476				if (result == REJECT && correctType) {
477					return CHANGED;
478				}
479				return result;
480			});
481		}
482	
483		/**
484		 * All args must have same types
485		 */
486		private TypeUpdateResult allSameListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
487			if (!isAssign(insn, arg)) {
488				return queueTypeUpdate(updateInfo, insn.getResult(), candidateType, null);
489			}
490			// update args with same type
491			var updateCallback = new ArgsListUpdateCallback<>(this, updateInfo, insn.getArgList(), candidateType, false);
492			updateCallback.setArgsFilter(a -> a != arg);
493			return updateCallback.runFirstQueue();
494		}
495	
496		private TypeUpdateResult arithListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
497			ArithNode arithInsn = (ArithNode) insn;
498			if (candidateType == ArgType.BOOLEAN && arithInsn.getOp().isBitOp()) {
499				// force all args to boolean
500				return allSameListener(updateInfo, insn, arg, candidateType);
501			}
502			return suggestAllSameListener(updateInfo, insn, arg, candidateType);
503		}
504	
505		/**
506		 * Try to set candidate type to all args, don't fail on reject
507		 */
508		private TypeUpdateResult suggestAllSameListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
509			var updateCallback = new ArgsListUpdateCallback<>(this, updateInfo, insn.getArgList(), candidateType, false);
510			updateCallback.setArgsFilter(a -> a != arg);
511			updateCallback.setIgnoreReject(true);
512			if (!isAssign(insn, arg)) {
513				RegisterArg resultArg = insn.getResult();
514				if (resultArg != null) {
515					// start with result
516					return queueTypeUpdate(updateInfo, resultArg, candidateType, updateCallback);
517				}
518			}
519			// start with first arg
520			return updateCallback.runFirstQueue();
521		}
522	
523		private TypeUpdateResult checkCastListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
524			IndexInsnNode checkCast = (IndexInsnNode) insn;
525			if (isAssign(insn, arg)) {
526				InsnArg insnArg = insn.getArg(0);
527				return queueTypeUpdate(updateInfo, insnArg, candidateType,
528						r -> r == REJECT ? SAME : r);
529			}
530			ArgType castType = (ArgType) checkCast.getIndex();
531			TypeCompareEnum res = comparator.compareTypes(candidateType, castType);
532			if (res == TypeCompareEnum.CONFLICT) {
533				// allow casting one interface to another
534				if (!isInterfaces(candidateType, castType)) {
535					return REJECT;
536				}
537			}
538			if (res == TypeCompareEnum.CONFLICT_BY_GENERIC) {
539				if (!insn.contains(AFlag.SOFT_CAST)) {
540					return REJECT;
541				}
542			}
543			if (res == TypeCompareEnum.NARROW_BY_GENERIC && candidateType.containsGeneric()) {
544				// propagate generic type to result
545				return queueTypeUpdate(updateInfo, checkCast.getResult(), candidateType, null);
546			}
547			ArgType currentType = checkCast.getArg(0).getType();
548			return candidateType.equals(currentType) ? SAME : CHANGED;
549		}
550	
551		private boolean isInterfaces(ArgType firstType, ArgType secondType) {
552			if (!firstType.isObject() || !secondType.isObject()) {
553				return false;
554			}
555			ClspClass firstCls = root.getClsp().getClsDetails(firstType);
556			ClspClass secondCls = root.getClsp().getClsDetails(secondType);
557			if (firstCls != null && !firstCls.isInterface()) {
558				return false;
559			}
560			if (secondCls != null && !secondCls.isInterface()) {
561				return false;
562			}
563			if (firstCls == null || secondCls == null) {
564				return true;
565			}
566			return secondCls.isInterface() && firstCls.isInterface();
567		}
568	
569		private TypeUpdateResult arrayGetListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
570			if (isAssign(insn, arg)) {
571				return queueTypeUpdate(updateInfo, insn.getArg(0), ArgType.array(candidateType), result -> {
572					if (result == REJECT) {
573						ArgType arrType = insn.getArg(0).getType();
574						if (arrType.isTypeKnown() && arrType.isArray() && arrType.getArrayElement().isPrimitive()) {
575							TypeCompareEnum compResult = comparator.compareTypes(candidateType, arrType.getArrayElement());
576							if (compResult == TypeCompareEnum.WIDER) {
577								// allow implicit upcast for primitive types (int a = byteArr[n])
578								return CHANGED;
579							}
580						}
581					}
582					return result;
583				});
584			}
585			InsnArg arrArg = insn.getArg(0);
586			if (arrArg == arg) {
587				ArgType arrayElement = candidateType.getArrayElement();
588				if (arrayElement == null) {
589					return REJECT;
590				}
591				return queueTypeUpdate(updateInfo, insn.getResult(), arrayElement, result -> {
592					if (result == REJECT) {
593						ArgType resType = insn.getResult().getType();
594						if (resType.isTypeKnown() && resType.isPrimitive()) {
595							TypeCompareEnum compResult = comparator.compareTypes(resType, arrayElement);
596							if (compResult == TypeCompareEnum.WIDER) {
597								// allow implicit upcast for primitive types (int a = byteArr[n])
598								return CHANGED;
599							}
600						}
601					}
602					return result;
603				});
604			}
605			// index argument
606			return SAME;
607		}
608	
609		private TypeUpdateResult arrayPutListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
610			InsnArg arrArg = insn.getArg(0);
611			InsnArg putArg = insn.getArg(2);
612			if (arrArg == arg) {
613				ArgType arrayElement = candidateType.getArrayElement();
614				if (arrayElement == null) {
615					return REJECT;
616				}
617				return queueTypeUpdate(updateInfo, putArg, arrayElement, result -> {
618					if (result == REJECT) {
619						ArgType putType = putArg.getType();
620						if (putType.isTypeKnown()) {
621							TypeCompareEnum compResult = comparator.compareTypes(arrayElement, putType);
622							if (compResult == TypeCompareEnum.WIDER || compResult == TypeCompareEnum.WIDER_BY_GENERIC) {
623								// allow wider result (i.e. allow put any objects in Object[] or byte in int[])
624								return CHANGED;
625							}
626						}
627					}
628					return result;
629				});
630			}
631			if (arrArg == putArg) {
632				return queueTypeUpdate(updateInfo, arrArg, ArgType.array(candidateType), null);
633			}
634			// index
635			return SAME;
636		}
637	
638		private TypeUpdateResult ifListener(TypeUpdateInfo updateInfo, InsnNode insn, InsnArg arg, ArgType candidateType) {
639			InsnArg firstArg = insn.getArg(0);
640			InsnArg secondArg = insn.getArg(1);
641			InsnArg updateArg = firstArg == arg ? secondArg : firstArg;
642			return queueTypeUpdate(updateInfo, updateArg, candidateType, result -> {
643				if (result == REJECT) {
644					// soft checks for objects and array - exact type not compared
645					ArgType updateArgType = updateArg.getType();
646					if (candidateType.isObject() && updateArgType.canBeObject()) {
647						return SAME;
648					}
649					if (candidateType.isArray() && updateArgType.canBeArray()) {
650						return SAME;
651					}
652					if (candidateType.isPrimitive()) {
653						if (updateArgType.canBePrimitive(candidateType.getPrimitiveType())) {
654							return SAME;
655						}
656						if (updateArgType.isTypeKnown() && candidateType.getRegCount() == updateArgType.getRegCount()) {
657							return SAME;
658						}
659					}
660				}
661				return result;
662			});
663		}
664	
665		private static boolean isAssign(InsnNode insn, InsnArg arg) {
666			return insn.getResult() == arg;
667		}
668	
669		public TypeCompare getTypeCompare() {
670			return comparator;
671		}
672	}
