52	public final class TypeInferenceVisitor extends AbstractVisitor {
53		private static final Logger LOG = LoggerFactory.getLogger(TypeInferenceVisitor.class);
54	
55		private RootNode root;
56		private TypeUpdate typeUpdate;
57	
58		@Override
59		public void init(RootNode root) {
60			this.root = root;
61			this.typeUpdate = root.getTypeUpdate();
62		}
63	
64		@Override
65		public void visit(MethodNode mth) {
66			if (mth.isNoCode()) {
67				return;
68			}
69			if (Consts.DEBUG_TYPE_INFERENCE) {
70				LOG.info("Start type inference in method: {}", mth);
71			}
72			try {
73				assignImmutableTypes(mth);
74				initTypeBounds(mth);
75				runTypePropagation(mth);
76			} catch (StackOverflowError | BootstrapMethodError e) {
77				mth.addError("Type inference failed with stack overflow", new JadxOverflowException(e.getMessage()));
78			} catch (Exception e) {
79				mth.addError("Type inference failed", e);
80			}
81		}
82	
83		/**
84		 * Collect initial type bounds from assign and usages
85		 */
86		void initTypeBounds(MethodNode mth) {
87			List<SSAVar> ssaVars = mth.getSVars();
88			ssaVars.forEach(this::attachBounds);
89			ssaVars.forEach(this::mergePhiBounds);
90			if (Consts.DEBUG_TYPE_INFERENCE) {
91				ssaVars.stream().sorted()
92						.forEach(ssaVar -> LOG.debug("Type bounds for {}: {}", ssaVar.toShortString(), ssaVar.getTypeInfo().getBounds()));
93			}
94		}
95	
96		/**
97		 * Guess type from usage and try to set it to current variable
98		 * and all connected instructions with {@link TypeUpdate#apply(MethodNode, SSAVar, ArgType)}
99		 */
100		boolean runTypePropagation(MethodNode mth) {
101			List<SSAVar> ssaVars = mth.getSVars();
102			ssaVars.forEach(var -> setImmutableType(mth, var));
103			ssaVars.forEach(var -> setBestType(mth, var));
104			return true;
105		}
106	
107		private void setImmutableType(MethodNode mth, SSAVar ssaVar) {
108			try {
109				ArgType immutableType = ssaVar.getImmutableType();
110				if (immutableType != null) {
111					TypeUpdateResult result = typeUpdate.applyWithWiderIgnSame(mth, ssaVar, immutableType);
112					if (Consts.DEBUG_TYPE_INFERENCE && result == TypeUpdateResult.REJECT) {
113						LOG.info("Reject initial immutable type {} for {}", immutableType, ssaVar);
114					}
115				}
116			} catch (JadxOverflowException e) {
117				throw e;
118			} catch (Exception e) {
119				mth.addWarnComment("Failed to set immutable type for var: " + ssaVar, e);
120			}
121		}
122	
123		private void setBestType(MethodNode mth, SSAVar ssaVar) {
124			try {
125				calculateFromBounds(mth, ssaVar);
126			} catch (JadxOverflowException e) {
127				throw e;
128			} catch (Exception e) {
129				mth.addWarnComment("Failed to calculate best type for var: " + ssaVar, e);
130			}
131		}
132	
133		private void calculateFromBounds(MethodNode mth, SSAVar ssaVar) {
134			TypeInfo typeInfo = ssaVar.getTypeInfo();
135			Set<ITypeBound> bounds = typeInfo.getBounds();
136			Optional<ArgType> bestTypeOpt = selectBestTypeFromBounds(bounds);
137			if (bestTypeOpt.isEmpty()) {
138				if (Consts.DEBUG_TYPE_INFERENCE) {
139					LOG.warn("Failed to select best type from bounds, count={} : ", bounds.size());
140					for (ITypeBound bound : bounds) {
141						LOG.warn("  {}", bound);
142					}
143				}
144				return;
145			}
146			ArgType candidateType = bestTypeOpt.get();
147			TypeUpdateResult result = typeUpdate.apply(mth, ssaVar, candidateType);
148			if (Consts.DEBUG_TYPE_INFERENCE && result == TypeUpdateResult.REJECT) {
149				if (ssaVar.getTypeInfo().getType().equals(candidateType)) {
150					LOG.info("Same type rejected: {} -> {}, bounds: {}", ssaVar, candidateType, bounds);
151				} else if (candidateType.isTypeKnown()) {
152					LOG.debug("Type rejected: {} -> {}, bounds: {}", ssaVar, candidateType, bounds);
153				}
154			}
155		}
156	
157		private Optional<ArgType> selectBestTypeFromBounds(Set<ITypeBound> bounds) {
158			return bounds.stream()
159					.map(ITypeBound::getType)
160					.filter(Objects::nonNull)
161					.max(typeUpdate.getTypeCompare().getComparator());
162		}
163	
164		private void attachBounds(SSAVar var) {
165			TypeInfo typeInfo = var.getTypeInfo();
166			typeInfo.getBounds().clear();
167			RegisterArg assign = var.getAssign();
168			addAssignBound(typeInfo, assign);
169	
170			for (RegisterArg regArg : var.getUseList()) {
171				addBound(typeInfo, makeUseBound(regArg));
172			}
173		}
174	
175		private void mergePhiBounds(SSAVar ssaVar) {
176			for (PhiInsn usedInPhi : ssaVar.getUsedInPhi()) {
177				Set<ITypeBound> bounds = ssaVar.getTypeInfo().getBounds();
178				bounds.addAll(usedInPhi.getResult().getSVar().getTypeInfo().getBounds());
179				for (InsnArg arg : usedInPhi.getArguments()) {
180					bounds.addAll(((RegisterArg) arg).getSVar().getTypeInfo().getBounds());
181				}
182			}
183		}
184	
185		private void addBound(TypeInfo typeInfo, ITypeBound bound) {
186			if (bound == null) {
187				return;
188			}
189			if (bound instanceof ITypeBoundDynamic
190					|| bound.getType() != ArgType.UNKNOWN) {
191				typeInfo.getBounds().add(bound);
192			}
193		}
194	
195		private void addAssignBound(TypeInfo typeInfo, RegisterArg assign) {
196			ArgType immutableType = assign.getImmutableType();
197			if (immutableType != null) {
198				addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, immutableType));
199				return;
200			}
201			InsnNode insn = assign.getParentInsn();
202			if (insn == null || insn.getResult() == null) {
203				addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, assign.getInitType()));
204				return;
205			}
206			switch (insn.getType()) {
207				case NEW_INSTANCE:
208					ArgType clsType = (ArgType) ((IndexInsnNode) insn).getIndex();
209					addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, clsType));
210					break;
211	
212				case CONSTRUCTOR:
213					ArgType ctrClsType = replaceAnonymousType((ConstructorInsn) insn);
214					addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, ctrClsType));
215					break;
216	
217				case CONST:
218					LiteralArg constLit = (LiteralArg) insn.getArg(0);
219					addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, constLit.getType()));
220					break;
221	
222				case MOVE_EXCEPTION:
223					ExcHandlerAttr excHandlerAttr = insn.get(AType.EXC_HANDLER);
224					if (excHandlerAttr != null) {
225						for (ClassInfo catchType : excHandlerAttr.getHandler().getCatchTypes()) {
226							addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, catchType.getType()));
227						}
228					} else {
229						addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, insn.getResult().getInitType()));
230					}
231					break;
232	
233				case INVOKE:
234					addBound(typeInfo, makeAssignInvokeBound((InvokeNode) insn));
235					break;
236	
237				case IGET:
238					addBound(typeInfo, makeAssignFieldGetBound((IndexInsnNode) insn));
239					break;
240	
241				case CHECK_CAST:
242					if (insn.contains(AFlag.SOFT_CAST)) {
243						// ignore bound, will run checks on update
244					} else {
245						addBound(typeInfo, new TypeBoundCheckCastAssign(root, (IndexInsnNode) insn));
246					}
247					break;
248	
249				default:
250					ArgType type = insn.getResult().getInitType();
251					addBound(typeInfo, new TypeBoundConst(BoundEnum.ASSIGN, type));
252					break;
253			}
254		}
255	
256		private ArgType replaceAnonymousType(ConstructorInsn ctr) {
257			if (ctr.isNewInstance()) {
258				ClassNode ctrCls = root.resolveClass(ctr.getClassType());
259				if (ctrCls != null && ctrCls.contains(AFlag.DONT_GENERATE)) {
260					AnonymousClassAttr baseTypeAttr = ctrCls.get(AType.ANONYMOUS_CLASS);
261					if (baseTypeAttr != null && baseTypeAttr.getInlineType() == AnonymousClassAttr.InlineType.CONSTRUCTOR) {
262						return baseTypeAttr.getBaseType();
263					}
264				}
265			}
266			return ctr.getClassType().getType();
267		}
268	
269		private ITypeBound makeAssignFieldGetBound(IndexInsnNode insn) {
270			ArgType initType = insn.getResult().getInitType();
271			if (initType.containsTypeVariable()) {
272				return new TypeBoundFieldGetAssign(root, insn, initType);
273			}
274			return new TypeBoundConst(BoundEnum.ASSIGN, initType);
275		}
276	
277		private ITypeBound makeAssignInvokeBound(InvokeNode invokeNode) {
278			ArgType boundType = invokeNode.getCallMth().getReturnType();
279			ArgType genericReturnType = root.getMethodUtils().getMethodGenericReturnType(invokeNode);
280			if (genericReturnType != null) {
281				if (genericReturnType.containsTypeVariable()) {
282					InvokeType invokeType = invokeNode.getInvokeType();
283					if (invokeNode.getArgsCount() != 0
284							&& invokeType != InvokeType.STATIC && invokeType != InvokeType.SUPER) {
285						return new TypeBoundInvokeAssign(root, invokeNode, genericReturnType);
286					}
287				} else {
288					boundType = genericReturnType;
289				}
290			}
291			return new TypeBoundConst(BoundEnum.ASSIGN, boundType);
292		}
293	
294		@Nullable
295		private ITypeBound makeUseBound(RegisterArg regArg) {
296			InsnNode insn = regArg.getParentInsn();
297			if (insn == null) {
298				return null;
299			}
300			if (insn instanceof BaseInvokeNode) {
301				ITypeBound invokeUseBound = makeInvokeUseBound(regArg, (BaseInvokeNode) insn);
302				if (invokeUseBound != null) {
303					return invokeUseBound;
304				}
305			}
306			if (insn.getType() == InsnType.CHECK_CAST && insn.contains(AFlag.SOFT_CAST)) {
307				// ignore
308				return null;
309			}
310			return new TypeBoundConst(BoundEnum.USE, regArg.getInitType(), regArg);
311		}
312	
313		private ITypeBound makeInvokeUseBound(RegisterArg regArg, BaseInvokeNode invoke) {
314			InsnArg instanceArg = invoke.getInstanceArg();
315			if (instanceArg == null) {
316				return null;
317			}
318			MethodUtils methodUtils = root.getMethodUtils();
319			IMethodDetails methodDetails = methodUtils.getMethodDetails(invoke);
320			if (methodDetails == null) {
321				return null;
322			}
323			if (instanceArg != regArg) {
324				int argIndex = invoke.getArgIndex(regArg) - invoke.getFirstArgOffset();
325				ArgType argType = methodDetails.getArgTypes().get(argIndex);
326				if (!argType.containsTypeVariable()) {
327					return null;
328				}
329				return new TypeBoundInvokeUse(root, invoke, regArg, argType);
330			}
331	
332			// for override methods use origin declared class as a type
333			if (methodDetails instanceof MethodNode) {
334				MethodNode callMth = (MethodNode) methodDetails;
335				ClassInfo declCls = methodUtils.getMethodOriginDeclClass(callMth);
336				return new TypeBoundConst(BoundEnum.USE, declCls.getType(), regArg);
337			}
338			return null;
339		}
340	
341		private void assignImmutableTypes(MethodNode mth) {
342			for (SSAVar ssaVar : mth.getSVars()) {
343				ArgType immutableType = getSsaImmutableType(ssaVar);
344				if (immutableType != null) {
345					ssaVar.markAsImmutable(immutableType);
346				}
347			}
348		}
349	
350		@Nullable
351		private static ArgType getSsaImmutableType(SSAVar ssaVar) {
352			if (ssaVar.getAssign().contains(AFlag.IMMUTABLE_TYPE)) {
353				return ssaVar.getAssign().getInitType();
354			}
355			for (RegisterArg reg : ssaVar.getUseList()) {
356				if (reg.contains(AFlag.IMMUTABLE_TYPE)) {
357					return reg.getInitType();
358				}
359			}
360			return null;
361		}
362	
363		@Override
364		public String getName() {
365			return "TypeInferenceVisitor";
366		}
367	}
