104		private MethodNode(ClassNode classNode, IMethodData mthData) {
105			this.mthInfo = MethodInfo.fromRef(classNode.root(), mthData.getMethodRef());
106			this.parentClass = classNode;
107			this.accFlags = new AccessInfo(mthData.getAccessFlags(), AFType.METHOD);
108			ICodeReader codeReader = mthData.getCodeReader();
109			if (codeReader == null) {
110				this.noCode = true;
111				this.codeReader = null;
112				this.insnsCount = 0;
113			} else {
114				this.noCode = false;
115				this.codeReader = codeReader.copy();
116				this.insnsCount = codeReader.getUnitsCount();
117			}
118	
119			this.retType = mthInfo.getReturnType();
120			this.argTypes = mthInfo.getArgumentsTypes();
121			this.typeParameters = Collections.emptyList();
122			unload();
123		}
