152		@Override
153		public void load() throws DecodeException {
154			if (loaded) {
155				// method already loaded
156				return;
157			}
158			try {
159				loaded = true;
160				if (noCode) {
161					regsCount = 0;
162					// TODO: registers not needed without code
163					initArguments(this.argTypes);
164					return;
165				}
166	
167				this.regsCount = codeReader.getRegistersCount();
168				this.argsStartReg = codeReader.getArgsStartReg();
169				initArguments(this.argTypes);
170	
171				if (contains(AType.JADX_ERROR)) {
172					// don't load instructions for method with errors
173					this.instructions = EMPTY_INSN_ARRAY;
174				} else {
175					InsnDecoder decoder = new InsnDecoder(this);
176					this.instructions = decoder.process(codeReader);
177				}
178			} catch (Exception e) {
179				if (!noCode) {
180					unload();
181					noCode = true;
182					// load without code
183					load();
184					noCode = false;
185				}
186				throw new DecodeException(this, "Load method exception: "
187						+ e.getClass().getSimpleName() + ": " + e.getMessage(), e);
188			}
189		}
