200		private void initArguments(List<ArgType> args) {
201			int pos = getArgsStartPos(args);
202			TypeUtils typeUtils = root().getTypeUtils();
203			if (accFlags.isStatic()) {
204				thisArg = null;
205			} else {
206				ArgType thisClsType = typeUtils.expandTypeVariables(this, parentClass.getType());
207				RegisterArg arg = InsnArg.reg(pos++, thisClsType);
208				arg.add(AFlag.THIS);
209				arg.add(AFlag.IMMUTABLE_TYPE);
210				thisArg = arg;
211			}
212			if (args.isEmpty()) {
213				argsList = Collections.emptyList();
214				return;
215			}
216			argsList = new ArrayList<>(args.size());
217			for (ArgType argType : args) {
218				ArgType expandedType = typeUtils.expandTypeVariables(this, argType);
219				RegisterArg regArg = InsnArg.reg(pos, expandedType);
220				regArg.add(AFlag.METHOD_ARGUMENT);
221				regArg.add(AFlag.IMMUTABLE_TYPE);
222				argsList.add(regArg);
223				pos += argType.getRegCount();
224			}
225		}
226	
227		private int getArgsStartPos(List<ArgType> args) {
228			if (noCode) {
229				return 0;
230			}
231			if (argsStartReg != -1) {
232				return argsStartReg;
233			}
234			int pos = regsCount;
235			for (ArgType arg : args) {
236				pos -= arg.getRegCount();
237			}
238			if (!accFlags.isStatic()) {
239				pos--;
240			}
241			return pos;
242		}
