277		public List<VarNode> collectArgNodes() {
278			ICodeInfo codeInfo = getTopParentClass().getCode();
279			int mthDefPos = getDefPosition();
280			int lineEndPos = CodeUtils.getLineEndForPos(codeInfo.getCodeStr(), mthDefPos);
281			int argsCount = mthInfo.getArgsCount();
282			List<VarNode> args = new ArrayList<>(argsCount);
283			codeInfo.getCodeMetadata().searchDown(mthDefPos, (pos, ann) -> {
284				if (pos > lineEndPos) {
285					// Stop at line end
286					return Boolean.TRUE;
287				}
288				if (ann instanceof NodeDeclareRef) {
289					ICodeNodeRef declRef = ((NodeDeclareRef) ann).getNode();
290					if (declRef instanceof VarNode) {
291						VarNode varNode = (VarNode) declRef;
292						if (!varNode.getMth().equals(this)) {
293							// Stop if we've gone too far and have entered a different method
294							return Boolean.TRUE;
295						}
296						args.add(varNode);
297					}
298				}
299				return null;
300			});
301			if (args.size() != argsCount) {
302				LOG.warn("Incorrect args count, expected: {}, got: {}", argsCount, args.size());
303			}
304			return args;
305		}
