66	/**
67	 * Visitor for modify method instructions
68	 * (remove, replace, process exception handlers)
69	 */
70	@JadxVisitor(
71			name = "ModVisitor",
72			desc = "Modify method instructions",
73			runBefore = {
74					CodeShrinkVisitor.class,
75					ProcessVariables.class
76			}
77	)
78	public class ModVisitor extends AbstractVisitor {
79		private static final Logger LOG = LoggerFactory.getLogger(ModVisitor.class);
80	
81		private static final long DOUBLE_TO_BITS = Double.doubleToLongBits(1);
82		private static final long FLOAT_TO_BITS = Float.floatToIntBits(1);
83	
84		@Override
85		public boolean visit(ClassNode cls) throws JadxException {
86			replaceConstInAnnotations(cls);
87			return true;
88		}
89	
90		@Override
91		public void visit(MethodNode mth) {
92			if (mth.isNoCode()) {
93				return;
94			}
95			InsnRemover remover = new InsnRemover(mth);
96			replaceStep(mth, remover);
97			removeStep(mth, remover);
98			iterativeRemoveStep(mth);
99		}
100	
101		private static void replaceStep(MethodNode mth, InsnRemover remover) {
102			ClassNode parentClass = mth.getParentClass();
103			for (BlockNode block : mth.getBasicBlocks()) {
104				remover.setBlock(block);
105				List<InsnNode> insnsList = block.getInstructions();
106				int size = insnsList.size();
107				for (int i = 0; i < size; i++) {
108					InsnNode insn = insnsList.get(i);
109					switch (insn.getType()) {
110						case CONSTRUCTOR:
111							processAnonymousConstructor(mth, ((ConstructorInsn) insn));
112							break;
113	
114						case CONST:
115						case CONST_STR:
116						case CONST_CLASS:
117							replaceConst(mth, parentClass, block, i, insn);
118							break;
119	
120						case SWITCH:
121							replaceConstKeys(mth, parentClass, (SwitchInsn) insn);
122							break;
123	
124						case NEW_ARRAY:
125							// replace with filled array if 'fill-array' is next instruction
126							NewArrayNode newArrInsn = (NewArrayNode) insn;
127							InsnNode nextInsn = getFirstUseSkipMove(insn.getResult());
128							if (nextInsn != null && nextInsn.getType() == InsnType.FILL_ARRAY) {
129								FillArrayInsn fillArrInsn = (FillArrayInsn) nextInsn;
130								if (checkArrSizes(mth, newArrInsn, fillArrInsn)) {
131									InsnNode filledArr = makeFilledArrayInsn(mth, newArrInsn, fillArrInsn);
132									replaceInsn(mth, block, i, filledArr);
133									remover.addAndUnbind(nextInsn);
134								}
135							}
136							break;
137	
138						case MOVE_EXCEPTION:
139							processMoveException(mth, block, insn, remover);
140							break;
141	
142						case ARITH:
143							processArith(mth, parentClass, (ArithNode) insn);
144							break;
145	
146						case CMP_L:
147						case CMP_G:
148							inlineCMPInsns(mth, block, i, insn, remover);
149							break;
150	
151						case CHECK_CAST:
152							removeCheckCast(mth, block, i, (IndexInsnNode) insn);
153							break;
154	
155						case CAST:
156							fixPrimitiveCast(mth, block, i, insn);
157							break;
158	
159						case IPUT:
160						case IGET:
161							fixFieldUsage(mth, (IndexInsnNode) insn);
162							break;
163	
164						default:
165							break;
166					}
167				}
168				remover.perform();
169			}
170		}
171	
172		/**
173		 * If field is not visible from use site => cast to origin class
174		 */
175		private static void fixFieldUsage(MethodNode mth, IndexInsnNode insn) {
176			InsnArg instanceArg = insn.getArg(insn.getType() == InsnType.IGET ? 0 : 1);
177			if (instanceArg.contains(AFlag.SUPER)) {
178				return;
179			}
180			if (instanceArg.isInsnWrap() && ((InsnWrapArg) instanceArg).getWrapInsn().getType() == InsnType.CAST) {
181				return;
182			}
183			FieldInfo fieldInfo = (FieldInfo) insn.getIndex();
184			ArgType clsType = fieldInfo.getDeclClass().getType();
185			ArgType instanceType = instanceArg.getType();
186			if (Objects.equals(clsType, instanceType)) {
187				// cast not needed
188				return;
189			}
190	
191			FieldNode fieldNode = mth.root().resolveField(fieldInfo);
192			if (fieldNode == null) {
193				// unknown field
194				TypeCompareEnum result = mth.root().getTypeCompare().compareTypes(instanceType, clsType);
195				if (result.isEqual() || (result == TypeCompareEnum.NARROW_BY_GENERIC && !instanceType.isGenericType())) {
196					return;
197				}
198			} else if (isFieldVisibleInMethod(fieldNode, mth)) {
199				return;
200			}
201			// insert cast
202			IndexInsnNode castInsn = new IndexInsnNode(InsnType.CAST, clsType, 1);
203			castInsn.addArg(instanceArg.duplicate());
204			castInsn.add(AFlag.SYNTHETIC);
205			castInsn.add(AFlag.EXPLICIT_CAST);
206	
207			InsnArg castArg = InsnArg.wrapInsnIntoArg(castInsn);
208			castArg.setType(clsType);
209			insn.replaceArg(instanceArg, castArg);
210			InsnRemover.unbindArgUsage(mth, instanceArg);
211		}
212	
213		private static boolean isFieldVisibleInMethod(FieldNode field, MethodNode mth) {
214			AccessInfo accessFlags = field.getAccessFlags();
215			if (accessFlags.isPublic()) {
216				return true;
217			}
218			ClassNode useCls = mth.getParentClass();
219			ClassNode fieldCls = field.getParentClass();
220			boolean sameScope = Objects.equals(useCls, fieldCls) && !mth.getAccessFlags().isStatic();
221			if (sameScope) {
222				return true;
223			}
224			if (accessFlags.isPrivate()) {
225				return false;
226			}
227			// package-private or protected
228			if (Objects.equals(useCls.getClassInfo().getPackage(), fieldCls.getClassInfo().getPackage())) {
229				// same package
230				return true;
231			}
232			if (accessFlags.isPackagePrivate()) {
233				return false;
234			}
235			// protected
236			TypeCompareEnum result = mth.root().getTypeCompare().compareTypes(useCls, fieldCls);
237			return result == TypeCompareEnum.NARROW; // true if use class is subclass of field class
238		}
