240		private static void replaceConstKeys(MethodNode mth, ClassNode parentClass, SwitchInsn insn) {
241			int[] keys = insn.getKeys();
242			int len = keys.length;
243			for (int k = 0; k < len; k++) {
244				IFieldInfoRef f = parentClass.getConstField(keys[k]);
245				if (f != null) {
246					insn.modifyKey(k, f);
247					addFieldUsage(f, mth);
248				}
249			}
250		}
