279		private void replaceConstInAnnotations(ClassNode cls) {
280			if (cls.root().getArgs().isReplaceConsts()) {
281				replaceConstsInAnnotationForAttrNode(cls, cls);
282				cls.getFields().forEach(f -> replaceConstsInAnnotationForAttrNode(cls, f));
283				cls.getMethods().forEach((m) -> {
284					replaceConstsInAnnotationForAttrNode(cls, m);
285					replaceConstsInAnnotationForMethodParamsAttr(cls, m);
286				});
287			}
288		}
