290		private void replaceConstsInAnnotationForMethodParamsAttr(ClassNode cls, MethodNode m) {
291			AnnotationMethodParamsAttr paramsAnnotation = m.get(JadxAttrType.ANNOTATION_MTH_PARAMETERS);
292			if (paramsAnnotation == null) {
293				return;
294			}
295			paramsAnnotation.getParamList().forEach(annotationsList -> replaceConstsInAnnotationsAttr(cls, annotationsList));
