298		private void replaceConstsInAnnotationForAttrNode(ClassNode parentCls, AttrNode attrNode) {
299			AnnotationsAttr annotationsList = attrNode.get(JadxAttrType.ANNOTATION_LIST);
300			replaceConstsInAnnotationsAttr(parentCls, annotationsList);
301		}
