303		private void replaceConstsInAnnotationsAttr(ClassNode parentCls, AnnotationsAttr annotationsList) {
304			if (annotationsList == null) {
305				return;
306			}
307			for (IAnnotation annotation : annotationsList.getAll()) {
308				if (annotation.getVisibility() == AnnotationVisibility.SYSTEM) {
309					continue;
310				}
311				for (Map.Entry<String, EncodedValue> entry : annotation.getValues().entrySet()) {
312					entry.setValue(replaceConstValue(parentCls, entry.getValue()));
313				}
314			}
315		}
