317		@SuppressWarnings("unchecked")
318		private EncodedValue replaceConstValue(ClassNode parentCls, EncodedValue encodedValue) {
319			if (encodedValue.getType() == EncodedType.ENCODED_ANNOTATION) {
320				IAnnotation annotation = (IAnnotation) encodedValue.getValue();
321				for (Map.Entry<String, EncodedValue> entry : annotation.getValues().entrySet()) {
322					entry.setValue(replaceConstValue(parentCls, entry.getValue()));
323				}
324				return encodedValue;
325			}
326			if (encodedValue.getType() == EncodedType.ENCODED_ARRAY) {
327				List<EncodedValue> listVal = (List<EncodedValue>) encodedValue.getValue();
328				if (!listVal.isEmpty()) {
329					listVal.replaceAll(v -> replaceConstValue(parentCls, v));
330				}
331				return new EncodedValue(EncodedType.ENCODED_ARRAY, listVal);
332			}
333			IFieldInfoRef constField = parentCls.getConstField(encodedValue.getValue());
334			if (constField != null) {
335				return new EncodedValue(EncodedType.ENCODED_FIELD, constField.getFieldInfo());
336			}
337			return encodedValue;
338		}
