340		private static void replaceConst(MethodNode mth, ClassNode parentClass, BlockNode block, int i, InsnNode insn) {
341			IFieldInfoRef f;
342			if (insn.getType() == InsnType.CONST_STR) {
343				String s = ((ConstStringNode) insn).getString();
344				f = parentClass.getConstField(s);
345			} else if (insn.getType() == InsnType.CONST_CLASS) {
346				ArgType t = ((ConstClassNode) insn).getClsType();
347				f = parentClass.getConstField(t);
348			} else {
349				f = parentClass.getConstFieldByLiteralArg((LiteralArg) insn.getArg(0));
350			}
351			if (f != null) {
352				InsnNode inode = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
353				inode.setResult(insn.getResult());
354				replaceInsn(mth, block, i, inode);
355				addFieldUsage(f, mth);
356			}
357		}
