359		private static void processArith(MethodNode mth, ClassNode parentClass, ArithNode arithNode) {
360			if (arithNode.getArgsCount() != 2) {
361				throw new JadxRuntimeException("Invalid args count in insn: " + arithNode);
362			}
363			InsnArg litArg = arithNode.getArg(1);
364			if (litArg.isLiteral()) {
365				IFieldInfoRef f = parentClass.getConstFieldByLiteralArg((LiteralArg) litArg);
366				if (f != null) {
367					InsnNode fGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
368					if (arithNode.replaceArg(litArg, InsnArg.wrapArg(fGet))) {
369						addFieldUsage(f, mth);
370					}
371				}
372			}
373		}
