439		/**
440		 * Remove unnecessary instructions
441		 */
442		private static void removeStep(MethodNode mth, InsnRemover remover) {
443			for (BlockNode block : mth.getBasicBlocks()) {
444				remover.setBlock(block);
445				for (InsnNode insn : block.getInstructions()) {
446					switch (insn.getType()) {
447						case NOP:
448						case GOTO:
449						case NEW_INSTANCE:
450							remover.addAndUnbind(insn);
451							break;
452	
453						default:
454							if (insn.contains(AFlag.REMOVE)) {
455								remover.addAndUnbind(insn);
456							}
457							break;
458					}
459				}
460				remover.perform();
461			}
462		}
463	
464		private static void iterativeRemoveStep(MethodNode mth) {
465			boolean changed;
466			do {
467				changed = false;
468				for (BlockNode block : mth.getBasicBlocks()) {
469					for (InsnNode insn : block.getInstructions()) {
470						if (insn.getType() == InsnType.MOVE
471								&& insn.isAttrStorageEmpty()
472								&& isResultArgNotUsed(insn)) {
473							InsnRemover.remove(mth, block, insn);
474							changed = true;
475							break;
476						}
477					}
478				}
479			} while (changed);
480		}
