482		private static boolean isResultArgNotUsed(InsnNode insn) {
483			RegisterArg result = insn.getResult();
484			if (result != null) {
485				SSAVar ssaVar = result.getSVar();
486				return ssaVar.getUseCount() == 0;
487			}
488			return false;
489		}
