491		/**
492		 * For args in anonymous constructor invoke apply:
493		 * - forbid inline into constructor call
494		 * - make variables final (compiler require this implicitly)
495		 */
496		private static void processAnonymousConstructor(MethodNode mth, ConstructorInsn co) {
497			IMethodDetails callMthDetails = mth.root().getMethodUtils().getMethodDetails(co);
498			if (!(callMthDetails instanceof MethodNode)) {
499				return;
500			}
501			MethodNode callMth = (MethodNode) callMthDetails;
502			if (!callMth.contains(AFlag.ANONYMOUS_CONSTRUCTOR) || callMth.contains(AFlag.NO_SKIP_ARGS)) {
503				return;
504			}
505			SkipMethodArgsAttr attr = callMth.get(AType.SKIP_MTH_ARGS);
506			if (attr != null) {
507				int argsCount = Math.min(callMth.getMethodInfo().getArgsCount(), co.getArgsCount());
508				for (int i = 0; i < argsCount; i++) {
509					if (attr.isSkip(i)) {
510						anonymousCallArgMod(co.getArg(i));
511					}
512				}
513			} else {
514				// additional info not available apply mods to all args (the safest solution)
515				co.getArguments().forEach(ModVisitor::anonymousCallArgMod);
516			}
517		}
518	
519		private static void anonymousCallArgMod(InsnArg arg) {
520			arg.add(AFlag.DONT_INLINE);
521			if (arg.isRegister()) {
522				((RegisterArg) arg).getSVar().getCodeVar().setFinal(true);
523			}
524		}
