526		/**
527		 * Return first usage instruction for arg.
528		 * If used only once try to follow move chain
529		 */
530		@Nullable
531		private static InsnNode getFirstUseSkipMove(RegisterArg arg) {
532			SSAVar sVar = arg.getSVar();
533			int useCount = sVar.getUseCount();
534			if (useCount == 0) {
535				return null;
536			}
537			RegisterArg useArg = sVar.getUseList().get(0);
538			InsnNode parentInsn = useArg.getParentInsn();
539			if (parentInsn == null) {
540				return null;
541			}
542			if (useCount == 1 && parentInsn.getType() == InsnType.MOVE) {
543				return getFirstUseSkipMove(parentInsn.getResult());
544			}
545			return parentInsn;
546		}
