548		private static InsnNode makeFilledArrayInsn(MethodNode mth, NewArrayNode newArrayNode, FillArrayInsn insn) {
549			ArgType insnArrayType = newArrayNode.getArrayType();
550			ArgType insnElementType = insnArrayType.getArrayElement();
551			ArgType elType = insn.getElementType();
552			if (!elType.isTypeKnown()
553					&& insnElementType.isPrimitive()
554					&& elType.contains(insnElementType.getPrimitiveType())) {
555				elType = insnElementType;
556			}
557			if (!elType.equals(insnElementType) && !insnArrayType.equals(ArgType.OBJECT)) {
558				mth.addWarn("Incorrect type for fill-array insn " + InsnUtils.formatOffset(insn.getOffset())
559						+ ", element type: " + elType + ", insn element type: " + insnElementType);
560			}
561			if (!elType.isTypeKnown()) {
562				LOG.warn("Unknown array element type: {} in mth: {}", elType, mth);
563				elType = insnElementType.isTypeKnown() ? insnElementType : elType.selectFirst();
564				if (elType == null) {
565					throw new JadxRuntimeException("Null array element type");
566				}
567			}
568	
569			List<LiteralArg> list = insn.getLiteralArgs(elType);
570			InsnNode filledArr = new FilledNewArrayNode(elType, list.size());
571			filledArr.setResult(newArrayNode.getResult().duplicate());
572			for (LiteralArg arg : list) {
573				IFieldInfoRef f = mth.getParentClass().getConstFieldByLiteralArg(arg);
574				if (f != null) {
575					InsnNode fGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
576					filledArr.addArg(InsnArg.wrapArg(fGet));
577					addFieldUsage(f, mth);
578				} else {
579					filledArr.addArg(arg.duplicate());
580				}
581			}
582			return filledArr;
583		}
