585		private static void processMoveException(MethodNode mth, BlockNode block, InsnNode insn, InsnRemover remover) {
586			ExcHandlerAttr excHandlerAttr = block.get(AType.EXC_HANDLER);
587			if (excHandlerAttr == null) {
588				return;
589			}
590			ExceptionHandler excHandler = excHandlerAttr.getHandler();
591	
592			// result arg used both in this insn and exception handler,
593			RegisterArg resArg = insn.getResult();
594			ArgType type = excHandler.getArgType();
595			String name = excHandler.isCatchAll() ? "th" : "e";
596			if (resArg.getName() == null) {
597				resArg.setName(name);
598			}
599			SSAVar sVar = insn.getResult().getSVar();
600			if (sVar.getUseCount() == 0) {
601				excHandler.setArg(new NamedArg(name, type));
602				remover.addAndUnbind(insn);
603			} else if (sVar.isUsedInPhi()) {
604				// exception var moved to external variable => replace with 'move' insn
605				InsnNode moveInsn = new InsnNode(InsnType.MOVE, 1);
606				moveInsn.setResult(insn.getResult());
607				NamedArg namedArg = new NamedArg(name, type);
608				moveInsn.addArg(namedArg);
609				excHandler.setArg(namedArg);
610				replaceInsn(mth, block, 0, moveInsn);
611			}
612			block.copyAttributeFrom(insn, AType.CODE_COMMENTS); // save comment
613		}
