29	public class BlockSplitter extends AbstractVisitor {
30	
31		/**
32		 * Leave these instructions alone in the block node
33		 */
34		private static final Set<InsnType> SEPARATE_INSNS = EnumSet.of(
35				InsnType.RETURN,
36				InsnType.IF,
37				InsnType.SWITCH,
38				InsnType.MONITOR_ENTER,
39				InsnType.MONITOR_EXIT,
40				InsnType.THROW,
41				InsnType.MOVE_EXCEPTION);
42	
43		public static boolean isSeparate(InsnType insnType) {
44			return SEPARATE_INSNS.contains(insnType);
45		}
46	
47		/**
48		 * Split without connecting to the next block
49		 */
50		private static final Set<InsnType> SPLIT_WITHOUT_CONNECT = EnumSet.of(
51				InsnType.RETURN,
52				InsnType.THROW,
53				InsnType.GOTO,
54				InsnType.IF,
55				InsnType.SWITCH,
56				InsnType.JAVA_JSR,
57				InsnType.JAVA_RET);
58	
59		@Override
60		public void visit(MethodNode mth) {
61			if (mth.isNoCode()) {
62				return;
63			}
64			mth.initBasicBlocks();
65			Map<Integer, BlockNode> blocksMap = splitBasicBlocks(mth);
66			setupConnectionsFromJumps(mth, blocksMap);
67			initBlocksInTargetNodes(mth);
68	
69			expandMoveMulti(mth);
70			if (mth.contains(AFlag.RESOLVE_JAVA_JSR)) {
71				ResolveJavaJSR.process(mth);
72			}
73	
74			removeJumpAttr(mth);
75			removeInsns(mth);
76			removeEmptyDetachedBlocks(mth);
77			mth.getBasicBlocks().removeIf(BlockSplitter::removeEmptyBlock);
78	
79			addTempConnectionsForExcHandlers(mth, blocksMap);
80			setupExitConnections(mth);
81	
82			mth.updateBlockPositions();
83			mth.unloadInsnArr();
84		}
85	
86		private static Map<Integer, BlockNode> splitBasicBlocks(MethodNode mth) {
87			BlockNode enterBlock = startNewBlock(mth, -1);
88			enterBlock.add(AFlag.MTH_ENTER_BLOCK);
89			mth.setEnterBlock(enterBlock);
90	
91			BlockNode exitBlock = startNewBlock(mth, -1);
92			exitBlock.add(AFlag.MTH_EXIT_BLOCK);
93			mth.setExitBlock(exitBlock);
94	
95			Map<Integer, BlockNode> blocksMap = new HashMap<>();
96			BlockNode curBlock = enterBlock;
97			InsnNode prevInsn = null;
98			for (InsnNode insn : mth.getInstructions()) {
99				if (insn == null) {
100					continue;
101				}
102				if (insn.getType() == InsnType.NOP && insn.isAttrStorageEmpty()) {
103					continue;
104				}
105				int insnOffset = insn.getOffset();
106				if (prevInsn == null) {
107					// first block after method enter block
108					curBlock = connectNewBlock(mth, curBlock, insnOffset);
109				} else {
110					InsnType prevType = prevInsn.getType();
111					if (SPLIT_WITHOUT_CONNECT.contains(prevType)) {
112						curBlock = startNewBlock(mth, insnOffset);
113					} else if (isSeparate(prevType)
114							|| isSeparate(insn.getType())
115							|| insn.contains(AFlag.TRY_ENTER)
116							|| prevInsn.contains(AFlag.TRY_LEAVE)
117							|| insn.contains(AType.EXC_HANDLER)
118							|| isSplitByJump(prevInsn, insn)
119							|| isDoWhile(blocksMap, curBlock, insn)) {
120						curBlock = connectNewBlock(mth, curBlock, insnOffset);
121					}
122				}
123				blocksMap.put(insnOffset, curBlock);
124				curBlock.getInstructions().add(insn);
125				prevInsn = insn;
126			}
127			return blocksMap;
128		}
129	
130		/**
131		 * Init 'then' and 'else' blocks for 'if' instruction.
132		 */
133		private static void initBlocksInTargetNodes(MethodNode mth) {
134			mth.getBasicBlocks().forEach(block -> {
135				InsnNode lastInsn = BlockUtils.getLastInsn(block);
136				if (lastInsn instanceof TargetInsnNode) {
137					((TargetInsnNode) lastInsn).initBlocks(block);
138				}
139			});
140		}
