142		static BlockNode connectNewBlock(MethodNode mth, BlockNode block, int offset) {
143			BlockNode newBlock = startNewBlock(mth, offset);
144			connect(block, newBlock);
145			return newBlock;
146		}
147	
148		static BlockNode startNewBlock(MethodNode mth, int offset) {
149			List<BlockNode> blocks = mth.getBasicBlocks();
150			BlockNode block = new BlockNode(mth.getNextBlockCId(), blocks.size(), offset);
151			blocks.add(block);
152			return block;
153		}
154	
155		public static void connect(BlockNode from, BlockNode to) {
156			if (!from.getSuccessors().contains(to)) {
157				from.getSuccessors().add(to);
158			}
159			if (!to.getPredecessors().contains(from)) {
160				to.getPredecessors().add(from);
161			}
162		}
163	
164		public static void removeConnection(BlockNode from, BlockNode to) {
165			from.getSuccessors().remove(to);
166			to.getPredecessors().remove(from);
167		}
168	
169		public static void removePredecessors(BlockNode block) {
170			for (BlockNode pred : block.getPredecessors()) {
171				pred.getSuccessors().remove(block);
172			}
173			block.getPredecessors().clear();
174		}
175	
176		public static void replaceConnection(BlockNode source, BlockNode oldDest, BlockNode newDest) {
177			removeConnection(source, oldDest);
178			connect(source, newDest);
179			replaceTarget(source, oldDest, newDest);
180		}
181	
182		public static BlockNode insertBlockBetween(MethodNode mth, BlockNode source, BlockNode target) {
183			BlockNode newBlock = startNewBlock(mth, target.getStartOffset());
184			newBlock.add(AFlag.SYNTHETIC);
185			removeConnection(source, target);
186			connect(source, newBlock);
187			connect(newBlock, target);
188			replaceTarget(source, target, newBlock);
189			source.updateCleanSuccessors();
190			newBlock.updateCleanSuccessors();
191			return newBlock;
192		}
193	
194		static BlockNode blockSplitTop(MethodNode mth, BlockNode block) {
195			BlockNode newBlock = startNewBlock(mth, block.getStartOffset());
196			for (BlockNode pred : new ArrayList<>(block.getPredecessors())) {
197				replaceConnection(pred, block, newBlock);
198				pred.updateCleanSuccessors();
199			}
200			connect(newBlock, block);
201			newBlock.updateCleanSuccessors();
202			return newBlock;
