340			for (BlockNode block : mth.getBasicBlocks()) {
341				List<InsnNode> insnsList = block.getInstructions();
342				int len = insnsList.size();
343				for (int i = 0; i < len; i++) {
344					InsnNode insn = insnsList.get(i);
345					if (insn.getType() == InsnType.MOVE_MULTI) {
346						int mvCount = insn.getArgsCount() / 2;
347						for (int j = 0; j < mvCount; j++) {
348							InsnNode mv = new InsnNode(InsnType.MOVE, 1);
349							int startArg = j * 2;
350							mv.setResult((RegisterArg) insn.getArg(startArg));
351							mv.addArg(insn.getArg(startArg + 1));
352							mv.copyAttributesFrom(insn);
353							if (j == 0) {
354								mv.setOffset(insn.getOffset());
355								insnsList.set(i, mv);
356							} else {
357								insnsList.add(i + j, mv);
358							}
359						}
360						i += mvCount - 1;
361						len = insnsList.size();
362					}
363				}
364			}
365		}
