439			Deque<BlockNode> stack = new ArrayDeque<>();
440			stack.add(startBlock);
441			while (!stack.isEmpty()) {
442				BlockNode block = stack.pop();
443				if (!toRemove.contains(block)) {
444					toRemove.add(block);
445					for (BlockNode successor : block.getSuccessors()) {
446						if (successor != methodEnterBlock && toRemove.containsAll(successor.getPredecessors())) {
447							stack.push(successor);
448						}
449					}
450				}
451			}
