private @Nullable ArgType selectBestTypeFromBounds(Set<ITypeBound> bounds) {
	Comparator<ArgType> cmp = typeUpdate.getTypeCompare().getComparator();
	ArgType best = null;
	for (ITypeBound bound : bounds) {
		ArgType t = bound.getType();
		if (t == null) {
			continue;
		}
		if (best == null || cmp.compare(t, best) > 0) {
			best = t;
		}
	}
	return best;
}

