1	package jadx.core.dex.visitors;
2	
3	import java.util.Collections;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.stream.Collectors;
7	
8	import org.jetbrains.annotations.Nullable;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	
12	import jadx.api.data.CodeRefType;
13	import jadx.api.data.ICodeComment;
14	import jadx.api.data.ICodeData;
15	import jadx.api.data.IJavaCodeRef;
16	import jadx.api.data.IJavaNodeRef;
17	import jadx.core.codegen.utils.CodeComment;
18	import jadx.core.dex.attributes.AType;
19	import jadx.core.dex.attributes.IAttributeNode;
20	import jadx.core.dex.nodes.ClassNode;
21	import jadx.core.dex.nodes.FieldNode;
22	import jadx.core.dex.nodes.InsnNode;
23	import jadx.core.dex.nodes.MethodNode;
24	import jadx.core.dex.nodes.RootNode;
25	import jadx.core.utils.exceptions.JadxException;
26	import jadx.core.utils.exceptions.JadxRuntimeException;
27	
28	@JadxVisitor(
29			name = "AttachComments",
30			desc = "Attach user code comments",
31			runBefore = {
32					ProcessInstructionsVisitor.class
33			}
34	)
35	public class AttachCommentsVisitor extends AbstractVisitor {
36	
37		private static final Logger LOG = LoggerFactory.getLogger(AttachCommentsVisitor.class);
38	
39		private Map<String, List<ICodeComment>> clsCommentsMap;
40	
41		@Override
42		public void init(RootNode root) throws JadxException {
43			updateCommentsData(root.getArgs().getCodeData());
44			root.registerCodeDataUpdateListener(this::updateCommentsData);
45		}
46	
47		@Override
48		public boolean visit(ClassNode cls) {
49			List<ICodeComment> clsComments = getCommentsData(cls);
50			if (!clsComments.isEmpty()) {
51				applyComments(cls, clsComments);
52			}
53			cls.getInnerClasses().forEach(this::visit);
54			return false;
55		}
56	
57		private static void applyComments(ClassNode cls, List<ICodeComment> clsComments) {
58			for (ICodeComment comment : clsComments) {
59				IJavaNodeRef nodeRef = comment.getNodeRef();
60				switch (nodeRef.getType()) {
61					case CLASS:
62						addComment(cls, comment);
63						break;
64	
65					case FIELD:
66						FieldNode fieldNode = cls.searchFieldByShortId(nodeRef.getShortId());
67						if (fieldNode == null) {
68							LOG.warn("Field reference not found: {}", nodeRef);
69						} else {
70							addComment(fieldNode, comment);
71						}
72						break;
73	
74					case METHOD:
75						MethodNode methodNode = cls.searchMethodByShortId(nodeRef.getShortId());
76						if (methodNode == null) {
77							LOG.warn("Method reference not found: {}", nodeRef);
78						} else {
79							IJavaCodeRef codeRef = comment.getCodeRef();
80							if (codeRef == null) {
81								addComment(methodNode, comment);
82							} else {
83								processCustomAttach(methodNode, codeRef, comment);
84							}
85						}
86						break;
87				}
88			}
89		}
90	
91		private static InsnNode getInsnByOffset(MethodNode mth, int offset) {
92			try {
93				return mth.getInstructions()[offset];
94			} catch (Exception e) {
95				LOG.warn("Insn reference not found in: {} with offset: {}", mth, offset);
96				return null;
97			}
98		}
99	
100		private static void processCustomAttach(MethodNode mth, IJavaCodeRef codeRef, ICodeComment comment) {
101			CodeRefType attachType = codeRef.getAttachType();
102			switch (attachType) {
103				case INSN: {
104					InsnNode insn = getInsnByOffset(mth, codeRef.getIndex());
105					addComment(insn, comment);
106					break;
107				}
108				default:
109					throw new JadxRuntimeException("Unexpected attach type: " + attachType);
110			}
111		}
112	
113		private static void addComment(@Nullable IAttributeNode node, ICodeComment comment) {
114			if (node == null) {
115				return;
116			}
117			node.addAttr(AType.CODE_COMMENTS, new CodeComment(comment));
118		}
119	
120		private List<ICodeComment> getCommentsData(ClassNode cls) {
121			if (clsCommentsMap == null) {
122				return Collections.emptyList();
123			}
124			List<ICodeComment> clsComments = clsCommentsMap.get(cls.getClassInfo().getRawName());
125			if (clsComments == null) {
126				return Collections.emptyList();
127			}
128			return clsComments;
129		}
130	
131		private void updateCommentsData(@Nullable ICodeData data) {
132			if (data == null) {
133				this.clsCommentsMap = Collections.emptyMap();
134			} else {
135				this.clsCommentsMap = data.getComments().stream()
136						.collect(Collectors.groupingBy(c -> c.getNodeRef().getDeclaringClass()));
137			}
138		}
139	}
