32	@JadxVisitor(
33			name = "Constants Inline",
34			desc = "Inline constant registers into instructions",
35			runAfter = {
36					SSATransform.class,
37					MarkFinallyVisitor.class
38			},
39			runBefore = TypeInferenceVisitor.class
40	)
41	public class ConstInlineVisitor extends AbstractVisitor {
42	
43		@Override
44		public void visit(MethodNode mth) throws JadxException {
45			if (mth.isNoCode()) {
46				return;
47			}
48			process(mth);
49		}
50	
51		public static void process(MethodNode mth) {
52			List<InsnNode> toRemove = new ArrayList<>();
53			for (BlockNode block : mth.getBasicBlocks()) {
54				toRemove.clear();
55				for (InsnNode insn : block.getInstructions()) {
56					checkInsn(mth, insn, toRemove);
57				}
58				InsnRemover.removeAllAndUnbind(mth, block, toRemove);
59			}
60		}
61	
62		private static void checkInsn(MethodNode mth, InsnNode insn, List<InsnNode> toRemove) {
63			if (insn.contains(AFlag.DONT_INLINE)
64					|| insn.contains(AFlag.DONT_GENERATE)
65					|| insn.getResult() == null) {
66				return;
67			}
68			SSAVar sVar = insn.getResult().getSVar();
69			InsnArg constArg;
70			Runnable onSuccess = null;
71			switch (insn.getType()) {
72				case CONST:
73				case MOVE: {
74					constArg = insn.getArg(0);
75					if (!constArg.isLiteral()) {
76						return;
77					}
78					if (constArg.isZeroLiteral() && forbidNullInlines(sVar)) {
79						// all usages forbids inlining
80						return;
81					}
82					break;
83				}
84				case CONST_STR: {
85					String s = ((ConstStringNode) insn).getString();
86					IFieldInfoRef f = mth.getParentClass().getConstField(s);
87					if (f == null) {
88						InsnNode copy = insn.copyWithoutResult();
89						constArg = InsnArg.wrapArg(copy);
90					} else {
91						InsnNode constGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
92						constArg = InsnArg.wrapArg(constGet);
93						constArg.setType(ArgType.STRING);
94						onSuccess = () -> ModVisitor.addFieldUsage(f, mth);
95					}
96					break;
97				}
98				case CONST_CLASS: {
99					if (sVar.isUsedInPhi()) {
100						return;
101					}
102					constArg = InsnArg.wrapArg(insn.copyWithoutResult());
103					constArg.setType(ArgType.CLASS);
104					break;
105				}
106				default:
107					return;
108			}
109	
110			// all check passed, run replace
111			if (replaceConst(mth, insn, constArg)) {
112				toRemove.add(insn);
113				if (onSuccess != null) {
114					onSuccess.run();
115				}
116			}
117		}
118	
119		/**
120		 * Don't inline null object
121		 */
122		private static boolean forbidNullInlines(SSAVar sVar) {
123			List<RegisterArg> useList = sVar.getUseList();
124			if (useList.isEmpty()) {
125				return false;
126			}
127			int k = 0;
128			for (RegisterArg useArg : useList) {
129				InsnNode insn = useArg.getParentInsn();
130				if (insn != null && forbidNullArgInline(insn, useArg)) {
131					k++;
132				}
133			}
134			return k == useList.size();
135		}
136	
137		private static boolean forbidNullArgInline(InsnNode insn, RegisterArg useArg) {
138			if (insn.getType() == InsnType.MOVE) {
139				// result is null, chain checks
140				return forbidNullInlines(insn.getResult().getSVar());
141			}
142			if (!canUseNull(insn, useArg)) {
143				useArg.add(AFlag.DONT_INLINE_CONST);
144				return true;
145			}
146			return false;
147		}
148	
149		private static boolean canUseNull(InsnNode insn, RegisterArg useArg) {
150			switch (insn.getType()) {
151				case INVOKE:
152					return ((InvokeNode) insn).getInstanceArg() != useArg;
153	
154				case ARRAY_LENGTH:
155				case AGET:
156				case APUT:
157				case IGET:
158				case SWITCH:
159				case MONITOR_ENTER:
160				case MONITOR_EXIT:
161				case INSTANCE_OF:
162					return insn.getArg(0) != useArg;
163	
164				case IPUT:
165					return insn.getArg(1) != useArg;
166			}
167			return true;
168		}
169	
170		private static boolean replaceConst(MethodNode mth, InsnNode constInsn, InsnArg constArg) {
171			SSAVar ssaVar = constInsn.getResult().getSVar();
172			if (ssaVar.getUseCount() == 0) {
173				return true;
174			}
175			List<RegisterArg> useList = new ArrayList<>(ssaVar.getUseList());
176			int replaceCount = 0;
177			for (RegisterArg arg : useList) {
178				if (canInline(mth, arg) && replaceArg(mth, arg, constArg, constInsn)) {
179					replaceCount++;
180				}
181			}
182			if (replaceCount == useList.size()) {
183				return true;
184			}
185			// hide insn if used only in not generated insns
186			if (ListUtils.allMatch(ssaVar.getUseList(), ConstInlineVisitor::canIgnoreInsn)) {
187				constInsn.add(AFlag.DONT_GENERATE);
188			}
189			return false;
190		}
191	
192		private static boolean canIgnoreInsn(RegisterArg reg) {
193			InsnNode parentInsn = reg.getParentInsn();
194			if (parentInsn == null || parentInsn.getType() == InsnType.PHI) {
195				return false;
196			}
197			if (reg.isLinkedToOtherSsaVars()) {
198				return false;
199			}
200			return parentInsn.contains(AFlag.DONT_GENERATE);
201		}
202	
203		@SuppressWarnings("RedundantIfStatement")
204		private static boolean canInline(MethodNode mth, RegisterArg arg) {
205			if (arg.contains(AFlag.DONT_INLINE_CONST) || arg.contains(AFlag.DONT_INLINE)) {
206				return false;
207			}
208			InsnNode parentInsn = arg.getParentInsn();
209			if (parentInsn == null) {
210				return false;
211			}
212			if (parentInsn.contains(AFlag.DONT_GENERATE)) {
213				return false;
214			}
215			if (arg.isLinkedToOtherSsaVars() && !arg.getSVar().isUsedInPhi()) {
216				// don't inline vars used in finally block
217				return false;
218			}
219			if (parentInsn.getType() == InsnType.CONSTRUCTOR) {
220				// don't inline into anonymous call if it can be inlined later
221				MethodNode ctrMth = mth.root().getMethodUtils().resolveMethod((ConstructorInsn) parentInsn);
222				if (ctrMth != null
223						&& (ctrMth.contains(AFlag.METHOD_CANDIDATE_FOR_INLINE) || ctrMth.contains(AFlag.ANONYMOUS_CONSTRUCTOR))) {
224					return false;
225				}
226			}
227			return true;
228		}
229	
230		private static boolean replaceArg(MethodNode mth, RegisterArg arg, InsnArg constArg, InsnNode constInsn) {
231			InsnNode useInsn = arg.getParentInsn();
232			if (useInsn == null) {
233				return false;
234			}
235			InsnType insnType = useInsn.getType();
236			if (insnType == InsnType.PHI) {
237				return false;
238			}
239	
240			if (constArg.isLiteral()) {
241				long literal = ((LiteralArg) constArg).getLiteral();
242				ArgType argType = arg.getType();
243				if (argType == ArgType.UNKNOWN) {
244					argType = arg.getInitType();
245				}
246				if (argType.isObject() && literal != 0) {
247					argType = ArgType.NARROW_NUMBERS;
248				}
249				LiteralArg litArg = InsnArg.lit(literal, argType);
250				litArg.copyAttributesFrom(constArg);
251				if (!useInsn.replaceArg(arg, litArg)) {
252					return false;
253				}
254				// arg replaced, made some optimizations
255				IFieldInfoRef fieldNode = null;
256				ArgType litArgType = litArg.getType();
257				if (litArgType.isTypeKnown()) {
258					fieldNode = mth.getParentClass().getConstFieldByLiteralArg(litArg);
259				} else if (litArgType.contains(PrimitiveType.INT)) {
260					fieldNode = mth.getParentClass().getConstField((int) literal, false);
261				}
262				if (fieldNode != null) {
263					IndexInsnNode sgetInsn = new IndexInsnNode(InsnType.SGET, fieldNode.getFieldInfo(), 0);
264					if (litArg.wrapInstruction(mth, sgetInsn) != null) {
265						ModVisitor.addFieldUsage(fieldNode, mth);
266					}
267				} else {
268					addExplicitCast(useInsn, litArg);
269				}
270			} else {
271				if (!useInsn.replaceArg(arg, constArg.duplicate())) {
272					return false;
273				}
274			}
275			useInsn.inheritMetadata(constInsn);
276			return true;
277		}
278	
279		private static void addExplicitCast(InsnNode insn, LiteralArg arg) {
280			if (insn instanceof BaseInvokeNode) {
281				BaseInvokeNode callInsn = (BaseInvokeNode) insn;
282				MethodInfo callMth = callInsn.getCallMth();
283				if (callInsn.getInstanceArg() == arg) {
284					// instance arg is null, force cast
285					if (!arg.isZeroLiteral()) {
286						throw new JadxRuntimeException("Unexpected instance arg in invoke");
287					}
288					ArgType castType = callMth.getDeclClass().getType();
289					InsnNode castInsn = new IndexInsnNode(InsnType.CAST, castType, 1);
290					castInsn.addArg(arg);
291					castInsn.add(AFlag.EXPLICIT_CAST);
292					InsnArg wrapCast = InsnArg.wrapArg(castInsn);
293					wrapCast.setType(castType);
294					insn.replaceArg(arg, wrapCast);
295				} else {
296					int offset = callInsn.getFirstArgOffset();
297					int argIndex = insn.getArgIndex(arg);
298					ArgType argType = callMth.getArgumentsTypes().get(argIndex - offset);
299					if (argType.isPrimitive()) {
300						arg.setType(argType);
301						if (argType.equals(ArgType.BYTE)) {
302							arg.add(AFlag.EXPLICIT_PRIMITIVE_TYPE);
303						}
304					}
305				}
306			}
307		}
308	}
