40	
41	@JadxVisitor(
42			name = "ClassModifier",
43			desc = "Remove synthetic classes, methods and fields",
44			runAfter = {
45					ModVisitor.class,
46					FixAccessModifiers.class,
47					ProcessAnonymous.class,
48					ExtractFieldInit.class
49			}
50	)
51	public class ClassModifier extends AbstractVisitor {
52	
53		@Override
54		public boolean visit(ClassNode cls) throws JadxException {
55			if (cls.contains(AFlag.PACKAGE_INFO)) {
56				return false;
57			}
58			for (ClassNode inner : cls.getInnerClasses()) {
59				visit(inner);
60			}
61			if (isEmptySyntheticClass(cls)) {
62				cls.add(AFlag.DONT_GENERATE);
63				return false;
64			}
65			removeSyntheticFields(cls);
66			cls.getMethods().forEach(ClassModifier::removeSyntheticMethods);
67			cls.getMethods().forEach(ClassModifier::removeEmptyMethods);
68			return false;
69		}
70	
71		private static boolean isEmptySyntheticClass(ClassNode cls) {
72			return cls.getAccessFlags().isSynthetic()
73					&& cls.getFields().isEmpty()
74					&& cls.getMethods().isEmpty()
75					&& cls.getInnerClasses().isEmpty();
76		}
77	
78		/**
79		 * Remove synthetic fields if type is outer class or class will be inlined (anonymous)
80		 */
81		private static void removeSyntheticFields(ClassNode cls) {
82			boolean inline = cls.isAnonymous();
83			if (inline || cls.getClassInfo().isInner()) {
84				for (FieldNode field : cls.getFields()) {
85					ArgType fldType = field.getType();
86					if (field.getAccessFlags().isSynthetic() && fldType.isObject() && !fldType.isGenericType()) {
87						ClassInfo clsInfo = ClassInfo.fromType(cls.root(), fldType);
88						ClassNode fieldsCls = cls.root().resolveClass(clsInfo);
89						ClassInfo parentClass = cls.getClassInfo().getParentClass();
90						if (fieldsCls == null) {
91							continue;
92						}
93						boolean isParentInst = Objects.equals(parentClass, fieldsCls.getClassInfo());
94						if (inline || isParentInst) {
95							int found = 0;
96							for (MethodNode mth : cls.getMethods()) {
97								if (removeFieldUsageFromConstructor(mth, field, fieldsCls)) {
98									found++;
99								}
100							}
101							if (found != 0) {
102								if (isParentInst) {
103									field.addAttr(new FieldReplaceAttr(fieldsCls.getClassInfo()));
104								}
105								field.add(AFlag.DONT_GENERATE);
106							}
107						}
108					}
109				}
110			}
111		}
112	
113		private static boolean removeFieldUsageFromConstructor(MethodNode mth, FieldNode field, ClassNode fieldsCls) {
114			if (mth.isNoCode() || !mth.getAccessFlags().isConstructor()) {
115				return false;
116			}
117			List<RegisterArg> args = mth.getArgRegs();
118			if (args.isEmpty() || mth.contains(AFlag.SKIP_FIRST_ARG)) {
119				return false;
120			}
121			RegisterArg arg = args.get(0);
122			if (!arg.getType().equals(fieldsCls.getClassInfo().getType())) {
123				return false;
124			}
125			BlockNode block = mth.getEnterBlock().getCleanSuccessors().get(0);
126			List<InsnNode> instructions = block.getInstructions();
127			if (instructions.isEmpty()) {
128				return false;
129			}
130			InsnNode insn = instructions.get(0);
131			if (insn.getType() != InsnType.IPUT) {
132				return false;
133			}
134			IndexInsnNode putInsn = (IndexInsnNode) insn;
135			FieldInfo fieldInfo = (FieldInfo) putInsn.getIndex();
136			if (!fieldInfo.equals(field.getFieldInfo()) || !putInsn.getArg(0).equals(arg)) {
137				return false;
138			}
139			mth.skipFirstArgument();
140			InsnRemover.remove(mth, block, insn);
141			// other arg usage -> wrap with IGET insn
142			if (arg.getSVar().getUseCount() != 0) {
143				InsnNode iget = new IndexInsnNode(InsnType.IGET, fieldInfo, 1);
144				iget.addArg(insn.getArg(1));
145				for (InsnArg insnArg : new ArrayList<>(arg.getSVar().getUseList())) {
146					insnArg.wrapInstruction(mth, iget);
147				}
148			}
149			return true;
150		}
151	
152		private static void removeSyntheticMethods(MethodNode mth) {
153			if (mth.isNoCode() || mth.contains(AFlag.DONT_GENERATE)) {
154				return;
155			}
156			AccessInfo af = mth.getAccessFlags();
157			if (!af.isSynthetic()) {
158				return;
159			}
160			ClassNode cls = mth.getParentClass();
161			if (removeBridgeMethod(cls, mth)) {
162				if (Consts.DEBUG) {
163					mth.addDebugComment("Removed as synthetic bridge method");
164				} else {
165					mth.add(AFlag.DONT_GENERATE);
166				}
167				return;
168			}
169			// remove synthetic constructor for inner classes
170			if (mth.isConstructor()
171					&& (mth.contains(AFlag.METHOD_CANDIDATE_FOR_INLINE) || mth.contains(AFlag.ANONYMOUS_CONSTRUCTOR))) {
172				InsnNode insn = BlockUtils.getOnlyOneInsnFromMth(mth);
173				if (insn != null) {
174					List<RegisterArg> args = mth.getArgRegs();
175					if (isRemovedClassInArgs(cls, args)) {
176						modifySyntheticMethod(cls, mth, insn, args);
177					}
178				}
179			}
180		}
181	
182		private static boolean isRemovedClassInArgs(ClassNode cls, List<RegisterArg> mthArgs) {
183			boolean removedFound = false;
184			for (RegisterArg arg : mthArgs) {
185				ArgType argType = arg.getType();
186				if (!argType.isObject()) {
187					continue;
188				}
189				boolean remove = false;
190				ClassNode argCls = cls.root().resolveClass(argType);
191				if (argCls == null) {
192					// check if missing class from current top class
193					ClassInfo argClsInfo = ClassInfo.fromType(cls.root(), argType);
194					if (argClsInfo.getParentClass() != null
195							&& cls.getFullName().startsWith(argClsInfo.getParentClass().getFullName())) {
196						remove = true;
197					}
198				} else {
199					if (argCls.contains(AFlag.DONT_GENERATE) || isEmptySyntheticClass(argCls)) {
200						remove = true;
201					}
202				}
203				if (remove) {
204					arg.add(AFlag.REMOVE);
205					removedFound = true;
206				}
207			}
208			return removedFound;
209		}
210	
211		/**
212		 * Remove synthetic constructor and redirect calls to existing constructor
213		 */
214		private static void modifySyntheticMethod(ClassNode cls, MethodNode mth, InsnNode insn, List<RegisterArg> args) {
215			if (insn.getType() == InsnType.CONSTRUCTOR) {
216				ConstructorInsn constr = (ConstructorInsn) insn;
217				if (constr.isThis() && !args.isEmpty()) {
218					// remove first arg for non-static class (references to outer class)
219					RegisterArg firstArg = args.get(0);
220					if (firstArg.getType().equals(cls.getParentClass().getClassInfo().getType())) {
221						SkipMethodArgsAttr.skipArg(mth, 0);
222					}
223					// remove unused args
224					int argsCount = args.size();
225					for (int i = 0; i < argsCount; i++) {
226						RegisterArg arg = args.get(i);
227						SSAVar sVar = arg.getSVar();
228						if (sVar != null && sVar.getUseCount() == 0) {
229							SkipMethodArgsAttr.skipArg(mth, i);
230						}
231					}
232					MethodInfo callMth = constr.getCallMth();
233					MethodNode callMthNode = cls.root().resolveMethod(callMth);
234					if (callMthNode != null) {
235						mth.addAttr(new MethodReplaceAttr(callMthNode));
236						mth.add(AFlag.DONT_GENERATE);
237						// code generation order should be already fixed for marked methods
238						UsageInfoVisitor.replaceMethodUsage(callMthNode, mth);
239					}
240				}
241			}
242		}
243	
244		private static boolean removeBridgeMethod(ClassNode cls, MethodNode mth) {
245			if (cls.root().getArgs().isInlineMethods()) { // simple wrapper remove is same as inline
246				List<InsnNode> allInsns = BlockUtils.collectAllInsns(mth.getBasicBlocks());
247				if (allInsns.size() == 1) {
248					InsnNode wrappedInsn = allInsns.get(0);
249					if (wrappedInsn.getType() == InsnType.RETURN) {
250						InsnArg arg = wrappedInsn.getArg(0);
251						if (arg.isInsnWrap()) {
252							wrappedInsn = ((InsnWrapArg) arg).getWrapInsn();
253						}
254					}
255					return checkSyntheticWrapper(mth, wrappedInsn);
256				}
257			}
258			return false;
259		}
260	
261		private static boolean checkSyntheticWrapper(MethodNode mth, InsnNode insn) {
262			InsnType insnType = insn.getType();
263			if (insnType != InsnType.INVOKE) {
264				return false;
265			}
266			InvokeNode invokeInsn = (InvokeNode) insn;
267			if (invokeInsn.getInvokeType() == InvokeType.SUPER) {
268				return false;
269			}
270			MethodInfo callMth = invokeInsn.getCallMth();
271			MethodNode wrappedMth = mth.root().resolveMethod(callMth);
272			if (wrappedMth == null) {
273				return false;
274			}
275			AccessInfo wrappedAccFlags = wrappedMth.getAccessFlags();
276			if (wrappedAccFlags.isStatic()) {
277				return false;
278			}
279			if (callMth.getArgsCount() != mth.getMethodInfo().getArgsCount()) {
280				return false;
281			}
282			// rename method only from current class
283			if (!mth.getParentClass().equals(wrappedMth.getParentClass())) {
284				return false;
285			}
286			// all args must be registers passed from method args (allow only casts insns)
287			for (InsnArg arg : insn.getArguments()) {
288				if (!registersAndCastsOnly(arg)) {
289					return false;
290				}
291			}
292			// remove confirmed, change visibility and name if needed
293			if (!wrappedAccFlags.isPublic() && !mth.root().getArgs().isRespectBytecodeAccModifiers()) {
294				// must be public
295				FixAccessModifiers.changeVisibility(wrappedMth, AccessFlags.PUBLIC);
296			}
297			String alias = mth.getAlias();
298			if (!Objects.equals(wrappedMth.getAlias(), alias)) {
299				wrappedMth.rename(alias);
300				RenameReasonAttr.forNode(wrappedMth).append("merged with bridge method [inline-methods]");
301			}
302			wrappedMth.addAttr(new MethodReplaceAttr(mth));
303			wrappedMth.copyAttributeFrom(mth, AType.METHOD_OVERRIDE);
304			wrappedMth.addDebugComment("Method merged with bridge method: " + mth.getMethodInfo().getShortId());
305			return true;
306		}
307	
308		private static boolean registersAndCastsOnly(InsnArg arg) {
309			if (arg.isRegister()) {
310				return true;
311			}
312			if (arg.isInsnWrap()) {
313				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
314				if (wrapInsn.getType() == InsnType.CHECK_CAST) {
315					return registersAndCastsOnly(wrapInsn.getArg(0));
316				}
317			}
318			return false;
319		}
320	
321		/**
322		 * Remove public empty constructors (static or default)
323		 */
324		private static void removeEmptyMethods(MethodNode mth) {
325			if (!mth.getArgRegs().isEmpty()) {
326				return;
327			}
328			AccessInfo af = mth.getAccessFlags();
329			boolean publicConstructor = mth.isConstructor() && af.isPublic();
330			boolean enumDefConstructor = mth.isConstructor() && mth.getParentClass().contains(AFlag.CONVERTED_ENUM);
331			boolean clsInit = mth.getMethodInfo().isClassInit() && af.isStatic();
332			if (publicConstructor || enumDefConstructor || clsInit) {
333				if (!BlockUtils.isAllBlocksEmpty(mth.getBasicBlocks())) {
334					return;
335				}
336				if (clsInit) {
337					mth.add(AFlag.DONT_GENERATE);
338				} else {
339					// don't remove default constructor if other constructors exists or constructor has annotations
340					if (mth.isDefaultConstructor()
341							&& !isNonDefaultConstructorExists(mth)
342							&& !mth.contains(JadxAttrType.ANNOTATION_LIST)) {
343						mth.add(AFlag.DONT_GENERATE);
344					}
345				}
346			}
347		}
348	
349		private static boolean isNonDefaultConstructorExists(MethodNode defCtor) {
350			ClassNode parentClass = defCtor.getParentClass();
351			for (MethodNode mth : parentClass.getMethods()) {
352				if (mth != defCtor
353						&& mth.isConstructor()
354						&& !mth.isDefaultConstructor()) {
355					return true;
356				}
357			}
358			return false;
359		}
360	}
