7	public class DepthTraversal {
8	
9		public static void visit(IDexTreeVisitor visitor, ClassNode cls) {
10			try {
11				if (visitor.visit(cls)) {
12					cls.getInnerClasses().forEach(inCls -> visit(visitor, inCls));
13					cls.getMethods().forEach(mth -> visit(visitor, mth));
14				}
15			} catch (StackOverflowError | BootstrapMethodError | Exception e) {
16				cls.addError(e.getClass().getSimpleName() + " in pass: " + visitor.getClass().getSimpleName(), e);
17			}
18		}
19	
20		public static void visit(IDexTreeVisitor visitor, MethodNode mth) {
21			try {
22				if (mth.contains(AType.JADX_ERROR)) {
23					return;
24				}
25				visitor.visit(mth);
26			} catch (StackOverflowError | BootstrapMethodError | Exception e) {
27				mth.addError(e.getClass().getSimpleName() + " in pass: " + visitor.getClass().getSimpleName(), e);
28			}
29		}
30	
31		private DepthTraversal() {
32		}
33	}
