52		Region makeRegion(BlockNode startBlock) {
53			Objects.requireNonNull(startBlock);
54			Region region = new Region(stack.peekRegion());
55			if (stack.containsExit(startBlock)) {
56				insertEdgeInsns(region, startBlock);
57				return region;
58			}
59			if (processedBlocks.addChecked(startBlock)) {
60				// Add block to multiple regions (duplicate the instructions in decompiled code)

60				// Add block to multiple regions (duplicate the instructions in decompiled code)
61				// and allow processing to continue
62				if (!startBlock.contains(AFlag.DUPLICATED)) {
63					mth.addWarnComment("Code duplicated, block: " + startBlock + ' ' + startBlock.getAttributesString());
64					startBlock.add(AFlag.DUPLICATED);
65				}
66			}
67			BlockNode next = startBlock;
68			while (next != null) {
69				next = traverse(region, next);
70				regionsCount++;
71				if (regionsCount > regionsLimit) {
72					throw new JadxOverflowException("Regions count limit reached at block " + startBlock);
73				}
74			}
75			return region;
76		}
