78		/**
79		 * Recursively traverse all blocks from 'block' until block from 'exits'
80		 */
81		private @Nullable BlockNode traverse(Region r, BlockNode block) {
82			if (block.contains(AFlag.MTH_EXIT_BLOCK)) {
83				return null;
84			}
85			BlockNode next = null;
86			boolean processed = false;
87	
88			List<LoopInfo> loops = block.getAll(AType.LOOP);
89			int loopCount = loops.size();
90			if (loopCount != 0 && block.contains(AFlag.LOOP_START)) {
91				if (loopCount == 1) {
92					next = loopMaker.process(r, loops.get(0), stack);
93					processed = true;
94				} else {
95					for (LoopInfo loop : loops) {
96						if (loop.getStart() == block) {
97							next = loopMaker.process(r, loop, stack);
98							processed = true;
99							break;
100						}
101					}
102				}
103			}
104	
105			InsnNode insn = BlockUtils.getLastInsn(block);
106			if (!processed && insn != null) {
107				switch (insn.getType()) {
108					case IF:
109						next = ifMaker.process(r, block, (IfNode) insn, stack);
110						processed = true;
111						break;
112	
113					case SWITCH:
114						SwitchRegionMaker switchMaker = new SwitchRegionMaker(mth, this);
115						next = switchMaker.process(r, block, (SwitchInsn) insn, stack);
116						processed = true;
117						break;
118	
119					case MONITOR_ENTER:
120						SynchronizedRegionMaker syncMaker = new SynchronizedRegionMaker(mth, this);
121						next = syncMaker.process(r, block, insn, stack);
122						processed = true;
123						break;
124				}
125			}
126			if (!processed) {
127				r.add(block);
128				next = getNextBlock(block);
129			}
130			if (next != null && !stack.containsExit(block) && !stack.containsExit(next)) {
131				return next;
132			}
133			return null;
134		}
