136		private void insertEdgeInsns(Region region, BlockNode exitBlock) {
137			List<EdgeInsnAttr> edgeInsns = exitBlock.getAll(AType.EDGE_INSN);
138			if (edgeInsns.isEmpty()) {
139				return;
140			}
141			List<InsnNode> insns = new ArrayList<>(edgeInsns.size());
142			addOneInsnOfType(insns, edgeInsns, InsnType.BREAK);
143			addOneInsnOfType(insns, edgeInsns, InsnType.CONTINUE);
144			region.add(new InsnContainer(insns));
145		}
