35	/*
36	 * Definitions:
37	 * main loop body - the set of nodes that form a loop in the control flow graph e.g. they can all
38	 * reach the loop start and are all reachable from the loop start
39	 * loop exit edge - an edge with a source in the main loop body and a target outside the main loop
40	 * body
41	 * outblock - the first node after the entire loop has finished that should be regioned next
42	 * header block - an IF node that implements the loop condition
43	 * crossing - a block that is reachable from two different source nodes and represents where control
44	 * flow paths from the two blocks cross
45	 * exit block/node - an overloaded term. May mean the source or target of an exit edge, or a route
46	 * to exit the overall region e.g. the outblock
47	 */
48	
49	final class LoopRegionMaker {
50		private final MethodNode mth;
51		private final RegionMaker regionMaker;
52		private final IfRegionMaker ifMaker;
53	
54		LoopRegionMaker(MethodNode mth, RegionMaker regionMaker, IfRegionMaker ifMaker) {
55			this.mth = mth;
56			this.regionMaker = regionMaker;
57			this.ifMaker = ifMaker;
58		}
59	
60		BlockNode process(IRegion curRegion, LoopInfo loop, RegionStack stack) {
61			BlockNode loopStart = loop.getStart();
62			Set<BlockNode> exitBlocksSet = loop.getExitNodes();
63	
64			// set exit blocks scan order priority
65			// this can help if loop has several exits (after using 'break' or 'return' in loop)
66			List<BlockNode> exitBlocks = new ArrayList<>(exitBlocksSet.size());
67			BlockNode nextStart = getNextBlock(loopStart);
68			if (nextStart != null && exitBlocksSet.remove(nextStart)) {
69				exitBlocks.add(nextStart);
70			}
71			if (exitBlocksSet.remove(loopStart)) {
72				exitBlocks.add(loopStart);
73			}
74			if (exitBlocksSet.remove(loop.getEnd())) {
75				exitBlocks.add(loop.getEnd());
76			}
77			exitBlocks.addAll(exitBlocksSet);
78	
79			LoopRegion loopRegion = makeLoopRegion(curRegion, loop, exitBlocks);
80			if (loopRegion == null) {
81				BlockNode exit = makeEndlessLoop(curRegion, stack, loop, loopStart);
82				insertContinue(loop);
83				return exit;
84			}
85			curRegion.getSubBlocks().add(loopRegion);
86			IRegion outerRegion = stack.peekRegion();
87			stack.push(loopRegion);
88	
89			IfInfo condInfo = ifMaker.buildIfInfo(loopRegion);
90			if (!loop.getLoopBlocks().contains(condInfo.getThenBlock())) {
91				// invert loop condition if 'then' points to exit
92				condInfo = IfInfo.invert(condInfo);
93			}
94			loopRegion.updateCondition(condInfo);
95			// prevent if's merge with loop condition
96			condInfo.getMergedBlocks().forEach(b -> b.add(AFlag.ADDED_TO_REGION));
97			exitBlocks.removeAll(condInfo.getMergedBlocks().toList());
98	
99			if (!exitBlocks.isEmpty()) {
100	
101				// Blocks associated with the loop condition
102				List<BlockNode> loopConditionBlocks = loopRegion.getConditionBlocks();
103	
104				for (Edge exitEdge : loop.getExitEdges()) {
105					// An exit edge from the loop condition blocks
106					BlockNode exitSource = exitEdge.getSource();
107	
108					if (loopConditionBlocks.contains(exitSource)) {
109						BlockNode outBlock = followEmptyPath(exitEdge.getTarget());
110	
111						for (BlockNode pred : outBlock.getPredecessors()) {
112	
113							// Restarting search through exit edges from the beginning ("top")
114							for (Edge exitEdgeTop : loop.getExitEdges()) {
115	
116								if (!loopConditionBlocks.contains(exitEdgeTop.getSource())) {
117									if (isPathExists(exitEdgeTop.getTarget(), pred) || exitEdgeTop.getTarget() == outBlock) {
118										insertLoopBreak(stack, loop, outBlock, exitEdgeTop.getSource(), new Edge(pred, outBlock));
119									}
120								}
121							}
122						}
123	
124						// Exit edge found - no need to check further regardless of break outcome
125						break;
126					}
127				}
128			}
129	
130			BlockNode out;
131			if (loopRegion.isConditionAtEnd()) {
132				BlockNode thenBlock = condInfo.getThenBlock();
133				out = thenBlock == loop.getEnd() || thenBlock == loopStart ? condInfo.getElseBlock() : thenBlock;
134				out = BlockUtils.followEmptyPath(out);
135				loopStart.remove(AType.LOOP);
136				loop.getEnd().add(AFlag.ADDED_TO_REGION);
137				stack.addExit(loop.getEnd());
138				regionMaker.clearBlockProcessedState(loopStart);
139				Region body = regionMaker.makeRegion(loopStart);
140				loopRegion.setBody(body);
141				loopStart.addAttr(AType.LOOP, loop);
142				loop.getEnd().remove(AFlag.ADDED_TO_REGION);
143			} else {
144				out = condInfo.getElseBlock(); // Following Jadx convention, this must be the next synthetic block, not actual (theoretical) out
145												// block
146				if (outerRegion != null
147						&& out != null
148						&& out.contains(AFlag.LOOP_START)
149						&& !out.getAll(AType.LOOP).contains(loop)
150						&& RegionUtils.isRegionContainsBlock(outerRegion, out)) {
151					// exit to already processed outer loop
152					out = null;
153				}
154				stack.addExit(out);
155				BlockNode loopBody = condInfo.getThenBlock();
156				Region body;
157				if (Objects.equals(loopBody, loopStart)) {
158					// empty loop body
159					body = new Region(loopRegion);
160				} else {
161					body = regionMaker.makeRegion(loopBody);
162				}
163				// add blocks from loop start to first condition block
164				BlockNode conditionBlock = condInfo.getFirstIfBlock();
165				if (loopStart != conditionBlock) {
166					Set<BlockNode> blocks = BlockUtils.getAllPathsBlocks(loopStart, conditionBlock);
167					blocks.remove(conditionBlock);
168					for (BlockNode block : blocks) {
169						if (block.getInstructions().isEmpty()
170								&& !block.contains(AFlag.ADDED_TO_REGION)
171								&& !RegionUtils.isRegionContainsBlock(body, block)) {
172							body.add(block);
173						}
174					}
175				}
176				loopRegion.setBody(body);
177			}
178			stack.pop();
179			insertContinue(loop);
180			return out;
181		}
182	
183		/**
184		 * Select loop exit and construct LoopRegion
185		 */
186		private LoopRegion makeLoopRegion(IRegion curRegion, LoopInfo loop, List<BlockNode> exitBlocks) {
187			for (BlockNode block : exitBlocks) {
188				// Ignore blocks that lead to exception handlers
189				if (block.contains(AType.EXC_HANDLER)) {
190					continue;
191				}
192				// Ignore blocks that do not branch based on an if statement
193				InsnNode lastInsn = BlockUtils.getLastInsn(block);
194				if (lastInsn == null || lastInsn.getType() != InsnType.IF) {
195					continue;
196				}
197				// Skip any nested if statements
198				List<LoopInfo> loops = block.getAll(AType.LOOP);
199				if (!loops.isEmpty() && loops.get(0) != loop) {
200					// skip nested loop condition
201					continue;
202				}
203				boolean exitAtLoopEnd = isExitAtLoopEnd(block, loop);
204	
205				LoopRegion loopRegion = new LoopRegion(curRegion, loop, block, exitAtLoopEnd);
206	
207				boolean found;
208				if (block == loop.getStart() || exitAtLoopEnd || BlockUtils.isEmptySimplePath(loop.getStart(), block)) {
209					found = true;
210				} else if (block.getPredecessors().contains(loop.getStart())) {
211					loopRegion.setPreCondition(loop.getStart());
212					// if we can't merge pre-condition this is not correct header
213					found = loopRegion.checkPreCondition();
214				} else {
215					found = false;
216				}
217				if (found) {
218					List<LoopInfo> list = mth.getAllLoopsForBlock(block);
219					if (list.size() >= 2) {
220						// bad condition if successors going out of all loops
221						boolean allOuter = true;
222						for (BlockNode outerBlock : block.getCleanSuccessors()) {
223							List<LoopInfo> outLoopList = mth.getAllLoopsForBlock(outerBlock);
224							outLoopList.remove(loop);
225							if (!outLoopList.isEmpty()) {
226								// goes to outer loop
227								allOuter = false;
228								break;
229							}
230						}
231						if (allOuter) {
232							found = false;
233						}
234					}
235				}
236				if (found && !checkLoopExits(loop, block)) {
237					found = false;
238				}
239				if (found) {
240					return loopRegion;
241				}
242			}
243			// no exit found => endless loop
244			return null;
245		}
246	
247		private static boolean isExitAtLoopEnd(BlockNode exit, LoopInfo loop) {
248			BlockNode loopEnd = loop.getEnd();
249			if (exit == loopEnd) {
250				return true;
251			}
252			BlockNode loopStart = loop.getStart();
253			if (loopStart.getInstructions().isEmpty() && ListUtils.isSingleElement(loopStart.getSuccessors(), exit)) {
254				return false;
255			}
256			return loopEnd.getInstructions().isEmpty() && ListUtils.isSingleElement(loopEnd.getPredecessors(), exit);
257		}
258	
259		/*
260		 * Check that the exits suggested by treating mainExitBlock as the header block
261		 * are consistent with a loop condition
262		 */
263		private boolean checkLoopExits(LoopInfo loop, BlockNode mainExitBlock) {
264			List<Edge> exitEdges = loop.getExitEdges();
265			if (exitEdges.size() < 2) {
266				return true;
267			}
268			// If the header selected does not have an exit edge, raise an exception
269			Edge mainExitEdge = ListUtils.firstOrNull(exitEdges, edge -> edge.getSource() == mainExitBlock);
270			if (mainExitEdge == null) {
271				throw new JadxRuntimeException("Not found exit edge by exit block: " + mainExitBlock);
272			}
273			BlockNode mainOutBlock = mainExitEdge.getTarget();
274	
275			BlockNode firstWorkAfterMainExitBlock = BlockUtils.followEmptyPath(mainOutBlock);
276			List<InsnNode> firstInstructions = firstWorkAfterMainExitBlock.getInstructions();
277	
278			// If there is a direct path to a return from the header, all exits are inside the loop
279			if (firstInstructions.size() == 1 && firstInstructions.get(0).getType() == InsnType.RETURN) {
280				return true;
281			}
282	
283			// Otherwise the exit must lead to a valid out block
284			return validOutBlock(firstWorkAfterMainExitBlock, loop);
285		}
286	
287		/*
288		 * An out block is valid if every exit path passes through it or doesn't cross any other exit path
289		 * (permitting one block of duplication)
290		 * @param outblock The proposed region exit block
291		 * @param exitEdges All edges leaving a section at the start of the region e.g. edges leaving a loop
292		 * body
293		 */
294		private Boolean validOutBlock(BlockNode outBlock, LoopInfo loop) {
295			/*
296			 * Not permitted:
297			 * - An edge which cannot reach outblock, but does cross with another exit path
298			 * --- This crossing could be on a path that never reaches outblock
299			 * --- This crossing could be after outblock
300			 * - An edge which can reach outblock, but has another crossing with an exit path
301			 * --- This crossing could be before outblock
302			 * --- This crossing could be after outblock
303			 * --- This crossing could be on a branch that does not reach outblock
304			 * Permitted:
305			 * - If any of these inconsistent crossings occur at or near the method exit
306			 * - If the node can reach the outblock but has no crossing there because it dominates the outnode
307			 * - A number of other edge cases
308			 */
309			List<Edge> exitEdges = loop.getExitEdges();
310			Queue<Edge> edgesToCheck = new LinkedList<>(exitEdges);
311	
312			while (!edgesToCheck.isEmpty()) {
313				Edge exitEdge = edgesToCheck.remove();
314				BlockNode exitBlock = exitEdge.getTarget();
315	
316				// Get the dominance frontier of exitEdge.getTarget() only along paths through exitEdge
317	
318				List<BlockNode> dominanceFrontier;
319				if (!exitEdge.isSynthetic()) {
320					dominanceFrontier = BlockUtils.bitSetToBlocks(mth, BlockUtils.getDomFrontierThroughEdge(exitEdge));
321				} else {
322					dominanceFrontier = BlockUtils.bitSetToBlocks(mth, exitEdge.getTarget().getDomFrontier());
323				}
324	
325				if (outBlock.isDominator(exitBlock) || outBlock == exitBlock) {
326					// Accept if the loop exit block is a dominator of the suggested out block
327					continue;
328				}
329	
330				for (BlockNode crossing : dominanceFrontier) {
331					if (crossing == outBlock) {
332						// Accept if the crossing is at the outblock
333						continue;
334					}
335					if (BlockUtils.isExitBlock(mth, crossing)) {
336						// Accept if the crossing is at the method end
337						continue;
338					}
339	
340					// Find the first block after the crossing with instructions
341					BlockNode firstInstructionBlock = crossing;
342					List<InsnNode> cInsns = crossing.getInstructions();
343					if (cInsns.isEmpty()) {
344						firstInstructionBlock = BlockUtils.followEmptyPath(crossing);
345					}
346	
347					// Return false if the crossing doesn't satisfy any relevant edge case
348					if (!(viaValidUncleanSuccessor(exitBlock, crossing, loop)
349							|| noWorkBeforeEnd(firstInstructionBlock, outBlock)
350							|| oneBlockOfWorkBeforeEnd(firstInstructionBlock, outBlock)
351							|| isNestedIfCross(crossing, edgesToCheck)
352							|| isOuterOutblock(crossing, loop))) {
353						return false;
354					}
355				}
356			}
357			return true;
358		}
359	
360		/*
361		 * @param exitBlock the target of an exit edge
362		 * @param crossing the crossing block between exitBlock and a possible outblock
363		 * @param loop the loop
364		 */
365		private boolean viaValidUncleanSuccessor(BlockNode exitBlock, BlockNode crossing, LoopInfo loop) {
366			// Return true if the path from exitBlock is to an exception handler or via a backwards loop edge
367			// with continue
368	
369			if (isPathExists(exitBlock, crossing)) {
370				// This case does not apply if there is a path via clean successors
371				return false;
372			}
373	
374			// If to a loop start check if the backwards edge has a branch without a valid continue
375			if (crossing.contains(AFlag.LOOP_START)) {
376				// Note: This loop start cannot be for the internal loop else exitEdge would not leave the loop
377	
378				// Find the outer loop containing the loop start
379				LoopInfo parent = loop.getParentLoop();
380				LoopInfo outerLoop = null;
381				while (parent != null) {
382					if (parent.getStart() == crossing) {
383						outerLoop = parent;
384						break;
385					}
386					parent = parent.getParentLoop();
387				}
388	
389				if (outerLoop != null) {
390					BlockNode loopEnd = outerLoop.getEnd();
391					List<BlockNode> predecessors = loopEnd.getPredecessors();
392					if (predecessors.size() > 1) {
393						for (BlockNode predecessor : predecessors) {
394							// Do not accept if a predecessor to the loop end reachable from the exit would not have a
395							// continue inserted
396							if (BlockUtils.isPathExists(exitBlock, predecessor)
397									&& !canInsertContinue(predecessor, predecessors, loopEnd, outerLoop.getExitNodes())) {
398								return false;
399							}
400						}
401					} else {
402						// Do not accept if no continues would be placed
403						return false;
404					}
405				}
406	
407			}
408	
409			// Accept if all branches have a valid continue or if not to a loop start (to an exception handler)
410			return true;
411		}
