413		/*
414		 * @param firstInstructionBlock the first block containing instructions off the main loop body
415		 * @param outBlock a possible outblock of the loop
416		 */
417		private boolean noWorkBeforeEnd(BlockNode firstInstructionBlock, BlockNode outBlock) {
418			// Return true if there is no work between the crossing and an exit block
419			return (BlockUtils.isExitBlock(mth, firstInstructionBlock) || firstInstructionBlock == outBlock);
420		}
