422		/*
423		 * @param firstInstructionBlock the first block containing instructions off the main loop body
424		 * @param outBlock a possible outblock of the loop
425		 */
426		private boolean oneBlockOfWorkBeforeEnd(BlockNode firstInstructionBlock, BlockNode outBlock) {
427			// Return true if down every path there is no more than one block of work between the crossing and
428			// an exit block
429			List<BlockNode> cleanSuccessors = firstInstructionBlock.getCleanSuccessors();
430			if (cleanSuccessors.isEmpty()) {
431				return false;
432			}
433			for (BlockNode cleanSuccessor : cleanSuccessors) {
434				BlockNode nextInstructionBlock = BlockUtils.followEmptyPath(cleanSuccessor);
435				if (!BlockUtils.isExitBlock(mth, nextInstructionBlock) && nextInstructionBlock != outBlock) {
436					return false;
437				}
438			}
439			return true;
440		}
