442		/*
443		 * @param crossing the block that may be the joint block of a merged if
444		 * @param edgesToCheck the list of edges that will be processed to add to
445		 */
446		private boolean isNestedIfCross(BlockNode crossing, Queue<Edge> edgesToCheck) {
447			// Return true if the crossing is due to merged control flow after a nested if
448			// Add the edges out of the crossing to be investigated
449	
450			// If the crossing is the branch of a merged if, all predecessors will be synthetic up to the if
451			// statements, and the first if statement will dominate the crossing
452			List<BlockNode> predecessors = crossing.getPredecessors();
453	
454			// Find a predecessor that dominates all other predecessors
455			BlockNode possibleFirstIF = BlockUtils.followEmptyPath(predecessors.get(0), true);
456			for (BlockNode predecessor : predecessors) {
457				// Follow the predecessor up to the first node with instructions
458				BlockNode possibleIF = followEmptyPath(predecessor, true);
459				if (crossing.isDominator(possibleIF)) {
460					possibleFirstIF = possibleIF;
461				}
462			}
463	
464			// This case does not apply if a merged if cannot be made
465			IfInfo currentIf = IfRegionMaker.makeIfInfo(mth, possibleFirstIF);
466			if (currentIf == null) {
467				return false;
468			}
469	
470			IfInfo mergedIf = IfRegionMaker.mergeNestedIfNodes(currentIf);
471			if (mergedIf == null) {
472				return false;
473			}
474	
475			// Note: work will be repeated for large merged ifs. Results could be cached to improve performance
476			// Accept if following every predecessor path from the crossing reaches a merged if node
477			BlockSet mergedBlocks = mergedIf.getMergedBlocks();
478			for (BlockNode predecessor : predecessors) {
479				BlockNode possibleIF = followEmptyPath(predecessor, true);
480				if (!mergedBlocks.contains(possibleIF)) {
481					return false;
482				}
483			}
484	
485			// If this crossing is the result of merged ifs, check the next crossing after this one
486			Edge placeHolderEdge = new Edge(crossing, crossing, true);
487			if (!edgesToCheck.contains(placeHolderEdge)) {
488				edgesToCheck.add(placeHolderEdge);
489			}
490	
491			return true;
492		}
