494		/*
495		 * @param crossing the block that may be an outblock for a parent loop
496		 * @param loop the inner loop currently being considered
497		 */
498		private boolean isOuterOutblock(BlockNode crossing, LoopInfo loop) {
499			// Return true if the crossing is the outblock for an outer loop and is jumped to using a labelled
500			// break
501	
502			List<EdgeInsnAttr> edgeInsns = crossing.getAll(AType.EDGE_INSN);
503			for (EdgeInsnAttr edgeInsn : edgeInsns) {
504				InsnNode insn = edgeInsn.getInsn();
505				// If there is a break edge instruction
506				if (insn.getType() == InsnType.BREAK) {
507					List<LoopInfo> loopsBrokenFrom = insn.get(AType.LOOP).getList();
508					for (LoopInfo loopBrokenFrom : loopsBrokenFrom) {
509						// If it is for a parent of the current loop
510						if (loop.hasParent(loopBrokenFrom)) {
511							BlockNode target = edgeInsn.getEnd();
512							// If it points at the crossing
513							if (target == crossing) {
514								// Accept if the crossing block is already the target of a break instruction from a parent loop
515								return true;
516							}
517						}
518					}
519				}
520			}
521			return false;
522		}
