524		private BlockNode makeEndlessLoop(IRegion curRegion, RegionStack stack, LoopInfo loop, BlockNode loopStart) {
525			LoopRegion loopRegion = new LoopRegion(curRegion, loop, null, false);
526			curRegion.getSubBlocks().add(loopRegion);
527	
528			loopStart.remove(AType.LOOP);
529			regionMaker.clearBlockProcessedState(loopStart);
530			stack.push(loopRegion);
531	
532			BlockNode out = null;
533			// insert 'break' for exits
534			List<Edge> exitEdges = loop.getExitEdges();
535			if (exitEdges.size() == 1) {
536				Edge exitEdge = exitEdges.get(0);
537				BlockNode exit = exitEdge.getTarget();
538				if (insertLoopBreak(stack, loop, exit, exitEdge.getSource(), exitEdge)) {
539					BlockNode nextBlock = getNextBlock(exit);
540					if (nextBlock != null) {
541						stack.addExit(nextBlock);
542						out = nextBlock;
543					}
544				}
545			} else {
546				loop0: for (Edge exitEdge : exitEdges) {
547					BlockNode exit = exitEdge.getTarget();
548					List<BlockNode> blocks = BlockUtils.bitSetToBlocks(mth, BlockUtils.getDomFrontierThroughEdge(exitEdge));
549	
550					// Only select the method exit if there is no other valid outblock
551					BlockNode methodExit = mth.getExitBlock();
552					if (blocks.contains(methodExit)) {
553						blocks.remove(methodExit);
554						blocks.add(methodExit);
555					}
556					for (BlockNode block : blocks) {
557						if (BlockUtils.isPathExists(exit, block)) {
558							if (validOutBlock(block, loop)) {
559								out = block;
560								break loop0;
561							}
562						} else if (block.contains(AFlag.LOOP_START)) {
563							// Special case if there is no joining control flow before an outer loop back edge
564							if (validOutBlock(exit, loop)) {
565								out = exit;
566								break loop0;
567							}
568						}
569					}
570				}
571	
572				// Add breaks
573				stack.addExit(out);
574				if (out != null && out != mth.getExitBlock()) {
575					// Add a break on every incoming edge where the predecessor is reachable from the loop
576					for (BlockNode predecessor : out.getPredecessors()) {
577						for (Edge exitEdge : loop.getExitEdges()) {
578							BlockNode target = exitEdge.getTarget();
579							if (BlockUtils.isPathExists(exitEdge.getTarget(), predecessor) || target == out) {
580								insertLoopBreak(stack, loop, out, exitEdge.getSource(), new Edge(predecessor, out));
581							}
582						}
583					}
584				}
585			}
586	
587			Region body = regionMaker.makeRegion(loopStart);
588			BlockNode loopEnd = loop.getEnd();
589			if (!RegionUtils.isRegionContainsBlock(body, loopEnd)
590					&& !loopEnd.contains(AType.EXC_HANDLER)
591					&& !inExceptionHandlerBlocks(loopEnd)) {
592				body.getSubBlocks().add(loopEnd);
593			}
594			loopRegion.setBody(body);
595	
596			if (out == null) {
597				BlockNode next = getNextBlock(loopEnd);
598				out = RegionUtils.isRegionContainsBlock(body, next) ? null : next;
599			}
600			stack.pop();
601			loopStart.addAttr(AType.LOOP, loop);
602			return out;
603		}
604	
605		private boolean inExceptionHandlerBlocks(BlockNode loopEnd) {
606			if (mth.getExceptionHandlersCount() == 0) {
607				return false;
608			}
609			for (ExceptionHandler eh : mth.getExceptionHandlers()) {
610				if (eh.getBlocks().contains(loopEnd)) {
611					return true;
612				}
613			}
614			return false;
615		}
