617		private boolean canInsertBreak(BlockNode exit) {
618			if (BlockUtils.containsExitInsn(exit)) {
619				return false;
620			}
621			List<BlockNode> simplePath = BlockUtils.buildSimplePath(exit);
622			if (!simplePath.isEmpty()) {
623				BlockNode lastBlock = simplePath.get(simplePath.size() - 1);
624				if (lastBlock.isMthExitBlock()
625						|| lastBlock.isReturnBlock()
626						|| mth.isPreExitBlock(lastBlock)) {
627					return false;
628				}
629			}
630			// check if there no outer switch (TODO: very expensive check)
631			Set<BlockNode> paths = BlockUtils.getAllPathsBlocks(mth.getEnterBlock(), exit);
632			for (BlockNode block : paths) {
633				if (BlockUtils.checkLastInsnType(block, InsnType.SWITCH)) {
634					return false;
635				}
636			}
637			return true;
638		}
639	
640		/*
641		 * Insert a break instruction where exitEdge meets loopExit
642		 * @param stack the region stack
643		 * @param loop the loop being broken out of
644		 * @param loopExit the outblock for loop
645		 * @param blockOnLoop an exit block on loop through which exitEdge is reachable
646		 * @param exitEdge an edge on the path between blockOnLoop and loopExit indicative of the breaking
647		 * path
648		 */
649		private boolean insertLoopBreak(RegionStack stack, LoopInfo loop, BlockNode loopExit, BlockNode blockOnLoop, Edge exitEdge) {
650			BlockNode exit = exitEdge.getTarget();
651			Edge insertEdge = null;
652			boolean confirm = false;
653			// process special cases:
654			// 1. jump to outer loop
655			BlockNode exitEnd = BlockUtils.followEmptyPath(exit);
656			List<LoopInfo> loops = exitEnd.getAll(AType.LOOP);
657			for (LoopInfo loopAtEnd : loops) {
658				if (loopAtEnd != loop && loop.hasParent(loopAtEnd)) {
659					insertEdge = exitEdge;
660					confirm = true;
661					break;
662				}
663			}
664	
665			if (!confirm) {
666				// Start search from the next edge if the target is simple (e.g. first
667				// node after loop exit)
668				Boolean isSimple = BlockUtils.followEmptyPath(exit) != exit;
669				BlockNode insertBlock = isSimple ? null : exitEdge.getSource();
670				BlockSet visited = new BlockSet(mth);
671				while (true) {
672					if (exit == null || visited.contains(exit)) {
673						break;
674					}
675					visited.add(exit);
676					if (insertBlock != null && isPathExists(loopExit, exit)) {
677						// found cross
678						if (canInsertBreak(insertBlock)) {
679							insertEdge = new Edge(insertBlock, exit);
680							confirm = true;
681							break;
682						}
683						return false;
684					}
685					insertBlock = exit;
686					List<BlockNode> cs = exit.getCleanSuccessors();
687					exit = cs.size() == 1 ? cs.get(0) : null;
688				}
689			}
690			if (!confirm) {
691				return false;
692			}
693			InsnNode breakInsn = new InsnNode(InsnType.BREAK, 0);
694			breakInsn.addAttr(AType.LOOP, loop);
695			EdgeInsnAttr.addEdgeInsn(insertEdge, breakInsn);
696			stack.addExit(exit);
697			// add label to 'break' if needed
698			addBreakLabel(blockOnLoop, exit, breakInsn);
699			return true;
700		}
701	
702		/*
703		 * Adds a label to a break instruction if reaching the exit from the loop involves leaving multiple
704		 * loops
705		 * @param blockOnLoop the exit block on the loop to which breakInsn is currently associated
706		 * @param exit the out block of the loop to which breakInsn is currently associated
707		 * @param breakInsn a break instruction
708		 */
709		private void addBreakLabel(BlockNode blockOnLoop, BlockNode exit, InsnNode breakInsn) {
710			List<LoopInfo> exitLoop = mth.getAllLoopsForBlock(exit);
711			if (!exitLoop.isEmpty()) {
712				return;
713			}
714			List<LoopInfo> inLoops = mth.getAllLoopsForBlock(blockOnLoop);
715			if (inLoops.size() < 2) {
716				return;
717			}
718			// search for parent loop
719			LoopInfo parentLoop = null;
720			for (LoopInfo loop : inLoops) {
721				if (loop.getParentLoop() == null) {
722					parentLoop = loop;
723					break;
724				}
725			}
726			if (parentLoop == null) {
727				return;
728			}
729			if (parentLoop.getEnd() != exit && !parentLoop.getExitNodes().contains(exit)) {
730				LoopLabelAttr labelAttr = new LoopLabelAttr(parentLoop);
731				breakInsn.addAttr(labelAttr);
732				parentLoop.getStart().addAttr(labelAttr);
733			}
734		}
735	
736		private static void insertContinue(LoopInfo loop) {
737			BlockNode loopEnd = loop.getEnd();
738			List<BlockNode> predecessors = loopEnd.getPredecessors();
739			if (predecessors.size() <= 1) {
740				return;
741			}
742			Set<BlockNode> loopExitNodes = loop.getExitNodes();
743			for (BlockNode pred : predecessors) {
744				if (canInsertContinue(pred, predecessors, loopEnd, loopExitNodes)) {
745					InsnNode cont = new InsnNode(InsnType.CONTINUE, 0);
746					pred.getInstructions().add(cont);
747				}
748			}
749		}
750	
751		private static boolean canInsertContinue(BlockNode pred, List<BlockNode> predecessors, BlockNode loopEnd,
752				Set<BlockNode> loopExitNodes) {
753			if (!pred.contains(AFlag.SYNTHETIC)
754					|| BlockUtils.checkLastInsnType(pred, InsnType.CONTINUE)) {
755				return false;
756			}
757			List<BlockNode> preds = pred.getPredecessors();
758			if (preds.isEmpty()) {
759				return false;
760			}
761			BlockNode codePred = preds.get(0);
762			if (codePred.contains(AFlag.ADDED_TO_REGION)) {
763				return false;
764			}
765			if (loopEnd.isDominator(codePred)
766					|| loopExitNodes.contains(codePred)) {
767				return false;
768			}
769			if (isDominatedOnBlocks(codePred, predecessors)) {
770				return false;
771			}
772			if (!pred.getAll(AType.EDGE_INSN).isEmpty()) {
773				// if we've already inserted a break, don't also insert a continue in the same spot
774				List<EdgeInsnAttr> insns = pred.getAll(AType.EDGE_INSN);
775				for (EdgeInsnAttr insn : insns) {
776					if (insn.getInsn().getType() == InsnType.BREAK) {
777						return false;
778					}
779				}
780			}
781			boolean gotoExit = false;
782			for (BlockNode exit : loopExitNodes) {
783				if (BlockUtils.isPathExists(codePred, exit)) {
784					gotoExit = true;
785					break;
786				}
787			}
788			return gotoExit;
789		}
790	
791		private static boolean isDominatedOnBlocks(BlockNode dom, List<BlockNode> blocks) {
792			for (BlockNode node : blocks) {
793				if (!node.isDominator(dom)) {
794					return false;
795				}
796			}
797			return true;
798		}
799	}
