52		BlockNode process(IRegion currentRegion, BlockNode block, SwitchInsn insn, RegionStack stack) {
53			// map case blocks to keys
54			int len = insn.getTargets().length;
55			Map<BlockNode, List<Object>> blocksMap = new LinkedHashMap<>(len);
56			BlockNode[] targetBlocksArr = insn.getTargetBlocks();
57			for (int i = 0; i < len; i++) {
58				List<Object> keys = blocksMap.computeIfAbsent(targetBlocksArr[i], k -> new ArrayList<>(2));
59				keys.add(insn.getKey(i));
60			}
61			BlockNode defCase = insn.getDefTargetBlock();
62			if (defCase != null) {
63				List<Object> keys = blocksMap.computeIfAbsent(defCase, k -> new ArrayList<>(1));
64				keys.add(SwitchRegion.DEFAULT_CASE_KEY);
65			}
66	
67			SwitchRegion sw = new SwitchRegion(currentRegion, block);
68			insn.addAttr(new RegionRefAttr(sw));
69			currentRegion.getSubBlocks().add(sw);
70			stack.push(sw);
71	
72			BlockNode out = calcSwitchOut(block, insn, stack);
73			stack.addExit(out);
74	
75			addCases(sw, out, stack, blocksMap);
76			removeEmptyCases(insn, sw, defCase, out);
77	
78			stack.pop();
79			return out;
80		}

80		}
