82		/**
83		 * Insert 'break' for all cases in switch region
84		 * Executed in {@link jadx.core.dex.visitors.regions.PostProcessRegions} after try/catch wrap to
85		 * handle all blocks
86		 */
87		public static void insertBreaks(MethodNode mth, SwitchRegion sw) {
88			for (SwitchRegion.CaseInfo caseInfo : sw.getCases()) {
89				insertBreaksForCase(mth, sw, caseInfo.getContainer());
90			}
91		}
