93		private void addCases(SwitchRegion sw, @Nullable BlockNode out,
94				RegionStack stack, Map<BlockNode, List<Object>> blocksMap) {
95			Map<BlockNode, BlockNode> fallThroughCases = new LinkedHashMap<>();
96			if (out != null) {
97				// detect fallthrough cases
98				BitSet caseBlocks = BlockUtils.blocksToBitSet(mth, blocksMap.keySet());
99				caseBlocks.clear(out.getPos());
100				for (BlockNode successor : sw.getHeader().getSuccessors()) {
101					BitSet df = successor.getDomFrontier();
102					if (df.intersects(caseBlocks)) {
103						BlockNode fallThroughBlock = getOneIntersectionBlock(out, caseBlocks, df);
104						fallThroughCases.put(successor, fallThroughBlock);
105					}
106				}
107				// check fallthrough cases order
108				if (!fallThroughCases.isEmpty() && isBadCasesOrder(blocksMap, fallThroughCases)) {
109					Map<BlockNode, List<Object>> newBlocksMap = reOrderSwitchCases(blocksMap, fallThroughCases);
110					if (isBadCasesOrder(newBlocksMap, fallThroughCases)) {
111						mth.addWarnComment("Can't fix incorrect switch cases order, some code will duplicate");
112						fallThroughCases.clear();
113					} else {
114						blocksMap = newBlocksMap;
115					}
116				}
117			}
118			for (Map.Entry<BlockNode, List<Object>> entry : blocksMap.entrySet()) {
119				List<Object> keysList = entry.getValue();
120				BlockNode caseBlock = entry.getKey();
121				Region caseRegion;
122				if (stack.containsExit(caseBlock)) {
123					caseRegion = new Region(stack.peekRegion());
124				} else {
125					BlockNode next = fallThroughCases.get(caseBlock);
126					stack.addExit(next);
127					caseRegion = regionMaker.makeRegion(caseBlock);
128					stack.removeExit(next);
129					if (next != null) {
130						next.add(AFlag.FALL_THROUGH);
131						caseRegion.add(AFlag.FALL_THROUGH);
132					}
133				}
134				sw.addCase(keysList, caseRegion);
135			}
136		}
