138		@Nullable
139		private BlockNode getOneIntersectionBlock(BlockNode out, BitSet caseBlocks, BitSet fallThroughSet) {
140			BitSet caseExits = BlockUtils.copyBlocksBitSet(mth, fallThroughSet);
141			caseExits.clear(out.getPos());
142			caseExits.and(caseBlocks);
143			return BlockUtils.bitSetToOneBlock(mth, caseExits);
144		}
