146		private @Nullable BlockNode calcSwitchOut(BlockNode block, SwitchInsn insn, RegionStack stack) {
147			// union of case blocks dominance frontier
148			// works if no fallthrough cases and no returns inside switch
149			BitSet outs = BlockUtils.newBlocksBitSet(mth);
150			for (BlockNode s : block.getCleanSuccessors()) {
151				if (s.contains(AFlag.LOOP_END)) {
152					// loop end dom frontier is loop start, ignore it
153					continue;
154				}
155				outs.or(s.getDomFrontier());
156			}
157			outs.clear(block.getId());
158			outs.clear(mth.getExitBlock().getId());
159	
160			BlockNode out = null;
161			if (outs.cardinality() == 1) {
162				// single exit
163				out = BlockUtils.bitSetToOneBlock(mth, outs);
164			} else {
165				// several switch exits
166				// possible 'return', 'continue' or fallthrough in one of the cases
167				LoopInfo loop = mth.getLoopForBlock(block);
168				if (loop != null) {
169					outs.andNot(loop.getStart().getPostDoms());
170					outs.andNot(loop.getEnd().getPostDoms());
171					BlockNode loopEnd = loop.getEnd();
172					if (outs.cardinality() == 2 && outs.get(loopEnd.getId())) {
173						// insert 'continue' for cases lead to loop end
174						// expect only 2 exits: loop end and switch out
175						List<BlockNode> outList = BlockUtils.bitSetToBlocks(mth, outs);
176						outList.remove(loopEnd);
177						BlockNode possibleOut = Utils.getOne(outList);
178						if (possibleOut != null && insertContinueInSwitch(block, possibleOut, loopEnd)) {
179							outs.clear(loopEnd.getId());
180							out = possibleOut;
181						}
182					}
