39	public class BlockProcessor extends AbstractVisitor {
40		private static final Logger LOG = LoggerFactory.getLogger(BlockProcessor.class);
41	
42		private static final boolean DEBUG_MODS = false;
43	
44		@Override
45		public void visit(MethodNode mth) {
46			if (mth.isNoCode() || mth.getBasicBlocks().isEmpty()) {
47				return;
48			}
49			processBlocksTree(mth);
50		}
51	
52		private static void processBlocksTree(MethodNode mth) {
53			removeUnreachableBlocks(mth);
54	
55			computeDominators(mth);
56			if (independentBlockTreeMod(mth)) {
57				checkForUnreachableBlocks(mth);
58				computeDominators(mth);
59			}
60			if (FixMultiEntryLoops.process(mth)) {
61				computeDominators(mth);
62			}
63			updateCleanSuccessors(mth);
64	
65			int blocksCount = mth.getBasicBlocks().size();
66			int modLimit = Math.max(100, blocksCount);
67			if (DEBUG_MODS) {
68				mth.addAttr(new DebugModAttr());
69			}
70			int i = 0;
71			while (modifyBlocksTree(mth)) {
72				computeDominators(mth);
73				if (i++ > modLimit) {
74					mth.addWarn("CFG modification limit reached, blocks count: " + blocksCount);
75					break;
76				}
77			}
78			if (DEBUG_MODS && i != 0) {
79				String stats = "CFG modifications count: " + i
80						+ ", blocks count: " + blocksCount + '\n'
81						+ mth.get(DebugModAttr.TYPE).formatStats() + '\n';
82				mth.addDebugComment(stats);
83				LOG.debug("Method: {}\n{}", mth, stats);
84				mth.remove(DebugModAttr.TYPE);
85			}
86			checkForUnreachableBlocks(mth);
87	
88			DominatorTree.computeDominanceFrontier(mth);
89			registerLoops(mth);
90			processNestedLoops(mth);
91	
92			PostDominatorTree.compute(mth);
93	
94			updateCleanSuccessors(mth);
95		}
96	
97		/**
98		 * Recalculate all additional info attached to blocks:
99		 *
100		 * <pre>
101		 * - dominators
102		 * - dominance frontier
103		 * - post dominators (only if {@link AFlag#COMPUTE_POST_DOM} added to method)
104		 * - loops and nested loop info
105		 * </pre>
106		 * <p>
107		 * This method should be called after changing a block tree in custom passes added before
108		 * {@link BlockFinisher}.
109		 */
110		public static void updateBlocksData(MethodNode mth) {
111			clearBlocksState(mth);
112			DominatorTree.compute(mth);
113			markLoops(mth);
114	
115			DominatorTree.computeDominanceFrontier(mth);
116			registerLoops(mth);
117			processNestedLoops(mth);
118	
119			PostDominatorTree.compute(mth);
120	
121			updateCleanSuccessors(mth);
122		}
123	
124		static void updateCleanSuccessors(MethodNode mth) {
125			mth.getBasicBlocks().forEach(BlockNode::updateCleanSuccessors);
126		}
127	
128		private static void checkForUnreachableBlocks(MethodNode mth) {
129			while (true) {
130				boolean fixed = false;
131				for (BlockNode block : mth.getBasicBlocks()) {
132					if (block.getPredecessors().isEmpty() && block != mth.getEnterBlock()) {
133						// Sometimes a split cross block will have all it's predecessors moved elsewhere after it's been
134						// created. This is usually detected at the time of it's creation, but in certain edge cases it
135						// is difficult to do so. In those cases it will be cleanly removed here, along with the associated
136						// bottom splitter.
137						if (block.contains(AType.EXC_SPLIT_CROSS) && fixUnreachableSplitCross(mth, block)) {
138							mth.addInfoComment("Removed unreachable split cross block " + block);
139							fixed = true;
140							break;
141						}
142						throw new JadxRuntimeException("Unreachable block: " + block);
143					}
144				}
145				if (!fixed) {
146					break;
147				}
148			}
149		}
150	
151		/**
152		 * Attempts to remove an unreachable synthetic split cross block that has been added previously,
153		 * along with the associated bottom splitter.
154		 *
155		 * @param mth        the method containing the unreachable block
156		 * @param splitCross the unreachable block
157		 * @return true if the operation was successful, false if a precondition was not satisfied and no
158		 *         changes were made.
159		 */
160		private static boolean fixUnreachableSplitCross(MethodNode mth, BlockNode splitCross) {
161			BlockNode bottomSplitter = null;
162			for (BlockNode succ : splitCross.getSuccessors()) {
163				if (succ.contains(AFlag.EXC_BOTTOM_SPLITTER)) {
164					bottomSplitter = succ;
165					break;
166				}
167			}
168			if (bottomSplitter == null || bottomSplitter.getPredecessors().size() != 1) {
169				return false;
170			}
171			Set<BlockNode> removeSet = new HashSet<>();
172			removeSet.add(bottomSplitter);
173			removeSet.add(splitCross);
174			removeFromMethod(removeSet, mth);
175			return true;
176		}
177	
178		private static boolean deduplicateBlockInsns(MethodNode mth, BlockNode block) {
179			if (block.contains(AFlag.LOOP_START) || block.contains(AFlag.LOOP_END)) {
180				// search for same instruction at end of all predecessors blocks
181				List<BlockNode> predecessors = block.getPredecessors();
182				int predsCount = predecessors.size();
183				if (predsCount > 1) {
184					InsnNode lastInsn = BlockUtils.getLastInsn(block);
185					if (lastInsn != null && lastInsn.getType() == InsnType.IF) {
186						return false;
187					}
188					if (BlockUtils.checkFirstInsn(block, insn -> insn.contains(AType.EXC_HANDLER))) {
189						return false;
190					}
191					// TODO: implement insn extraction into separate block for partial predecessors
192					int sameInsnCount = getSameLastInsnCount(predecessors);
193					if (sameInsnCount > 0) {
194						List<InsnNode> insns = getLastInsns(predecessors.get(0), sameInsnCount);
195						insertAtStart(block, insns);
196						predecessors.forEach(pred -> getLastInsns(pred, sameInsnCount).clear());
197						mth.addDebugComment("Move duplicate insns, count: " + sameInsnCount + " to block " + block);
198						return true;
199					}
200				}
201			}
202			return false;
203		}
204	
205		private static List<InsnNode> getLastInsns(BlockNode blockNode, int sameInsnCount) {
206			List<InsnNode> instructions = blockNode.getInstructions();
207			int size = instructions.size();
208			return instructions.subList(size - sameInsnCount, size);
209		}
210	
211		private static void insertAtStart(BlockNode block, List<InsnNode> insns) {
212			List<InsnNode> blockInsns = block.getInstructions();
213	
214			List<InsnNode> newInsnList = new ArrayList<>(insns.size() + blockInsns.size());
215			newInsnList.addAll(insns);
216			newInsnList.addAll(blockInsns);
217	
218			blockInsns.clear();
219			blockInsns.addAll(newInsnList);
220		}
221	
222		private static int getSameLastInsnCount(List<BlockNode> predecessors) {
223			int sameInsnCount = 0;
224			while (true) {
225				InsnNode insn = null;
226				for (BlockNode pred : predecessors) {
227					InsnNode curInsn = getInsnsFromEnd(pred, sameInsnCount);
228					if (curInsn == null) {
229						return sameInsnCount;
230					}
231					if (insn == null) {
232						insn = curInsn;
233					} else {
234						if (!isSame(insn, curInsn)) {
235							return sameInsnCount;
236						}
237					}
238				}
239				sameInsnCount++;
240			}
241		}
242	
243		private static boolean isSame(InsnNode insn, InsnNode curInsn) {
244			return isInsnsEquals(insn, curInsn) && insn.canReorder();
245		}
246	
247		private static boolean isInsnsEquals(InsnNode insn, InsnNode otherInsn) {
248			if (insn == otherInsn) {
249				return true;
250			}
251			if (insn.isSame(otherInsn)
252					&& sameArgs(insn.getResult(), otherInsn.getResult())) {
253				int argsCount = insn.getArgsCount();
254				for (int i = 0; i < argsCount; i++) {
255					if (!sameArgs(insn.getArg(i), otherInsn.getArg(i))) {
256						return false;
257					}
258				}
259				return true;
260			}
261			return false;
262		}
263	
264		private static boolean sameArgs(@Nullable InsnArg arg, @Nullable InsnArg otherArg) {
265			if (arg == otherArg) {
266				return true;
267			}
268			if (arg == null || otherArg == null) {
269				return false;
270			}
271			if (arg.getClass().equals(otherArg.getClass())) {
272				if (arg.isRegister()) {
273					return ((RegisterArg) arg).getRegNum() == ((RegisterArg) otherArg).getRegNum();
274				}
275				if (arg.isLiteral()) {
276					return ((LiteralArg) arg).getLiteral() == ((LiteralArg) otherArg).getLiteral();
277				}
278				throw new JadxRuntimeException("Unexpected InsnArg types: " + arg + " and " + otherArg);
279			}
280			return false;
281		}
282	
283		private static InsnNode getInsnsFromEnd(BlockNode block, int number) {
284			List<InsnNode> instructions = block.getInstructions();
285			int insnCount = instructions.size();
286			if (insnCount <= number) {
287				return null;
288			}
289			return instructions.get(insnCount - number - 1);
290		}
291	
292		private static void computeDominators(MethodNode mth) {
293			clearBlocksState(mth);
294			DominatorTree.compute(mth);
295			markLoops(mth);
296		}
297	
298		private static void markLoops(MethodNode mth) {
299			mth.getBasicBlocks().forEach(block -> {
300				// Every successor that dominates its predecessor is a header of a loop,
301				// block -> successor is a back edge.
302				block.getSuccessors().forEach(successor -> {
303					if (block.getDoms().get(successor.getId()) || block == successor) {
304						successor.add(AFlag.LOOP_START);
305						block.add(AFlag.LOOP_END);
306	
307						Set<BlockNode> loopBlocks = BlockUtils.getAllPathsBlocks(successor, block);
308						LoopInfo loop = new LoopInfo(successor, block, loopBlocks);
309						successor.addAttr(AType.LOOP, loop);
310						block.addAttr(AType.LOOP, loop);
311					}
312				});
313			});
314		}
315	
316		private static void registerLoops(MethodNode mth) {
317			mth.resetLoops();
318			mth.getBasicBlocks().forEach(block -> {
319				if (block.contains(AFlag.LOOP_START)) {
320					block.getAll(AType.LOOP).forEach(mth::registerLoop);
321				}
322			});
323		}
324	
325		private static void processNestedLoops(MethodNode mth) {
326			if (mth.getLoopsCount() == 0) {
327				return;
328			}
329			for (LoopInfo outLoop : mth.getLoops()) {
330				for (LoopInfo innerLoop : mth.getLoops()) {
331					if (outLoop == innerLoop) {
332						continue;
333					}
334					if (outLoop.getLoopBlocks().containsAll(innerLoop.getLoopBlocks())) {
335						LoopInfo parentLoop = innerLoop.getParentLoop();
336						if (parentLoop != null) {
337							if (parentLoop.getLoopBlocks().containsAll(outLoop.getLoopBlocks())) {
338								outLoop.setParentLoop(parentLoop);
339								innerLoop.setParentLoop(outLoop);
340							} else {
341								parentLoop.setParentLoop(outLoop);
342							}
343						} else {
344							innerLoop.setParentLoop(outLoop);
345						}
346					}
347				}
348			}
349		}
350	
351		private static boolean modifyBlocksTree(MethodNode mth) {
352			for (BlockNode block : mth.getBasicBlocks()) {
353				if (checkLoops(mth, block)) {
354					return true;
355				}
356			}
357			if (mergeConstReturn(mth)) {
358				return true;
359			}
360			if (CodeFeaturesAttr.contains(mth, CodeFeaturesAttr.CodeFeature.SWITCH)) {
361				for (BlockNode basicBlock : mth.getBasicBlocks()) {
362					if (duplicateSimpleMoveBlock(mth, basicBlock)) {
363						return true;
364					}
365				}
366			}
367			return splitExitBlocks(mth);
368		}
369	
370		private static boolean mergeConstReturn(MethodNode mth) {
371			if (mth.isVoidReturn()) {
372				return false;
373			}
374			boolean changed = false;
375			for (BlockNode retBlock : new ArrayList<>(mth.getPreExitBlocks())) {
376				BlockNode pred = Utils.getOne(retBlock.getPredecessors());
377				if (pred != null) {
378					InsnNode constInsn = Utils.getOne(pred.getInstructions());
379					if (constInsn != null && constInsn.isConstInsn()) {
380						RegisterArg constArg = constInsn.getResult();
381						InsnNode returnInsn = BlockUtils.getLastInsn(retBlock);
382						if (returnInsn != null && returnInsn.getType() == InsnType.RETURN) {
383							InsnArg retArg = returnInsn.getArg(0);
384							if (constArg.sameReg(retArg)) {
385								mergeConstAndReturnBlocks(mth, retBlock, pred);
386								changed = true;
387							}
388						}
389					}
390				}
391			}
392			if (changed) {
393				removeMarkedBlocks(mth);
394				if (DEBUG_MODS) {
395					mth.get(DebugModAttr.TYPE).addEvent("Merge const return");
396				}
397			}
398			return changed;
399		}
400	
401		private static void mergeConstAndReturnBlocks(MethodNode mth, BlockNode retBlock, BlockNode pred) {
402			pred.getInstructions().addAll(retBlock.getInstructions());
403			pred.copyAttributesFrom(retBlock);
404			BlockSplitter.removeConnection(pred, retBlock);
405			retBlock.getInstructions().clear();
406			retBlock.add(AFlag.REMOVE);
407			BlockNode exitBlock = mth.getExitBlock();
408			BlockSplitter.removeConnection(retBlock, exitBlock);
409			BlockSplitter.connect(pred, exitBlock);
410			pred.updateCleanSuccessors();
411		}
412	
413		private static boolean independentBlockTreeMod(MethodNode mth) {
414			boolean changed = false;
415			List<BlockNode> basicBlocks = mth.getBasicBlocks();
416			for (BlockNode basicBlock : basicBlocks) {
417				if (deduplicateBlockInsns(mth, basicBlock)) {
418					changed = true;
419				}
420			}
421			if (BlockExceptionHandler.process(mth)) {
422				changed = true;
423			}
424			for (BlockNode basicBlock : basicBlocks) {
425				if (BlockSplitter.removeEmptyBlock(basicBlock)) {
426					changed = true;
427				}
428			}
429			if (BlockSplitter.removeEmptyDetachedBlocks(mth)) {
430				changed = true;
431			}
432			return changed;
433		}
434	
435		/**
436		 * Duplicate block if it contains only one 'move' insn and all predecessors are 'switch' and 'if'.
437		 * This will help to resolve switch cases order and fallthrough detection
438		 * because such move blocks can be deduplicated by compiler.
439		 */
440		private static boolean duplicateSimpleMoveBlock(MethodNode mth, BlockNode block) {
441			List<InsnNode> insns = block.getInstructions();
442			if (insns.size() == 1 && block.getSuccessors().size() == 1) {
443				InsnNode insn = insns.get(0);
444				if (insn.getType() == InsnType.MOVE) {
445					List<BlockNode> preds = block.getPredecessors();
446					int predSize = preds.size();
447					if (predSize >= 3 && onlySwitchAndIfInLastInsns(preds)) {
448						// confirmed, duplicate block
449						BlockNode successor = block.getSuccessors().get(0);
450						List<BlockNode> predsCopy = new ArrayList<>(preds);
451						for (int i = 1; i < predSize; i++) {
452							BlockNode pred = predsCopy.get(i);
453							BlockNode newBlock = BlockSplitter.startNewBlock(mth, -1);
454							newBlock.add(AFlag.SYNTHETIC);
455							for (InsnNode oldInsn : block.getInstructions()) {
456								InsnNode copyInsn = oldInsn.copyWithoutSsa();
457								copyInsn.add(AFlag.SYNTHETIC);
458								newBlock.getInstructions().add(copyInsn);
459							}
460							newBlock.copyAttributesFrom(block);
461							BlockSplitter.replaceConnection(pred, block, newBlock);
462							BlockSplitter.connect(newBlock, successor);
463						}
464						return true;
465					}
466				}
467			}
468			return false;
469		}
470	
471		private static boolean onlySwitchAndIfInLastInsns(List<BlockNode> preds) {
472			boolean hasSwitch = false;
473			boolean hasIf = false;
474			for (BlockNode pred : preds) {
475				InsnNode lastInsn = BlockUtils.getLastInsn(pred);
476				if (lastInsn == null) {
477					return false;
478				}
479				InsnType insnType = lastInsn.getType();
480				switch (insnType) {
481					case SWITCH:
482						hasSwitch = true;
483						break;
484					case IF:
485						hasIf = true;
486						break;
487					default:
488						return false;
489				}
490			}
491			return hasSwitch && hasIf;
492		}
493	
494		private static boolean simplifyLoopEnd(MethodNode mth, LoopInfo loop) {
495			BlockNode loopEnd = loop.getEnd();
496			if (loopEnd.getSuccessors().size() <= 1) {
497				return false;
498			}
499			// make loop end a simple path block
500			BlockNode newLoopEnd = BlockSplitter.startNewBlock(mth, -1);
501			newLoopEnd.add(AFlag.SYNTHETIC);
502			newLoopEnd.add(AFlag.LOOP_END);
503			BlockNode loopStart = loop.getStart();
504			BlockSplitter.replaceConnection(loopEnd, loopStart, newLoopEnd);
505			BlockSplitter.connect(newLoopEnd, loopStart);
506			if (DEBUG_MODS) {
507				mth.get(DebugModAttr.TYPE).addEvent("Simplify loop end");
508			}
509			return true;
510		}
511	
512		private static boolean checkLoops(MethodNode mth, BlockNode block) {
513			if (!block.contains(AFlag.LOOP_START)) {
514				return false;
515			}
516			List<LoopInfo> loops = block.getAll(AType.LOOP);
517			int loopsCount = loops.size();
518			if (loopsCount == 0) {
519				return false;
520			}
521			for (LoopInfo loop : loops) {
522				if (insertBlocksForBreak(mth, loop)) {
523					return true;
524				}
525			}
526			if (loopsCount > 1 && splitLoops(mth, block, loops)) {
527				return true;
528			}
529			if (loopsCount == 1) {
530				LoopInfo loop = loops.get(0);
531				return insertBlocksForContinue(mth, loop)
532						|| insertPreHeader(mth, loop)
533						|| simplifyLoopEnd(mth, loop);
534			}
535			return false;
536		}
537	
538		/**
539		 * Insert simple path block before loop header
540		 */
541		private static boolean insertPreHeader(MethodNode mth, LoopInfo loop) {
542			BlockNode start = loop.getStart();
543			List<BlockNode> preds = start.getPredecessors();
544			int predsCount = preds.size() - 1; // don't count back edge
545			if (predsCount == 1) {
546				return false;
547			}
548			if (predsCount == 0) {
549				if (!start.contains(AFlag.MTH_ENTER_BLOCK)) {
550					mth.addWarnComment("Unexpected block without predecessors: " + start);
551				}
552				BlockNode newEnterBlock = BlockSplitter.startNewBlock(mth, -1);
553				newEnterBlock.add(AFlag.SYNTHETIC);
554				newEnterBlock.add(AFlag.MTH_ENTER_BLOCK);
555				mth.setEnterBlock(newEnterBlock);
556				start.remove(AFlag.MTH_ENTER_BLOCK);
557				BlockSplitter.connect(newEnterBlock, start);
558			} else {
559				// multiple predecessors
560				BlockNode preHeader = BlockSplitter.startNewBlock(mth, -1);
561				preHeader.add(AFlag.SYNTHETIC);
562				BlockNode loopEnd = loop.getEnd();
563				for (BlockNode pred : new ArrayList<>(preds)) {
564					if (pred != loopEnd) {
565						BlockSplitter.replaceConnection(pred, start, preHeader);
566					}
567				}
568				BlockSplitter.connect(preHeader, start);
569			}
570			if (DEBUG_MODS) {
571				mth.get(DebugModAttr.TYPE).addEvent("Insert loop pre header");
572			}
573			return true;
574		}
575	
576		/**
577		 * Insert additional blocks for possible 'break' insertion
578		 */
579		private static boolean insertBlocksForBreak(MethodNode mth, LoopInfo loop) {
580			boolean change = false;
581			List<Edge> edges = loop.getExitEdges();
582			if (!edges.isEmpty()) {
583				for (Edge edge : edges) {
584					BlockNode target = edge.getTarget();
585					BlockNode source = edge.getSource();
586					if (!target.contains(AFlag.SYNTHETIC) && !source.contains(AFlag.SYNTHETIC)) {
587						BlockSplitter.insertBlockBetween(mth, source, target);
588						change = true;
589					}
590				}
591			}
592			if (DEBUG_MODS && change) {
593				mth.get(DebugModAttr.TYPE).addEvent("Insert loop break blocks");
594			}
595			return change;
596		}
597	
598		/**
599		 * Insert additional blocks for possible 'continue' insertion
600		 */
601		private static boolean insertBlocksForContinue(MethodNode mth, LoopInfo loop) {
602			BlockNode loopEnd = loop.getEnd();
603			boolean change = false;
604			List<BlockNode> preds = loopEnd.getPredecessors();
605			if (preds.size() > 1) {
606				for (BlockNode pred : new ArrayList<>(preds)) {
607					if (!pred.contains(AFlag.SYNTHETIC)) {
608						BlockSplitter.insertBlockBetween(mth, pred, loopEnd);
609						change = true;
610					}
611				}
612			}
613			if (DEBUG_MODS && change) {
614				mth.get(DebugModAttr.TYPE).addEvent("Insert loop continue block");
615			}
616			return change;
617		}
618	
619		private static boolean splitLoops(MethodNode mth, BlockNode block, List<LoopInfo> loops) {
620			boolean oneHeader = true;
621			for (LoopInfo loop : loops) {
622				if (loop.getStart() != block) {
623					oneHeader = false;
624					break;
625				}
626			}
627			if (!oneHeader) {
628				return false;
629			}
630			// several back edges connected to one loop header => make additional block
631			BlockNode newLoopEnd = BlockSplitter.startNewBlock(mth, block.getStartOffset());
632			newLoopEnd.add(AFlag.SYNTHETIC);
633			connect(newLoopEnd, block);
634			for (LoopInfo la : loops) {
635				BlockSplitter.replaceConnection(la.getEnd(), block, newLoopEnd);
636			}
637			if (DEBUG_MODS) {
638				mth.get(DebugModAttr.TYPE).addEvent("Split loops");
639			}
640			return true;
641		}
642	
643		private static boolean splitExitBlocks(MethodNode mth) {
644			boolean changed = false;
645			for (BlockNode preExitBlock : mth.getPreExitBlocks()) {
646				if (splitReturn(mth, preExitBlock)) {
647					changed = true;
648				} else if (splitThrow(mth, preExitBlock)) {
649					changed = true;
650				}
651			}
652			if (changed) {
653				updateExitBlockConnections(mth);
654				if (DEBUG_MODS) {
655					mth.get(DebugModAttr.TYPE).addEvent("Split exit block");
656				}
657			}
658			return changed;
659		}
660	
661		private static void updateExitBlockConnections(MethodNode mth) {
662			BlockNode exitBlock = mth.getExitBlock();
663			BlockSplitter.removePredecessors(exitBlock);
664			for (BlockNode block : mth.getBasicBlocks()) {
665				if (block != exitBlock
666						&& block.getSuccessors().isEmpty()
667						&& !block.contains(AFlag.REMOVE)) {
668					BlockSplitter.connect(block, exitBlock);
669				}
670			}
671		}
672	
673		/**
674		 * Splice return block if several predecessors presents
675		 */
676		private static boolean splitReturn(MethodNode mth, BlockNode returnBlock) {
677			if (returnBlock.contains(AFlag.SYNTHETIC)
678					|| returnBlock.contains(AFlag.ORIG_RETURN)
679					|| returnBlock.contains(AType.EXC_HANDLER)) {
680				return false;
681			}
682			List<BlockNode> preds = returnBlock.getPredecessors();
683			if (preds.size() < 2) {
684				return false;
685			}
686			InsnNode returnInsn = BlockUtils.getLastInsn(returnBlock);
687			if (returnInsn == null) {
688				return false;
689			}
690			if (returnInsn.getArgsCount() == 1
691					&& returnBlock.getInstructions().size() == 1
692					&& !isArgAssignInPred(preds, returnInsn.getArg(0))) {
693				return false;
694			}
695	
696			boolean first = true;
697			for (BlockNode pred : new ArrayList<>(preds)) {
698				if (first) {
699					returnBlock.add(AFlag.ORIG_RETURN);
700					first = false;
701				} else {
702					BlockNode newRetBlock = BlockSplitter.startNewBlock(mth, -1);
703					newRetBlock.add(AFlag.SYNTHETIC);
704					newRetBlock.add(AFlag.RETURN);
705					for (InsnNode oldInsn : returnBlock.getInstructions()) {
706						InsnNode copyInsn = oldInsn.copyWithoutSsa();
707						copyInsn.add(AFlag.SYNTHETIC);
708						newRetBlock.getInstructions().add(copyInsn);
709					}
710					BlockSplitter.replaceConnection(pred, returnBlock, newRetBlock);
711				}
712			}
713			return true;
714		}
715	
716		private static boolean splitThrow(MethodNode mth, BlockNode exitBlock) {
717			if (exitBlock.contains(AFlag.IGNORE_THROW_SPLIT)) {
718				return false;
719			}
720			List<BlockNode> preds = exitBlock.getPredecessors();
721			if (preds.size() < 2) {
722				return false;
723			}
724			InsnNode throwInsn = BlockUtils.getLastInsn(exitBlock);
725			if (throwInsn == null || throwInsn.getType() != InsnType.THROW) {
726				return false;
727			}
728			// split only for several exception handlers
729			// traverse predecessors to exception handler
730			Map<BlockNode, ExcHandlerAttr> handlersMap = new HashMap<>(preds.size());
731			Set<BlockNode> handlers = new HashSet<>(preds.size());
732			for (BlockNode pred : preds) {
733				BlockUtils.visitPredecessorsUntil(mth, pred, block -> {
734					ExcHandlerAttr excHandlerAttr = block.get(AType.EXC_HANDLER);
735					if (excHandlerAttr == null) {
736						return false;
737					}
738					boolean correctHandler = excHandlerAttr.getHandler().getBlocks().contains(block);
739					if (correctHandler && isArgAssignInPred(Collections.singletonList(block), throwInsn.getArg(0))) {
740						handlersMap.put(pred, excHandlerAttr);
741						handlers.add(block);
742					}
743					return correctHandler;
744				});
745			}
746			if (handlers.size() == 1) {
747				exitBlock.add(AFlag.IGNORE_THROW_SPLIT);
748				return false;
749			}
750	
751			boolean first = true;
752			for (BlockNode pred : new ArrayList<>(preds)) {
753				if (first) {
754					first = false;
755				} else {
756					BlockNode newThrowBlock = BlockSplitter.startNewBlock(mth, -1);
757					newThrowBlock.add(AFlag.SYNTHETIC);
758					for (InsnNode oldInsn : exitBlock.getInstructions()) {
759						InsnNode copyInsn = oldInsn.copyWithoutSsa();
760						copyInsn.add(AFlag.SYNTHETIC);
761						newThrowBlock.getInstructions().add(copyInsn);
762					}
763					newThrowBlock.copyAttributesFrom(exitBlock);
764					ExcHandlerAttr excHandlerAttr = handlersMap.get(pred);
765					if (excHandlerAttr != null) {
766						excHandlerAttr.getHandler().addBlock(newThrowBlock);
767					}
768					BlockSplitter.replaceConnection(pred, exitBlock, newThrowBlock);
769				}
770			}
771			return true;
772		}
773	
774		private static boolean isArgAssignInPred(List<BlockNode> preds, InsnArg arg) {
775			if (arg.isRegister()) {
776				int regNum = ((RegisterArg) arg).getRegNum();
777				for (BlockNode pred : preds) {
778					for (InsnNode insnNode : pred.getInstructions()) {
779						RegisterArg result = insnNode.getResult();
780						if (result != null && result.getRegNum() == regNum) {
781							return true;
782						}
783					}
784				}
785			}
786			return false;
787		}
788	
789		public static void removeMarkedBlocks(MethodNode mth) {
790			boolean removed = mth.getBasicBlocks().removeIf(block -> {
791				if (block.contains(AFlag.REMOVE)) {
792					if (!block.getPredecessors().isEmpty() || !block.getSuccessors().isEmpty()) {
793						LOG.warn("Block {} not deleted, method: {}", block, mth);
794					} else {
795						TryCatchBlockAttr tryBlockAttr = block.get(AType.TRY_BLOCK);
796						if (tryBlockAttr != null) {
797							tryBlockAttr.removeBlock(block);
798						}
799						return true;
800					}
801				}
802				return false;
803			});
804			if (removed) {
805				mth.updateBlockPositions();
806			}
807		}
808	
809		private static void removeUnreachableBlocks(MethodNode mth) {
810			Set<BlockNode> toRemove = new LinkedHashSet<>();
811			for (BlockNode block : mth.getBasicBlocks()) {
812				computeUnreachableFromBlock(toRemove, block, mth);
813			}
814			removeFromMethod(toRemove, mth);
815		}
816	
817		public static void removeUnreachableBlock(BlockNode blockToRemove, MethodNode mth) {
818			Set<BlockNode> toRemove = new LinkedHashSet<>();
819			computeUnreachableFromBlock(toRemove, blockToRemove, mth);
820			removeFromMethod(toRemove, mth);
821		}
822	
823		private static void computeUnreachableFromBlock(Set<BlockNode> toRemove, BlockNode block, MethodNode mth) {
824			if (block.getPredecessors().isEmpty() && block != mth.getEnterBlock()) {
825				BlockSplitter.collectSuccessors(block, mth.getEnterBlock(), toRemove);
826			}
827		}
828	
829		private static void removeFromMethod(Set<BlockNode> toRemove, MethodNode mth) {
830			if (toRemove.isEmpty()) {
831				return;
832			}
833	
834			int notEmptyBlocks = 0;
835			int insnsCount = 0;
836			for (BlockNode block : toRemove) {
837				int size = block.getInstructions().size();
838				if (size > 0) {
839					notEmptyBlocks++;
840					insnsCount += size;
841				}
842			}
843			if (notEmptyBlocks != 0) {
844				mth.addWarnComment("Unreachable blocks removed: " + notEmptyBlocks + ", instructions: " + insnsCount);
845			}
846	
847			toRemove.forEach(BlockSplitter::detachBlock);
848			mth.getBasicBlocks().removeAll(toRemove);
849			mth.updateBlockPositions();
850		}
851	
852		private static void clearBlocksState(MethodNode mth) {
853			mth.getBasicBlocks().forEach(block -> {
854				block.remove(AType.LOOP);
855				block.remove(AFlag.LOOP_START);
856				block.remove(AFlag.LOOP_END);
857				block.setDoms(null);
858				block.setIDom(null);
859				block.setDomFrontier(null);
860				block.getDominatesOn().clear();
861			});
862		}
863	
864		private static final class DebugModAttr implements IJadxAttribute {
865			static final IJadxAttrType<DebugModAttr> TYPE = IJadxAttrType.create("DebugModAttr");
866	
867			private final Map<String, Integer> statMap = new HashMap<>();
868	
869			public void addEvent(String name) {
870				statMap.merge(name, 1, Integer::sum);
871			}
872	
873			public String formatStats() {
874				StringBuilder sb = new StringBuilder();
875				for (Map.Entry<String, Integer> entry : statMap.entrySet()) {
876					if (sb.length() > 0) {
877						sb.append('\n');
878					}
879					sb.append(' ').append(entry.getKey()).append(": ").append(entry.getValue());
880				}
881				return sb.toString();
882			}
883	
884			@Override
885			public IJadxAttrType<DebugModAttr> getAttrType() {
886				return TYPE;
887			}
888		}
