205		private void exploreTryPath(List<TryEdge> edges, BlockNode blk, Set<BlockNode> searchBlocks, List<BlockNode> exploredBlocks,
206				List<TryCatchBlockAttr> exploredTrys) {
207			for (BlockNode successor : blk.getSuccessors()) {
208				// If a separate branch has already explored this block, we don't need to recalculate its exits.
209				if (exploredBlocks.contains(successor)) {
210					continue;
211				}
212	
213				// If this is a bottom splitter, ignore - we only care about non-handler edges.
214				if (successor.contains(AFlag.EXC_BOTTOM_SPLITTER)) {
215					continue;
216				}
217	
218				exploredBlocks.add(successor);
219	
220				if (successor.contains(AFlag.LOOP_END)) {
221					var loopsAttrList = successor.get(AType.LOOP);
222					List<LoopInfo> loops = loopsAttrList.getList();
223					List<BlockNode> loopStartBlocks = new LinkedList<>();
224					for (LoopInfo loop : loops) {
225						loopStartBlocks.add(loop.getStart());
226						List<Edge> loopEdges = loop.getExitEdges();
227						for (Edge loopEdge : loopEdges) {
228							if (loopEdge.getTarget() == successor) {
229								loopStartBlocks.add(loopEdge.getSource());
230							}
231						}
232					}
233					boolean includesAllLoopStart = ListUtils.allMatch(loopStartBlocks, exploredBlocks::contains);
234					if (!includesAllLoopStart) {
235						edges.add(new TryEdge(blk, successor, TryEdgeType.LOOP_EXIT));
236						continue;
237					}
238				}
239	
240				boolean isPathToAnySearchBlock = false;
241				for (BlockNode searchBlock : searchBlocks) {
242					if (BlockUtils.isPathExists(successor, searchBlock)) {
243						isPathToAnySearchBlock = true;
244						break;
245					}
246				}
247				if (!searchBlocks.contains(successor) && !isPathToAnySearchBlock) {
248					// This block is not contained within this try's block list. This can either be since it is an exit
249					// to the try or it is a block which leads to an exit (for example, an exception handler).
250	
251					// If this block (successor) leads to an exit, then the "bottom block" of all try blocks and this
252					// block will be
253					// equal to the bottom block of all try blocks. If this block is an exit, then either:
254					// - a path does not exist from all try blocks to this block, thus making the bottom block null.
255					// - a path does exist from all try blocks to this block but no more try blocks follow, thus making
256					// the bottom block this block.
257					List<BlockNode> allBlocksWithCurrent = new ArrayList<>(getBlocks().size() + 1);
258					allBlocksWithCurrent.addAll(getBlocks());
259					allBlocksWithCurrent.add(successor);
260					BlockNode bottomBlock = BlockUtils.getBottomBlock(allBlocksWithCurrent);
261	
262					if (!(bottomBlock == null || bottomBlock == successor)) {
263						// This block leads to an exit.
264						exploreTryPath(edges, successor, searchBlocks, exploredBlocks, exploredTrys);
265						continue;
266					}
267	
268					BlockNode emptyPathEndOfSuccessor = BlockUtils.followEmptyPath(successor, false, false);
269	
270					if (emptyPathEndOfSuccessor.contains(AFlag.EXC_TOP_SPLITTER)) {
271						// This block is an exit which enters another try catch. In this case, the next try catch is within
272						// the same scope. Thus, we will take all of the edges out of that try and add them to the list of
273						// edges of this try.
274						Set<TryCatchBlockAttr> nestedTrys = new HashSet<>();
275						List<BlockNode> allSuccessorsOnTryBody = ListUtils.filter(emptyPathEndOfSuccessor.getSuccessors(),
276								potentialTryBlock -> potentialTryBlock.contains(AFlag.TRY_ENTER));
277						for (BlockNode tryBodyEnter : allSuccessorsOnTryBody) {
278							TryCatchBlockAttr nestedTry = tryBodyEnter.get(AType.TRY_BLOCK);
279							if (nestedTry == null) {
280								continue;
281							}
282	
283							// If we have already added a try's edges, skip over it to avoid infinite recursion.
284							if (exploredTrys.contains(nestedTry)) {
285								continue;
286							}
287	
288							// Unsure of why these top splitters have to be the same for them to be "nested" trys, but this
289							// seems to work (?)
290							if (nestedTry.getTopSplitter() != getTopSplitter()) {
291								continue;
292							}
293	
294							nestedTrys.add(nestedTry);
295						}
296	
297						// Only will we attempt to add nested inners if there exists any. If none exist, perform normal
298						// handling of the edge.
299						if (!nestedTrys.isEmpty()) {
300							for (TryCatchBlockAttr nestedTry : nestedTrys) {
301								nestedTry.getFallthroughTryEdges(edges, exploredBlocks, exploredTrys);
302							}
303							continue;
304						}
305					}
306	
307					if (bottomBlock == null) {
308						// This block is an exit which occurs before all try blocks are logically executed.
309						edges.add(new TryEdge(blk, successor, TryEdgeType.PREMATURE_EXIT));
310					} else if (bottomBlock == successor) {
311						// This block is an exit which occurs after all try blocks are logically executed.
312						edges.add(new TryEdge(blk, successor, TryEdgeType.TRUE_FALLTHROUGH));
313					} else {
314						// All possible cases should have been caught by the above if / else and the preceeding if.
315						// If this is hit, any changes made to this algorithm must aptly handle all possible code paths
316						// before executing this.
317						throw new JadxRuntimeException(
318								"Unexpected code execution branch taken during try edge resolution: blk="
319										+ blk + ",successor=" + successor);
320					}
321				} else {
322					exploreTryPath(edges, successor, searchBlocks, exploredBlocks, exploredTrys);
323				}
324			}
325		}
