364		public List<BlockNode> getSearchBlocksFromFallthroughGroups(MethodNode mth, ExceptionHandler finallyHandler,
365				Map<BlockNode, List<TryEdge>> fallthroughGroups) {
366	
367			List<BlockNode> searchBlocks = new LinkedList<>();
368			for (Map.Entry<BlockNode, List<TryEdge>> entry : fallthroughGroups.entrySet()) {
369				BlockNode scopeEndBlock = entry.getKey();
370				List<TryEdge> sourceHandlers = entry.getValue();
371	
372				for (BlockNode scopeEndPredecessor : scopeEndBlock.getPredecessors()) {
373					// Add all predecessors to the scope end which are connected to some handler's scope start
374					for (TryEdge handler : sourceHandlers) {
375						if (handler.isHandlerExit() && handler.getExceptionHandler() == finallyHandler) {
376							continue;
377						}
378						if (BlockUtils.isPathExists(handler.getTarget(), scopeEndPredecessor)) {
379							searchBlocks.add(scopeEndPredecessor);
380							break;
381						}
382					}
383				}
384			}
385			return searchBlocks;
386		}
