79		private static void moveStaticFieldsInit(ClassNode cls) {
80			MethodNode classInitMth = cls.getClassInitMth();
81			if (classInitMth == null
82					|| !classInitMth.getAccessFlags().isStatic()
83					|| classInitMth.isNoCode()
84					|| classInitMth.getBasicBlocks() == null) {
85				return;
86			}
87			if (ListUtils.noneMatch(cls.getFields(), FieldNode::isStatic)) {
88				return;
89			}
90			while (processStaticFields(cls, classInitMth)) {
91				// sometimes instructions moved to field init prevent from vars inline -> inline and try again
