96		private static boolean processStaticFields(ClassNode cls, MethodNode classInitMth) {
97			List<FieldInitInfo> inits = collectFieldsInit(cls, classInitMth, InsnType.SPUT);
98			if (inits.isEmpty()) {
99				return false;
100			}
101			// ignore field init constant if field initialized in class init method
102			for (FieldInitInfo fieldInit : inits) {
103				FieldNode field = fieldInit.fieldNode;
104				if (field.getAccessFlags().isFinal()) {
105					field.remove(JadxAttrType.CONSTANT_VALUE);
106				}
107			}
108			filterFieldsInit(inits);
109			if (inits.isEmpty()) {
110				return false;
111			}
112			for (FieldInitInfo fieldInit : inits) {
113				IndexInsnNode insn = fieldInit.putInsn;
114				InsnArg arg = insn.getArg(0);
115				if (arg instanceof InsnWrapArg) {
116					((InsnWrapArg) arg).getWrapInsn().add(AFlag.DECLARE_VAR);
117				}
118				InsnRemover.remove(classInitMth, insn);
119				addFieldInitAttr(classInitMth, fieldInit.fieldNode, insn);
120			}
121			fixFieldsOrder(cls, inits);
122			return true;
123		}
