125		private static void moveCommonFieldsInit(ClassNode cls) {
126			if (ListUtils.noneMatch(cls.getFields(), FieldNode::isInstance)) {
127				return;
128			}
129			List<MethodNode> constructors = getConstructorsList(cls);
130			if (constructors.isEmpty()) {
131				return;
132			}
133			List<ConstructorInitInfo> infoList = new ArrayList<>(constructors.size());
134			for (MethodNode constructorMth : constructors) {
135				List<FieldInitInfo> inits = collectFieldsInit(cls, constructorMth, InsnType.IPUT);
136				filterFieldsInit(inits);
137				if (inits.isEmpty()) {
138					return;
139				}
140				infoList.add(new ConstructorInitInfo(constructorMth, inits));
141			}
142			// compare collected instructions
143			ConstructorInitInfo common = null;
144			for (ConstructorInitInfo info : infoList) {
145				if (common == null) {
146					common = info;
147					continue;
148				}
149				if (!compareFieldInits(common.fieldInits, info.fieldInits)) {
150					return;
151				}
152			}
153			if (common == null) {
154				return;
155			}
156			// all checks passed
157			for (ConstructorInitInfo info : infoList) {
158				for (FieldInitInfo fieldInit : info.fieldInits) {
159					IndexInsnNode putInsn = fieldInit.putInsn;
160					InsnArg arg = putInsn.getArg(0);
161					if (arg instanceof InsnWrapArg) {
162						((InsnWrapArg) arg).getWrapInsn().add(AFlag.DECLARE_VAR);
163					}
164					InsnRemover.remove(info.constructorMth, putInsn);
165				}
166			}
167			for (FieldInitInfo fieldInit : common.fieldInits) {
168				addFieldInitAttr(common.constructorMth, fieldInit.fieldNode, fieldInit.putInsn);
169			}
170			fixFieldsOrder(cls, common.fieldInits);
171		}
