173		private static List<FieldInitInfo> collectFieldsInit(ClassNode cls, MethodNode mth, InsnType putType) {
174			List<FieldInitInfo> fieldsInit = new ArrayList<>();
175			Set<BlockNode> singlePathBlocks = new HashSet<>();
176			BlockUtils.visitSinglePath(mth.getEnterBlock(), singlePathBlocks::add);
177	
178			boolean canReorder = true;
179			for (BlockNode block : mth.getBasicBlocks()) {
180				for (InsnNode insn : block.getInstructions()) {
181					boolean fieldInsn = false;
182					if (insn.getType() == putType) {
183						IndexInsnNode putInsn = (IndexInsnNode) insn;
184						FieldInfo field = (FieldInfo) putInsn.getIndex();
185						if (field.getDeclClass().equals(cls.getClassInfo())) {
186							FieldNode fn = cls.searchField(field);
187							if (fn != null) {
188								boolean canMove = canReorder && singlePathBlocks.contains(block);
189								fieldsInit.add(new FieldInitInfo(fn, putInsn, canMove));
190								fieldInsn = true;
191							}
192						}
193					}
194					if (!fieldInsn && canReorder && !insn.canReorder()) {
195						canReorder = false;
196					}
197				}
198			}
199			return fieldsInit;
200		}
