202		private static void filterFieldsInit(List<FieldInitInfo> inits) {
203			// exclude fields initialized several times
204			Set<FieldNode> seen = new HashSet<>();
205			Set<FieldInfo> excludedFields = new HashSet<>();
206			for (FieldInitInfo fi : inits) {
207				if (!seen.add(fi.fieldNode)) {
208					excludedFields.add(fi.fieldNode.getFieldInfo());
209				}
210			}
211	
212			for (FieldInitInfo initInfo : inits) {
213				if (!checkInsn(initInfo)) {
214					excludedFields.add(initInfo.fieldNode.getFieldInfo());
215				}
216			}
217			if (!excludedFields.isEmpty()) {
218				boolean changed;
219				do {
220					changed = false;
221					for (FieldInitInfo initInfo : inits) {
222						FieldInfo fieldInfo = initInfo.fieldNode.getFieldInfo();
223						if (excludedFields.contains(fieldInfo)) {
224							continue;
225						}
226						if (insnUseExcludedField(initInfo, excludedFields)) {
227							excludedFields.add(fieldInfo);
228							changed = true;
229						}
230					}
231				} while (changed);
232			}
233	
234			// apply
235			if (!excludedFields.isEmpty()) {
236				inits.removeIf(fi -> excludedFields.contains(fi.fieldNode.getFieldInfo()));
237			}
238		}
