240		private static boolean checkInsn(FieldInitInfo initInfo) {
241			if (!initInfo.canMove) {
242				return false;
243			}
244			IndexInsnNode insn = initInfo.putInsn;
245			InsnArg arg = insn.getArg(0);
246			if (arg.isInsnWrap()) {
247				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
248				if (!wrapInsn.canReorder() && insn.contains(AType.EXC_CATCH)) {
249					return false;
250				}
251			} else {
252				return arg.isLiteral() || arg.isThis();
253			}
254			Set<RegisterArg> regs = new HashSet<>();
255			insn.getRegisterArgs(regs);
256			if (!regs.isEmpty()) {
257				for (RegisterArg reg : regs) {
258					if (!reg.isThis()) {
259						return false;
260					}
261				}
262			}
263			return true;
264		}
