266		private static boolean insnUseExcludedField(FieldInitInfo initInfo, Set<FieldInfo> excludedFields) {
267			if (excludedFields.isEmpty()) {
268				return false;
269			}
270			IndexInsnNode insn = initInfo.putInsn;
271			boolean staticField = insn.getType() == InsnType.SPUT;
272			InsnType useType = staticField ? InsnType.SGET : InsnType.IGET;
273			// exclude if init code use any excluded field
274			Boolean exclude = insn.visitInsns(innerInsn -> {
275				if (innerInsn.getType() == useType) {
276					FieldInfo fieldInfo = (FieldInfo) ((IndexInsnNode) innerInsn).getIndex();
277					if (excludedFields.contains(fieldInfo)) {
278						return true;
279					}
280				}
281				return null;
282			});
283			return Objects.equals(exclude, Boolean.TRUE);
284		}
