286		private static void fixFieldsOrder(ClassNode cls, List<FieldInitInfo> inits) {
287			List<FieldNode> orderedFields = processFieldsDependencies(cls, inits);
288	
289			// apply source line and alias name sorting (same as for methods and inner classes)
290			List<FieldNode> clsFields = cls.getFields();
