292			clsFields.sort(Comparator.comparingInt(FieldNode::getSourceLine)
293					.thenComparing(f -> sortingMap.computeIfAbsent(f, ClassGen::getShortAlias)));
294	
295			if (!orderedFields.isEmpty()) {
296				// check if already ordered
297				boolean ordered = Collections.indexOfSubList(clsFields, orderedFields) != -1;
298				if (!ordered) {
299					clsFields.removeAll(orderedFields);
300					clsFields.addAll(orderedFields);
301				}
302			}
303		}
