305		private static List<FieldNode> processFieldsDependencies(ClassNode cls, List<FieldInitInfo> inits) {
306			// collect dependant fields
307			Map<FieldNode, List<FieldNode>> deps = buildFieldDeps(cls, inits);
308			if (deps.isEmpty()) {
309				return Collections.emptyList();
310			}
311			// build new list with deps fields before usage field
312			List<FieldNode> orderedFields = Utils.collectionMap(inits, v -> v.fieldNode);
313			List<FieldNode> result = new ArrayList<>();
314			for (FieldNode field : orderedFields) {
315				int idx = result.indexOf(field);
316				List<FieldNode> fieldDeps = deps.get(field);
317				if (fieldDeps == null) {
318					if (idx == -1) {
319						result.add(field);
320					}
321					continue;
322				}
323				if (idx == -1) {
324					for (FieldNode depField : fieldDeps) {
325						if (!result.contains(depField)) {
326							result.add(depField);
327						}
328					}
329					result.add(field);
330					continue;
331				}
332				for (FieldNode depField : fieldDeps) {
333					int depIdx = result.indexOf(depField);
334					if (depIdx == -1) {
335						result.add(idx, depField);
336					} else if (depIdx > idx) {
337						result.remove(depIdx);
338						result.add(idx, depField);
339					}
340				}
341			}
342			return result;
343		}
