345		private static Map<FieldNode, List<FieldNode>> buildFieldDeps(ClassNode cls, List<FieldInitInfo> inits) {
346			Map<FieldNode, List<FieldNode>> deps = new HashMap<>(inits.size());
347			for (FieldInitInfo initInfo : inits) {
348				IndexInsnNode insn = initInfo.putInsn;
349				boolean staticField = insn.getType() == InsnType.SPUT;
350				InsnType useType = staticField ? InsnType.SGET : InsnType.IGET;
351				insn.visitInsns(subInsn -> {
352					if (subInsn.getType() == useType) {
353						FieldInfo fieldInfo = (FieldInfo) ((IndexInsnNode) subInsn).getIndex();
354						if (fieldInfo.getDeclClass().equals(cls.getClassInfo())) {
355							FieldNode depField = cls.searchField(fieldInfo);
356							if (depField != null) {
357								deps.computeIfAbsent(initInfo.fieldNode, k -> new ArrayList<>())
358										.add(depField);
359							}
360						}
361					}
362				});
363			}
364			return deps;
365		}
