367		private static boolean compareFieldInits(List<FieldInitInfo> base, List<FieldInitInfo> other) {
368			if (base.size() != other.size()) {
369				return false;
370			}
371			int count = base.size();
372			for (int i = 0; i < count; i++) {
373				InsnNode baseInsn = base.get(i).putInsn;
374				InsnNode otherInsn = other.get(i).putInsn;
375				if (!sameFieldInit(baseInsn, otherInsn)) {
376					return false;
377				}
378			}
379			return true;
380		}
