382		private static boolean sameFieldInit(InsnNode first, InsnNode second) {
383			if (!first.isSame(second)) {
384				return false;
385			}
386			for (int i = 0; i < first.getArgsCount(); i++) {
387				InsnArg firstArg = first.getArg(i);
388				InsnArg secondArg = second.getArg(i);
389				// Constructors can use different registers and SSA variables for the same instance.
390				if (firstArg.isThis() && secondArg.isThis()) {
391					continue;
392				}
393				if (firstArg.isInsnWrap() && secondArg.isInsnWrap()) {
394					if (!sameFieldInit(((InsnWrapArg) firstArg).getWrapInsn(), ((InsnWrapArg) secondArg).getWrapInsn())) {
395						return false;
396					}
397				} else if (!firstArg.equals(secondArg)) {
398					return false;
399				}
400			}
401			return true;
402		}
