49	public class SimplifyVisitor extends AbstractVisitor {
50	
51		private static final Logger LOG = LoggerFactory.getLogger(SimplifyVisitor.class);
52	
53		private MethodInfo stringGetBytesMth;
54	
55		@Override
56		public void init(RootNode root) {
57			stringGetBytesMth = MethodInfo.fromDetails(
58					root,
59					ClassInfo.fromType(root, ArgType.STRING),
60					"getBytes",
61					Collections.emptyList(),
62					ArgType.array(ArgType.BYTE));
63		}
64	
65		@Override
66		public void visit(MethodNode mth) {
67			if (mth.isNoCode()) {
68				return;
69			}
70			boolean changed = false;
71			for (BlockNode block : mth.getBasicBlocks()) {
72				if (simplifyBlock(mth, block)) {
73					changed = true;
74				}
75			}
76			if (changed || mth.contains(AFlag.REQUEST_CODE_SHRINK)) {
77				CodeShrinkVisitor.shrinkMethod(mth);
78			}
79		}
80	
81		private boolean simplifyBlock(MethodNode mth, BlockNode block) {
82			boolean changed = false;
83			List<InsnNode> list = block.getInstructions();
84			for (int i = 0; i < list.size(); i++) {
85				InsnNode insn = list.get(i);
86				int insnCount = list.size();
87				InsnNode modInsn = simplifyInsn(mth, insn, null);
88				if (modInsn != null) {
89					if (i < list.size() && list.get(i) == insn) {
90						list.set(i, modInsn);
91					} else {
92						int idx = InsnList.getIndex(list, insn);
93						if (idx == -1) {
94							throw new JadxRuntimeException("Failed to replace insn");
95						}
96						list.set(idx, modInsn);
97					}
98					InsnRemover.unbindInsn(mth, insn);
99					modInsn.rebindArgs();
100					if (list.size() < insnCount) {
101						// some insns removed => restart block processing
102						simplifyBlock(mth, block);
103						return true;
104					}
105					changed = true;
106				}
107			}
108			return changed;
109		}
110	
111		private void simplifyArgs(MethodNode mth, InsnNode insn) {
112			boolean changed = false;
113			for (InsnArg arg : insn.getArguments()) {
114				if (arg.isInsnWrap()) {
115					InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
116					InsnNode replaceInsn = simplifyInsn(mth, wrapInsn, insn);
117					if (replaceInsn != null) {
118						arg.wrapInstruction(mth, replaceInsn);
119						changed = true;
120					}
121				}
122			}
123			if (changed) {
124				insn.rebindArgs();
125				mth.add(AFlag.REQUEST_CODE_SHRINK);
126			}
127		}
128	
129		private InsnNode simplifyInsn(MethodNode mth, InsnNode insn, @Nullable InsnNode parentInsn) {
130			if (insn.contains(AFlag.DONT_GENERATE)) {
131				return null;
132			}
133			simplifyArgs(mth, insn);
134			switch (insn.getType()) {
135				case ARITH:
136					return simplifyArith((ArithNode) insn);
137	
138				case IF:
139					simplifyIf(mth, (IfNode) insn);
140					break;
141				case TERNARY:
142					simplifyTernary(mth, (TernaryInsn) insn);
143					break;
144	
145				case INVOKE:
146					return convertInvoke(mth, (InvokeNode) insn);
147	
148				case IPUT:
149				case SPUT:
150					return convertFieldArith(mth, insn);
151	
152				case CAST:
153				case CHECK_CAST:
154					return processCast(mth, (IndexInsnNode) insn, parentInsn);
155	
156				case MOVE:
157					InsnArg firstArg = insn.getArg(0);
158					if (firstArg.isLiteral()) {
159						InsnNode constInsn = new InsnNode(InsnType.CONST, 1);
160						constInsn.setResult(insn.getResult());
161						constInsn.addArg(firstArg);
162						constInsn.copyAttributesFrom(insn);
163						return constInsn;
164					}
165					break;
166	
167				case CONSTRUCTOR:
168					return simplifyStringConstructor(mth, (ConstructorInsn) insn);
169	
170				default:
171					break;
172			}
173			return null;
174		}
175	
176		private InsnNode simplifyStringConstructor(MethodNode mth, ConstructorInsn insn) {
177			if (insn.getCallMth().getDeclClass().getType().equals(ArgType.STRING)
178					&& insn.getArgsCount() != 0
179					&& insn.getArg(0).isInsnWrap()) {
180				InsnNode arrInsn = ((InsnWrapArg) insn.getArg(0)).getWrapInsn();
181				if (arrInsn.getType() == InsnType.FILLED_NEW_ARRAY
182						&& arrInsn.getArgsCount() != 0) {
183					ArgType elemType = ((FilledNewArrayNode) arrInsn).getElemType();
184					if (elemType == ArgType.BYTE || elemType == ArgType.CHAR) {
185						int printable = 0;
186						byte[] arr = new byte[arrInsn.getArgsCount()];
187						for (int i = 0; i < arr.length; i++) {
188							InsnArg arrArg = arrInsn.getArg(i);
189							if (!arrArg.isLiteral()) {
190								return null;
191							}
192							arr[i] = (byte) ((LiteralArg) arrArg).getLiteral();
193							if (NameMapper.isPrintableChar((char) arr[i])) {
194								printable++;
195							}
196						}
197						if (printable >= arr.length - printable) {
198							InsnNode constStr = new ConstStringNode(new String(arr));
199							if (insn.getArgsCount() == 1) {
200								constStr.setResult(insn.getResult());
201								constStr.copyAttributesFrom(insn);
202								InsnRemover.unbindArgUsage(mth, insn.getArg(0));
203								return constStr;
204							} else {
205								InvokeNode in = new InvokeNode(stringGetBytesMth, InvokeType.VIRTUAL, 1);
206								in.addArg(InsnArg.wrapArg(constStr));
207								InsnArg bytesArg = InsnArg.wrapArg(in);
208								bytesArg.setType(stringGetBytesMth.getReturnType());
209								insn.setArg(0, bytesArg);
210								return null;
211							}
212						}
213					}
214				}
215			}
216			return null;
217		}
218	
219		private static InsnNode processCast(MethodNode mth, IndexInsnNode castInsn, @Nullable InsnNode parentInsn) {
220			if (castInsn.contains(AFlag.EXPLICIT_CAST)) {
221				return null;
222			}
223			InsnArg castArg = castInsn.getArg(0);
224			ArgType argType = castArg.getType();
225	
226			// Don't removes CHECK_CAST for wrapped INVOKE if invoked method returns different type
227			if (castArg.isInsnWrap()) {
228				InsnNode wrapInsn = ((InsnWrapArg) castArg).getWrapInsn();
229				if (wrapInsn.getType() == InsnType.INVOKE) {
230					argType = ((InvokeNode) wrapInsn).getCallMth().getReturnType();
231				}
232			}
233	
234			ArgType castToType = (ArgType) castInsn.getIndex();
235			if (isArithWideUpCast(parentInsn, argType, castToType)) {
236				return null;
237			}
238			if (!ArgType.isCastNeeded(mth.root(), argType, castToType)
239					|| isCastDuplicate(castInsn)
240					|| shadowedByOuterCast(mth.root(), castToType, parentInsn)) {
241				InsnNode insnNode = new InsnNode(InsnType.MOVE, 1);
242				insnNode.setOffset(castInsn.getOffset());
243				insnNode.setResult(InsnNode.duplicateArg(castInsn.getResult()));
244				insnNode.addArg(castArg.duplicate());
245				return insnNode;
246			}
247			return null;
248		}
249	
250		/**
251		 * Keep cast to wide types in arith instructions,
252		 * because arguments type determine instruction used in result bytecode.
253		 * Example: (long) i << 32 - without 'long' cast will be used 'int shift' instruction and result
254		 * will be incorrect
255		 */
256		private static boolean isArithWideUpCast(@Nullable InsnNode parentInsn, ArgType argType, ArgType castToType) {
257			if (parentInsn != null
258					&& parentInsn.getType() == InsnType.ARITH
259					&& argType.isPrimitive() && castToType.isPrimitive()) {
260				return castToType.getRegCount() > argType.getRegCount();
261			}
262			return false;
263		}
