269		private static boolean shadowedByOuterCast(RootNode root, ArgType castType, @Nullable InsnNode parentInsn) {
270			if (parentInsn != null && parentInsn.getType() == InsnType.CAST) {
271				ArgType parentCastType = (ArgType) ((IndexInsnNode) parentInsn).getIndex();
272				TypeCompareEnum result = root.getTypeCompare().compareTypes(parentCastType, castType);
273				return result.isNarrow();
274			}
275			return false;
