308		/**
309		 * Simplify chains of calls to StringBuilder#append() plus constructor of StringBuilder.
310		 * Those chains are usually automatically generated by the Java compiler when you create String
311		 * concatenations like <code>"text " + 1 + " text"</code>.
312		 */
313		private static InsnNode convertInvoke(MethodNode mth, InvokeNode insn) {
314			MethodInfo callMth = insn.getCallMth();
315	
316			if (callMth.getDeclClass().getFullName().equals(Consts.CLASS_STRING_BUILDER)
317					&& callMth.getShortId().equals(Consts.MTH_TOSTRING_SIGNATURE)) {
318				InsnArg instanceArg = insn.getArg(0);
319				if (instanceArg.isInsnWrap()) {
320					// Convert 'new StringBuilder(xxx).append(yyy).append(zzz).toString() to STRING_CONCAT insn
321					List<InsnNode> callChain = flattenInsnChainUntil(insn, InsnType.CONSTRUCTOR);
322					return convertStringBuilderChain(mth, insn, callChain);
323				}
324				if (instanceArg.isRegister()) {
325					// Convert 'StringBuilder sb = new StringBuilder(xxx); sb.append(yyy); String str = sb.toString();'
326					List<InsnNode> useChain = collectUseChain(mth, insn, (RegisterArg) instanceArg);
327					return convertStringBuilderChain(mth, insn, useChain);
328				}
329			}
330			return null;
331		}
332	
333		private static List<InsnNode> collectUseChain(MethodNode mth, InvokeNode insn, RegisterArg instanceArg) {
334			SSAVar sVar = instanceArg.getSVar();
335			if (sVar.isUsedInPhi() || sVar.getUseCount() == 0) {
336				return Collections.emptyList();
337			}
338			List<InsnNode> useChain = new ArrayList<>(sVar.getUseCount() + 1);
339			InsnNode assignInsn = sVar.getAssign().getParentInsn();
340			if (assignInsn == null) {
341				return Collections.emptyList();
342			}
343			useChain.add(assignInsn);
344			for (RegisterArg reg : sVar.getUseList()) {
345				InsnNode parentInsn = reg.getParentInsn();
346				if (parentInsn == null) {
347					return Collections.emptyList();
348				}
349				useChain.add(parentInsn);
350			}
351			int toStrIdx = InsnList.getIndex(useChain, insn);
352			if (useChain.size() - 1 != toStrIdx) {
353				return Collections.emptyList();
354			}
355			useChain.remove(toStrIdx);
356	
357			// all insns must be in one block and sequential
358			BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
359			if (assignBlock == null) {
360				return Collections.emptyList();
361			}
362			List<InsnNode> blockInsns = assignBlock.getInstructions();
363			int assignIdx = InsnList.getIndex(blockInsns, assignInsn);
364			int chainSize = useChain.size();
365			int lastInsn = blockInsns.size() - assignIdx;
366			if (lastInsn < chainSize) {
367				return Collections.emptyList();
368			}
369			for (int i = 1; i < chainSize; i++) {
370				if (blockInsns.get(assignIdx + i) != useChain.get(i)) {
371					return Collections.emptyList();
372				}
373			}
374			return useChain;
375		}
376	
377		private static InsnNode convertStringBuilderChain(MethodNode mth, InvokeNode toStrInsn, List<InsnNode> chain) {
378			try {
379				int chainSize = chain.size();
380				if (chainSize < 2) {
381					return null;
382				}
383				List<InsnArg> args = new ArrayList<>(chainSize);
384				InsnNode firstInsn = chain.get(0);
385				if (firstInsn.getType() != InsnType.CONSTRUCTOR) {
386					return null;
387				}
388				ConstructorInsn constrInsn = (ConstructorInsn) firstInsn;
389				if (constrInsn.getArgsCount() == 1) {
390					ArgType argType = constrInsn.getCallMth().getArgumentsTypes().get(0);
391					if (!argType.isObject()) {
392						return null;
393					}
394					args.add(constrInsn.getArg(0));
395				}
396				for (int i = 1; i < chainSize; i++) {
397					InsnNode chainInsn = chain.get(i);
398					InsnArg arg = getArgFromAppend(chainInsn);
399					if (arg == null) {
400						return null;
401					}
402					args.add(arg);
403				}
404	
405				// all check passed
406				List<InsnArg> dupArgs = Utils.collectionMap(args, InsnArg::duplicate);
407				List<InsnArg> simplifiedArgs = concatConstArgs(dupArgs);
408				InsnNode concatInsn = new InsnNode(InsnType.STR_CONCAT, simplifiedArgs);
409				concatInsn.add(AFlag.SYNTHETIC);
410				if (toStrInsn.getResult() == null && !toStrInsn.contains(AFlag.WRAPPED)) {
411					// string concat without assign to variable will cause compilation error
412					concatInsn.setResult(mth.makeSyntheticRegArg(ArgType.STRING));
413				} else {
414					concatInsn.setResult(toStrInsn.getResult());
415				}
416				concatInsn.copyAttributesFrom(toStrInsn);
417				removeStringBuilderInsns(mth, toStrInsn, chain);
418				return concatInsn;
419			} catch (Exception e) {
420				mth.addWarnComment("String concatenation convert failed", e);
421			}
422			return null;
423		}
424	
425		private static boolean isConstConcatNeeded(List<InsnArg> args) {
426			boolean prevConst = false;
427			for (InsnArg arg : args) {
428				boolean curConst = arg.isConst();
429				if (curConst && prevConst) {
430					// found 2 consecutive constants
431					return true;
432				}
433				prevConst = curConst;
434			}
435			return false;
436		}
437	
438		private static List<InsnArg> concatConstArgs(List<InsnArg> args) {
439			if (!isConstConcatNeeded(args)) {
440				return args;
441			}
442			int size = args.size();
443			List<InsnArg> newArgs = new ArrayList<>(size);
444			List<String> concatList = new ArrayList<>(size);
445			for (int i = 0; i < size; i++) {
446				InsnArg arg = args.get(i);
447				String constStr = getConstString(arg);
448				if (constStr != null) {
449					concatList.add(constStr);
450				} else {
451					if (!concatList.isEmpty()) {
452						newArgs.add(getConcatArg(concatList, args, i));
453						concatList.clear();
454					}
455					newArgs.add(arg);
456				}
457			}
458			if (!concatList.isEmpty()) {
459				newArgs.add(getConcatArg(concatList, args, size));
460			}
461			return newArgs;
462		}
463	
464		private static InsnArg getConcatArg(List<String> concatList, List<InsnArg> args, int idx) {
465			if (concatList.size() == 1) {
466				return args.get(idx - 1);
467			}
468			String str = Utils.concatStrings(concatList);
469			return InsnArg.wrapArg(new ConstStringNode(str));
470		}
471	
472		@Nullable
473		private static String getConstString(InsnArg arg) {
474			if (arg.isLiteral()) {
475				return TypeGen.literalToRawString((LiteralArg) arg);
476			}
477			if (arg.isInsnWrap()) {
478				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
479				if (wrapInsn instanceof ConstStringNode) {
480					return ((ConstStringNode) wrapInsn).getString();
481				}
482			}
483			return null;
484		}
