503		private static List<InsnNode> flattenInsnChainUntil(InsnNode insn, InsnType insnType) {
504			List<InsnNode> chain = new ArrayList<>();
505			InsnArg arg = insn.getArg(0);
506			while (arg.isInsnWrap()) {
507				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
508				chain.add(wrapInsn);
509				if (wrapInsn.getType() == insnType
510						|| wrapInsn.getArgsCount() == 0) {
511					break;
512				}
513				arg = wrapInsn.getArg(0);
514			}
515			Collections.reverse(chain);
516			return chain;
517		}
518	
519		private static InsnArg getArgFromAppend(InsnNode chainInsn) {
520			if (chainInsn.getType() == InsnType.INVOKE && chainInsn.getArgsCount() == 2) {
521				MethodInfo callMth = ((InvokeNode) chainInsn).getCallMth();
522				if (callMth.getDeclClass().getFullName().equals(Consts.CLASS_STRING_BUILDER)
523						&& callMth.getName().equals("append")) {
524					return chainInsn.getArg(1);
525				}
526			}
527			return null;
528		}
