530		private static InsnNode simplifyArith(ArithNode arith) {
531			if (arith.getArgsCount() != 2) {
532				return null;
533			}
534			LiteralArg litArg = null;
535			InsnArg secondArg = arith.getArg(1);
536			if (secondArg.isInsnWrap()) {
537				InsnNode wr = ((InsnWrapArg) secondArg).getWrapInsn();
538				if (wr.getType() == InsnType.CONST) {
539					InsnArg arg = wr.getArg(0);
540					if (arg.isLiteral()) {
541						litArg = (LiteralArg) arg;
542					}
543				}
544			} else if (secondArg.isLiteral()) {
545				litArg = (LiteralArg) secondArg;
546			}
547			if (litArg == null) {
548				return null;
549			}
550			switch (arith.getOp()) {
551				case ADD:
552					// fix 'c + (-1)' to 'c - (1)'
553					if (litArg.isNegative()) {
554						LiteralArg negLitArg = litArg.negate();
555						if (negLitArg != null) {
556							RegisterArg resArg = InsnNode.duplicateArg(arith.getResult());
557							ArithNode newInsn = new ArithNode(ArithOp.SUB, resArg, arith.getArg(0).duplicate(), negLitArg);
558							newInsn.copyAttributesFrom(arith);
559							newInsn.setOffset(arith.getOffset());
560							return newInsn;
561						}
562					}
563					break;
564	
565				case XOR:
566					// simplify xor on boolean
567					InsnArg firstArg = arith.getArg(0);
568					long lit = litArg.getLiteral();
569					if (firstArg.getType() == ArgType.BOOLEAN && (lit == 0 || lit == 1)) {
570						InsnNode newInsn = new InsnNode(lit == 0 ? InsnType.MOVE : InsnType.NOT, 1);
571						newInsn.setResult(InsnNode.duplicateArg(arith.getResult()));
572						newInsn.addArg(firstArg.duplicate());
573						newInsn.copyAttributesFrom(arith);
574						newInsn.setOffset(arith.getOffset());
575						return newInsn;
576					}
577					break;
578			}
579			return null;
580		}
581	
582		/**
583		 * Convert field arith operation to arith instruction
584		 * (IPUT (ARITH (IGET, lit)) -> ARITH ((IGET)) <op>= lit))
585		 */
586		private static ArithNode convertFieldArith(MethodNode mth, InsnNode insn) {
587			InsnArg arg = insn.getArg(0);
588			if (!arg.isInsnWrap()) {
589				return null;
590			}
591			InsnNode wrap = ((InsnWrapArg) arg).getWrapInsn();
592			InsnType wrapType = wrap.getType();
593			if (wrapType != InsnType.ARITH && wrapType != InsnType.STR_CONCAT
594					|| !wrap.getArg(0).isInsnWrap()) {
595				return null;
596			}
597			InsnArg getWrap = wrap.getArg(0);
598			InsnNode get = ((InsnWrapArg) getWrap).getWrapInsn();
599			InsnType getType = get.getType();
600			if (getType != InsnType.IGET && getType != InsnType.SGET) {
601				return null;
602			}
603			FieldInfo field = (FieldInfo) ((IndexInsnNode) insn).getIndex();
604			FieldInfo innerField = (FieldInfo) ((IndexInsnNode) get).getIndex();
605			if (!field.equals(innerField)) {
606				return null;
607			}
608			try {
609				if (getType == InsnType.IGET && insn.getType() == InsnType.IPUT) {
610					InsnArg reg = get.getArg(0);
611					InsnArg putReg = insn.getArg(1);
612					if (!reg.equals(putReg)) {
613						return null;
614					}
615				}
616				InsnArg fArg = getWrap.duplicate();
617				InsnRemover.unbindInsn(mth, get);
618				if (insn.getType() == InsnType.IPUT) {
619					InsnRemover.unbindArgUsage(mth, insn.getArg(1));
620				}
621				if (wrapType == InsnType.ARITH) {
622					ArithNode ar = (ArithNode) wrap;
623					ArithNode newInsn = ArithNode.oneArgOp(ar.getOp(), fArg, ar.getArg(1).duplicate());
624					newInsn.copyAttributesFrom(insn);
625					newInsn.setOffset(insn.getOffset());
626					return newInsn;
627				}
628				int argsCount = wrap.getArgsCount();
629				InsnNode concat = new InsnNode(InsnType.STR_CONCAT, argsCount - 1);
630				for (int i = 1; i < argsCount; i++) {
631					concat.addArg(wrap.getArg(i).duplicate());
632				}
633				InsnArg concatArg = InsnArg.wrapArg(concat);
634				concatArg.setType(ArgType.STRING);
635				ArithNode newInsn = ArithNode.oneArgOp(ArithOp.ADD, fArg, concatArg);
636				newInsn.copyAttributesFrom(wrap);
637				newInsn.setOffset(wrap.getOffset());
638				return newInsn;
639			} catch (Exception e) {
640				LOG.debug("Can't convert field arith insn: {}, mth: {}", insn, mth, e);
641			}
642			return null;
643		}
644	}
