29	
30	@JadxVisitor(
31			name = "CodeShrinkVisitor",
32			desc = "Inline variables to make code smaller",
33			runAfter = { ModVisitor.class }
34	)
35	public class CodeShrinkVisitor extends AbstractVisitor {
36	
37		@Override
38		public void visit(MethodNode mth) {
39			shrinkMethod(mth);
40		}
41	
42		public static void shrinkMethod(MethodNode mth) {
43			if (mth.isNoCode()) {
44				return;
45			}
46			mth.remove(AFlag.REQUEST_CODE_SHRINK);
47			for (BlockNode block : mth.getBasicBlocks()) {
48				shrinkBlock(mth, block);
49				simplifyMoveInsns(mth, block);
50			}
51		}
52	
53		private static void shrinkBlock(MethodNode mth, BlockNode block) {
54			if (block.getInstructions().isEmpty()) {
55				return;
56			}
57			InsnList insnList = new InsnList(block.getInstructions());
58			int insnCount = insnList.size();
59			List<ArgsInfo> argsList = new ArrayList<>(insnCount);
60			for (int i = 0; i < insnCount; i++) {
61				argsList.add(new ArgsInfo(insnList.get(i), argsList, i));
62			}
63			List<WrapInfo> wrapList = new ArrayList<>();
64			for (ArgsInfo argsInfo : argsList) {
65				List<RegisterArg> args = argsInfo.getArgs();
66				for (int i = args.size() - 1; i >= 0; i--) {
67					RegisterArg arg = args.get(i);
68					checkInline(mth, block, insnList, wrapList, argsInfo, arg);
69				}
70			}
71			if (!wrapList.isEmpty()) {
72				for (WrapInfo wrapInfo : wrapList) {
73					inline(mth, wrapInfo.getArg(), wrapInfo.getInsn(), block);
74				}
75			}
76		}
77	
78		private static void checkInline(MethodNode mth, BlockNode block, InsnList insnList,
79				List<WrapInfo> wrapList, ArgsInfo argsInfo, RegisterArg arg) {
80			if (arg.contains(AFlag.DONT_INLINE)
81					|| arg.getParentInsn() == null
82					|| arg.getParentInsn().contains(AFlag.DONT_GENERATE)) {
83				return;
84			}
85			SSAVar sVar = arg.getSVar();
86			if (sVar == null || sVar.getAssign().contains(AFlag.DONT_INLINE)) {
87				return;
88			}
89			InsnNode assignInsn = sVar.getAssign().getParentInsn();
90			if (assignInsn == null
91					|| assignInsn.contains(AFlag.DONT_INLINE)
92					|| assignInsn.contains(AFlag.WRAPPED)) {
93				return;
94			}
95			boolean assignInline = assignInsn.contains(AFlag.FORCE_ASSIGN_INLINE);
96			if (!assignInline && sVar.isUsedInPhi()) {
97				return;
98			}
99			// allow inline only one use arg
100			int useCount = 0;
101			for (RegisterArg useArg : sVar.getUseList()) {
102				InsnNode parentInsn = useArg.getParentInsn();
103				if (parentInsn != null && parentInsn.contains(AFlag.DONT_GENERATE)) {
104					continue;
105				}
106				if (!assignInline && useArg.contains(AFlag.DONT_INLINE_CONST)) {
107					return;
108				}
109				useCount++;
110			}
111			if (!assignInline && useCount != 1) {
112				return;
113			}
114			if (!assignInline && sVar.getName() != null) {
115				if (!searchArgWithName(assignInsn, sVar.getName()) && !varWithSameNameExists(mth, sVar)) {
116					return;
117				}
118			}
119			if (!checkLambdaInline(arg, assignInsn)) {
120				return;
121			}
122	
123			int assignPos = insnList.getIndex(assignInsn);
124			if (assignPos != -1) {
125				WrapInfo wrapInfo = argsInfo.checkInline(assignPos, arg);
126				if (wrapInfo != null) {
127					wrapList.add(wrapInfo);
128				}
129			} else {
130				// another block
131				BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
132				if (assignBlock != null
133						&& assignInsn != arg.getParentInsn()
134						&& canMoveBetweenBlocks(mth, assignInsn, assignBlock, block, argsInfo.getInsn())) {
135					if (assignInline) {
136						assignInline(mth, arg, assignInsn, assignBlock);
137					} else {
138						inline(mth, arg, assignInsn, assignBlock);
139					}
140				}
141			}
142		}
143	
144		/**
145		 * Forbid inline lambda into invoke as an instance arg, i.e. this will not compile:
146		 * {@code () -> { ... }.apply(); }
147		 */
148		private static boolean checkLambdaInline(RegisterArg arg, InsnNode assignInsn) {
149			if (assignInsn.getType() == InsnType.INVOKE && assignInsn instanceof InvokeCustomNode) {
150				for (RegisterArg useArg : arg.getSVar().getUseList()) {
151					InsnNode parentInsn = useArg.getParentInsn();
152					if (parentInsn != null && parentInsn.getType() == InsnType.INVOKE) {
153						InvokeNode invokeNode = (InvokeNode) parentInsn;
154						InsnArg instArg = invokeNode.getInstanceArg();
155						if (instArg != null && instArg == useArg) {
156							return false;
157						}
158					}
159				}
160			}
161			return true;
162		}
163	
164		private static boolean varWithSameNameExists(MethodNode mth, SSAVar inlineVar) {
165			for (SSAVar ssaVar : mth.getSVars()) {
166				if (ssaVar == inlineVar || ssaVar.getCodeVar() == inlineVar.getCodeVar()) {
167					continue;
168				}
169				if (Objects.equals(ssaVar.getName(), inlineVar.getName())) {
170					return ssaVar.getUseCount() > inlineVar.getUseCount();
171				}
172			}
173			return false;
174		}
175	
176		private static boolean searchArgWithName(InsnNode assignInsn, String varName) {
177			InsnArg result = assignInsn.visitArgs(insnArg -> {
178				if (insnArg instanceof Named) {
179					String argName = ((Named) insnArg).getName();
180					if (Objects.equals(argName, varName)) {
181						return insnArg;
182					}
183				}
184				return null;
185			});
186			return result != null;
187		}
188	
189		private static boolean assignInline(MethodNode mth, RegisterArg arg, InsnNode assignInsn, BlockNode assignBlock) {
190			RegisterArg useArg = arg.getSVar().getUseList().get(0);
191			InsnNode useInsn = useArg.getParentInsn();
192			if (useInsn == null || useInsn.contains(AFlag.DONT_GENERATE)) {
193				return false;
194			}
195			if (!InsnRemover.removeWithoutUnbind(mth, assignBlock, assignInsn)) {
196				return false;
197			}
198			useArg.wrapInstruction(mth, assignInsn);
199			return true;
200		}
201	
202		private static boolean inline(MethodNode mth, RegisterArg arg, InsnNode insn, BlockNode block) {
203			if (insn.contains(AFlag.FORCE_ASSIGN_INLINE)) {
204				return assignInline(mth, arg, insn, block);
205			}
206			// just move instruction into arg, don't unbind/copy/duplicate
207			InsnArg wrappedArg = arg.wrapInstruction(mth, insn, false);
208			boolean replaced = wrappedArg != null;
209			if (replaced) {
210				InsnNode parentInsn = arg.getParentInsn();
211				if (parentInsn != null) {
212					parentInsn.inheritMetadata(insn);
213				}
214				InsnRemover.unbindResult(mth, insn);
215				InsnRemover.removeWithoutUnbind(mth, block, insn);
216			}
217			return replaced;
218		}
219	
220		private static boolean canMoveBetweenBlocks(MethodNode mth, InsnNode assignInsn, BlockNode assignBlock,
221				BlockNode useBlock, InsnNode useInsn) {
222			if (!BlockUtils.isPathExists(assignBlock, useBlock)) {
223				return false;
224			}
225	
226			List<RegisterArg> argsList = ArgsInfo.getArgs(assignInsn);
227			BitSet args = new BitSet();
228			for (RegisterArg arg : argsList) {
229				args.set(arg.getRegNum());
230			}
231			boolean startCheck = false;
232			for (InsnNode insn : assignBlock.getInstructions()) {
233				if (startCheck && (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args))) {
234					return false;
235				}
236				if (insn == assignInsn) {
237					startCheck = true;
238				}
239			}
240			Set<BlockNode> pathsBlocks = BlockUtils.getAllPathsBlocks(assignBlock, useBlock);
241			pathsBlocks.remove(assignBlock);
242			pathsBlocks.remove(useBlock);
243			for (BlockNode block : pathsBlocks) {
244				if (block.contains(AFlag.DONT_GENERATE)) {
245					if (BlockUtils.checkLastInsnType(block, InsnType.MONITOR_EXIT)) {
246						if (RegionUtils.isBlocksInSameRegion(mth, assignBlock, useBlock)) {
247							// allow move inside same synchronized region
248						} else {
249							// don't move from synchronized block
250							return false;
251						}
252					}
253					// skip checks for not generated blocks
254					continue;
255				}
256				for (InsnNode insn : block.getInstructions()) {
257					if (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args)) {
258						return false;
259					}
260				}
261			}
262			for (InsnNode insn : useBlock.getInstructions()) {
263				if (insn == useInsn) {
264					return true;
265				}
266				if (!insn.canReorder() || ArgsInfo.usedArgAssign(insn, args)) {
267					return false;
268				}
269			}
270			throw new JadxRuntimeException("Can't process instruction move : " + assignBlock);
271		}
272	
273		private static void simplifyMoveInsns(MethodNode mth, BlockNode block) {
274			List<InsnNode> insns = block.getInstructions();
275			int size = insns.size();
276			for (int i = 0; i < size; i++) {
277				InsnNode insn = insns.get(i);
278				if (insn.getType() == InsnType.MOVE) {
279					// replace 'move' with wrapped insn
280					InsnArg arg = insn.getArg(0);
281					if (arg.isInsnWrap()) {
282						InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
283						InsnRemover.unbindResult(mth, wrapInsn);
284						wrapInsn.setResult(insn.getResult().duplicate());
285						wrapInsn.inheritMetadata(insn);
286						wrapInsn.setOffset(insn.getOffset());
287						wrapInsn.remove(AFlag.WRAPPED);
288						block.getInstructions().set(i, wrapInsn);
289					}
290				}
291			}
292		}
293	}
