32	@JadxVisitor(
33			name = "SSATransform",
34			desc = "Calculate Single Side Assign (SSA) variables",
35			runAfter = BlockProcessor.class
36	)
37	public class SSATransform extends AbstractVisitor {
38	
39		@Override
40		public void visit(MethodNode mth) throws JadxException {
41			if (mth.isNoCode()) {
42				return;
43			}
44			process(mth);
45		}
46	
47		private static void process(MethodNode mth) {
48			if (!mth.getSVars().isEmpty()) {
49				return;
50			}
51			LiveVarAnalysis la = new LiveVarAnalysis(mth);
52			la.runAnalysis();
53			int regsCount = mth.getRegsCount();
54			for (int i = 0; i < regsCount; i++) {
55				placePhi(mth, i, la);
56			}
57			renameVariables(mth);
58			fixLastAssignInTry(mth);
59			removeBlockerInsns(mth);
60			tryToFixUselessPhi(mth);
61			markThisArgs(mth.getThisArg());
62			hidePhiInsns(mth);
63			removeUnusedInvokeResults(mth);
64		}
65	
66		private static void placePhi(MethodNode mth, int regNum, LiveVarAnalysis la) {
67			List<BlockNode> blocks = mth.getBasicBlocks();
68			int blocksCount = blocks.size();
69			BitSet hasPhi = new BitSet(blocksCount);
70			BitSet processed = new BitSet(blocksCount);
71			Deque<BlockNode> workList = new ArrayDeque<>();
72	
73			BitSet assignBlocks = la.getAssignBlocks(regNum);
74			for (int id = assignBlocks.nextSetBit(0); id >= 0; id = assignBlocks.nextSetBit(id + 1)) {
75				processed.set(id);
76				workList.add(blocks.get(id));
77			}
78			while (!workList.isEmpty()) {
79				BlockNode block = workList.pop();
80				BitSet domFrontier = block.getDomFrontier();
81				for (int id = domFrontier.nextSetBit(0); id >= 0; id = domFrontier.nextSetBit(id + 1)) {
82					if (!hasPhi.get(id) && la.isLive(id, regNum)) {
83						BlockNode df = blocks.get(id);
84						PhiInsn phiInsn = addPhi(mth, df, regNum);
85						df.getInstructions().add(0, phiInsn);
86						hasPhi.set(id);
87						if (!processed.get(id)) {
88							processed.set(id);
89							workList.add(df);
90						}
91					}
92				}
93			}
94		}
