96		public static PhiInsn addPhi(MethodNode mth, BlockNode block, int regNum) {
97			PhiListAttr phiList = block.get(AType.PHI_LIST);
98			if (phiList == null) {
99				phiList = new PhiListAttr();
100				block.addAttr(phiList);

100				block.addAttr(phiList);
101			}
102			int size = block.getPredecessors().size();
103			if (mth.getEnterBlock() == block) {
104				RegisterArg thisArg = mth.getThisArg();
105				if (thisArg != null && thisArg.getRegNum() == regNum) {
106					size++;
107				} else {
108					for (RegisterArg arg : mth.getArgRegs()) {
109						if (arg.getRegNum() == regNum) {
110							size++;
111							break;
112						}
113					}
114				}
115			}
116			PhiInsn phiInsn = new PhiInsn(regNum, size);
117			phiList.getList().add(phiInsn);
118			phiInsn.setOffset(block.getStartOffset());
119			return phiInsn;
120		}
