122		private static void renameVariables(MethodNode mth) {
123			RenameState initState = RenameState.init(mth);
124			initPhiInEnterBlock(initState);
125	
126			Deque<RenameState> stack = new ArrayDeque<>();
127			stack.push(initState);
128			while (!stack.isEmpty()) {
129				RenameState state = stack.pop();
130				renameVarsInBlock(mth, state);
131				for (BlockNode dominated : state.getBlock().getDominatesOn()) {
132					stack.push(RenameState.copyFrom(state, dominated));
133				}
134			}
135		}
136	
137		private static void initPhiInEnterBlock(RenameState initState) {
138			PhiListAttr phiList = initState.getBlock().get(AType.PHI_LIST);
139			if (phiList != null) {
140				for (PhiInsn phiInsn : phiList.getList()) {
141					bindPhiArg(initState, phiInsn);
142				}
143			}
144		}
145	
146		private static void renameVarsInBlock(MethodNode mth, RenameState state) {
147			BlockNode block = state.getBlock();
148			for (InsnNode insn : block.getInstructions()) {
149				if (insn.getType() != InsnType.PHI) {
150					for (InsnArg arg : insn.getArguments()) {
151						if (!arg.isRegister()) {
152							continue;
153						}
154						RegisterArg reg = (RegisterArg) arg;
155						int regNum = reg.getRegNum();
156						SSAVar var = state.getVar(regNum);
157						if (var == null) {
158							// TODO: in most cases issue in incorrectly attached exception handlers
159							mth.addWarnComment("Not initialized variable reg: " + regNum + ", insn: " + insn + ", block:" + block);
160							var = state.startVar(reg);
161						}
162						var.use(reg);
163					}
164				}
165				RegisterArg result = insn.getResult();
166				if (result != null) {
167					state.startVar(result);
168				}
169			}
170			for (BlockNode s : block.getSuccessors()) {
171				PhiListAttr phiList = s.get(AType.PHI_LIST);
172				if (phiList == null) {
173					continue;
174				}
175				for (PhiInsn phiInsn : phiList.getList()) {
176					bindPhiArg(state, phiInsn);
177				}
178			}
179		}
180	
181		private static void bindPhiArg(RenameState state, PhiInsn phiInsn) {
182			int regNum = phiInsn.getResult().getRegNum();
183			SSAVar var = state.getVar(regNum);
184			if (var == null) {
185				return;
186			}
187			RegisterArg arg = phiInsn.bindArg(state.getBlock());
188			var.use(arg);
189			var.addUsedInPhi(phiInsn);
190		}
