192		/**
193		 * Fix last try/catch assign instruction
194		 */
195		private static void fixLastAssignInTry(MethodNode mth) {
196			for (BlockNode block : mth.getBasicBlocks()) {
197				PhiListAttr phiList = block.get(AType.PHI_LIST);
198				if (phiList != null) {
199					ExcHandlerAttr handlerAttr = block.get(AType.EXC_HANDLER);
200					if (handlerAttr != null) {
201						for (PhiInsn phi : phiList.getList()) {
202							fixPhiInTryCatch(mth, phi, handlerAttr);
203						}
204					}
205				}
206			}
207		}
208	
209		private static void fixPhiInTryCatch(MethodNode mth, PhiInsn phi, ExcHandlerAttr handlerAttr) {
210			int argsCount = phi.getArgsCount();
211			int k = 0;
212			while (k < argsCount) {
213				RegisterArg arg = phi.getArg(k);
214				if (shouldSkipInsnResult(mth, arg.getAssignInsn(), handlerAttr)) {
215					phi.removeArg(arg);
216					argsCount--;
217				} else {
218					k++;
219				}
220			}
221			if (phi.getArgsCount() == 0) {
222				throw new JadxRuntimeException("PHI empty after try-catch fix!");
223			}
224		}
225	
226		private static boolean shouldSkipInsnResult(MethodNode mth, InsnNode insn, ExcHandlerAttr handlerAttr) {
227			if (insn != null
228					&& insn.getResult() != null
229					&& insn.contains(AFlag.TRY_LEAVE)) {
230				CatchAttr catchAttr = BlockUtils.getCatchAttrForInsn(mth, insn);
231				return catchAttr != null && catchAttr.getHandlers().contains(handlerAttr.getHandler());
232			}
233			return false;
234		}
