259		private static void tryToFixUselessPhi(MethodNode mth) {
260			int k = 0;
261			int maxTries = mth.getSVars().size() * 2;
262			while (fixUselessPhi(mth)) {
263				if (k++ > maxTries) {
264					throw new JadxRuntimeException("Phi nodes fix limit reached!");
265				}
266			}
267		}
268	
269		private static boolean fixUselessPhi(MethodNode mth) {
270			boolean changed = false;
271			List<PhiInsn> insnToRemove = new ArrayList<>();
272			for (SSAVar var : mth.getSVars()) {
273				// phi result not used
274				if (var.getUseCount() == 0) {
275					InsnNode assignInsn = var.getAssign().getParentInsn();
276					if (assignInsn != null && assignInsn.getType() == InsnType.PHI) {
277						insnToRemove.add((PhiInsn) assignInsn);
278						changed = true;
279					}
280				}
281			}
282			for (BlockNode block : mth.getBasicBlocks()) {
283				PhiListAttr phiList = block.get(AType.PHI_LIST);
284				if (phiList == null) {
285					continue;
286				}
287				Iterator<PhiInsn> it = phiList.getList().iterator();
288				while (it.hasNext()) {
289					PhiInsn phi = it.next();
290					if (fixPhiWithSameArgs(mth, block, phi)) {
291						it.remove();
292						changed = true;
293					}
294				}
295			}
296			removePhiList(mth, insnToRemove);
297			return changed;
298		}
