300		private static boolean fixPhiWithSameArgs(MethodNode mth, BlockNode block, PhiInsn phi) {
301			if (phi.getArgsCount() == 0) {
302				for (RegisterArg useArg : phi.getResult().getSVar().getUseList()) {
303					InsnNode useInsn = useArg.getParentInsn();
304					if (useInsn != null && useInsn.getType() == InsnType.PHI) {
305						phi.removeArg(useArg);
306					}
307				}
308				InsnRemover.remove(mth, block, phi);
309				return true;
310			}
311			boolean allSame = phi.getArgsCount() == 1 || isSameArgs(phi);
312			if (allSame) {
313				return replacePhiWithMove(mth, block, phi, phi.getArg(0));
314			}
315			SSAVar sameVar = isSameMove(phi);
316			if (sameVar != null) {
317				RegisterArg sameArg = sameVar.getAssign().duplicate();
318				if (inlinePhiInsn(mth, block, phi, sameArg)) {
319					for (InsnArg arg : phi.getArguments()) {
320						InsnNode moveInsn = ((RegisterArg) arg).getAssignInsn();
321						if (moveInsn != null) {
322							moveInsn.add(AFlag.REMOVE);
323							InsnRemover.remove(mth, moveInsn);
324						}
325					}
326					return true;
327				}
328			}
329			return false;
330		}
