332		private static boolean isSameArgs(PhiInsn phi) {
333			boolean allSame = true;
334			SSAVar var = null;
335			for (int i = 0; i < phi.getArgsCount(); i++) {
336				RegisterArg arg = phi.getArg(i);
337				if (var == null) {
338					var = arg.getSVar();
339				} else if (var != arg.getSVar()) {
340					allSame = false;
341					break;
342				}
343			}
344			return allSame;
345		}
346	
347		private static SSAVar isSameMove(PhiInsn phi) {
348			SSAVar var = null;
349			int argsCount = phi.getArgsCount();
350			for (int i = 0; i < argsCount; i++) {
351				RegisterArg arg = phi.getArg(i);
352				if (arg.getSVar().getUseCount() != 1) {
353					return null;
354				}
355				InsnNode assignInsn = arg.getAssignInsn();
356				if (assignInsn == null || assignInsn.getType() != InsnType.MOVE) {
357					return null;
358				}
359				InsnArg moveArg = assignInsn.getArg(0);
360				if (!moveArg.isRegister()) {
361					return null;
362				}
363				SSAVar moveVar = ((RegisterArg) moveArg).getSVar();
364				if (var == null) {
365					var = moveVar;
366				} else if (var != moveVar) {
367					return null;
368				}
369			}
370			return var;
371		}
