373		private static boolean removePhiList(MethodNode mth, List<PhiInsn> insnToRemove) {
374			for (BlockNode block : mth.getBasicBlocks()) {
375				PhiListAttr phiList = block.get(AType.PHI_LIST);
376				if (phiList == null) {
377					continue;
378				}
379				List<PhiInsn> list = phiList.getList();
380				for (PhiInsn phiInsn : insnToRemove) {
381					if (list.remove(phiInsn)) {
382						for (InsnArg arg : phiInsn.getArguments()) {
383							if (arg == null) {
384								continue;
385							}
386							SSAVar sVar = ((RegisterArg) arg).getSVar();
387							if (sVar != null) {
388								sVar.removeUsedInPhi(phiInsn);
389							}
390						}
391						InsnRemover.remove(mth, block, phiInsn);
392					}
393				}
394				if (list.isEmpty()) {
395					block.remove(AType.PHI_LIST);
396				}
397			}
398			insnToRemove.clear();
399			return true;
400		}
