402		private static boolean replacePhiWithMove(MethodNode mth, BlockNode block, PhiInsn phi, RegisterArg arg) {
403			List<InsnNode> insns = block.getInstructions();
404			int phiIndex = InsnList.getIndex(insns, phi);
405			if (phiIndex == -1) {
406				return false;
407			}
408			SSAVar assign = phi.getResult().getSVar();
409			SSAVar argVar = arg.getSVar();
410			if (argVar != null) {
411				argVar.removeUse(arg);
412				argVar.removeUsedInPhi(phi);
413			}
414			// try inline
415			if (inlinePhiInsn(mth, block, phi, phi.getArg(0))) {
416				insns.remove(phiIndex);
417			} else {
418				assign.removeUsedInPhi(phi);
419	
420				InsnNode m = new InsnNode(InsnType.MOVE, 1);
421				m.add(AFlag.SYNTHETIC);
422				m.setResult(phi.getResult());
423				m.addArg(arg);
424				arg.getSVar().use(arg);
425				insns.set(phiIndex, m);
426			}
427			return true;
428		}
