48	public class BlockExceptionHandler {
49		private static final Logger LOG = LoggerFactory.getLogger(BlockExceptionHandler.class);
50	
51		public static boolean process(MethodNode mth) {
52			if (mth.isNoExceptionHandlers()) {
53				return false;
54			}
55			BlockProcessor.updateCleanSuccessors(mth);
56			DominatorTree.computeDominanceFrontier(mth);
57	
58			processCatchAttr(mth);
59			initExcHandlers(mth);
60	
61			List<TryCatchBlockAttr> tryBlocks = prepareTryBlocks(mth);
62			connectExcHandlers(mth, tryBlocks);
63			mth.addAttr(AType.TRY_BLOCKS_LIST, tryBlocks);
64			mth.getBasicBlocks().forEach(BlockNode::updateCleanSuccessors);
65	
66			for (ExceptionHandler eh : mth.getExceptionHandlers()) {
67				removeMonitorExitFromExcHandler(mth, eh);
68			}
69			BlockProcessor.removeMarkedBlocks(mth);
70	
71			BlockSet sorted = new BlockSet(mth);
72			BlockUtils.visitDFS(mth, sorted::add);
73			removeUnusedExcHandlers(mth, tryBlocks, sorted);
74			return true;
75		}
76	
77		/**
78		 * Wrap try blocks with top/bottom splitter and connect them to handler block.
79		 * Sometimes try block can be handler block itself and should be connected before wrapping.
80		 * Use queue for postpone try blocks not ready for wrap.
81		 */
82		private static void connectExcHandlers(MethodNode mth, List<TryCatchBlockAttr> tryBlocks) {
83			if (tryBlocks.isEmpty()) {
84				return;
85			}
86			int limit = tryBlocks.size() * 3;
87			int count = 0;
88			Deque<TryCatchBlockAttr> queue = new ArrayDeque<>(tryBlocks);
89			while (!queue.isEmpty()) {
90				TryCatchBlockAttr tryBlock = queue.removeFirst();
91				boolean complete = wrapBlocksWithTryCatch(mth, tryBlock);
92				if (!complete) {
93					queue.addLast(tryBlock); // return to queue at the end
94				}
95				if (count++ > limit) {
96					throw new JadxRuntimeException("Try blocks wrapping queue limit reached! Please report as an issue!");
97				}
98			}
99		}
100	
101		private static void processCatchAttr(MethodNode mth) {
102			for (BlockNode block : mth.getBasicBlocks()) {
103				for (InsnNode insn : block.getInstructions()) {
104					if (insn.contains(AType.EXC_CATCH) && !insn.canThrowException()) {
105						insn.remove(AType.EXC_CATCH);
106					}
107				}
108			}
109			// if all instructions in block have same 'catch' attribute -> add this attribute for whole block.
110			for (BlockNode block : mth.getBasicBlocks()) {
111				CatchAttr commonCatchAttr = getCommonCatchAttr(block);
112				if (commonCatchAttr != null) {
113					block.addAttr(commonCatchAttr);
114					for (InsnNode insn : block.getInstructions()) {
115						if (insn.contains(AFlag.TRY_ENTER)) {
116							block.add(AFlag.TRY_ENTER);
117						}
118						if (insn.contains(AFlag.TRY_LEAVE)) {
119							block.add(AFlag.TRY_LEAVE);
120						}
121					}
122				}
123			}
124		}
125	
126		@Nullable
127		private static CatchAttr getCommonCatchAttr(BlockNode block) {
128			CatchAttr commonCatchAttr = null;
129			for (InsnNode insn : block.getInstructions()) {
130				CatchAttr catchAttr = insn.get(AType.EXC_CATCH);
131				if (catchAttr != null) {
132					if (commonCatchAttr == null) {
133						commonCatchAttr = catchAttr;
134						continue;
135					}
136					if (!commonCatchAttr.equals(catchAttr)) {
137						return null;
138					}
139				}
140			}
141			return commonCatchAttr;
142		}
143	
144		@SuppressWarnings("ForLoopReplaceableByForEach")
145		private static void initExcHandlers(MethodNode mth) {
146			List<BlockNode> blocks = mth.getBasicBlocks();
147			int blocksCount = blocks.size();
148			for (int i = 0; i < blocksCount; i++) { // will add new blocks to list end
149				BlockNode block = blocks.get(i);
150				InsnNode firstInsn = BlockUtils.getFirstInsn(block);
151				if (firstInsn == null) {
152					continue;
153				}
154				ExcHandlerAttr excHandlerAttr = firstInsn.get(AType.EXC_HANDLER);
155				if (excHandlerAttr == null) {
156					continue;
157				}
158				firstInsn.remove(AType.EXC_HANDLER);
159				removeTmpConnection(block);
160	
161				ExceptionHandler excHandler = excHandlerAttr.getHandler();
162				if (block.getPredecessors().isEmpty()) {
163					excHandler.setHandlerBlock(block);
164					block.addAttr(excHandlerAttr);
165					excHandler.addBlock(block);
166					BlockUtils.collectBlocksDominatedByWithExcHandlers(mth, block, block)
167							.forEach(excHandler::addBlock);
168				} else {
169					// ignore already connected handlers -> make catch empty
170					BlockNode emptyHandlerBlock = BlockSplitter.startNewBlock(mth, block.getStartOffset());
171					emptyHandlerBlock.add(AFlag.SYNTHETIC);
172					emptyHandlerBlock.addAttr(excHandlerAttr);
173					BlockSplitter.connect(emptyHandlerBlock, block);
174					excHandler.setHandlerBlock(emptyHandlerBlock);
175					excHandler.addBlock(emptyHandlerBlock);
176				}
177				fixMoveExceptionInsn(block, excHandlerAttr);
178			}
179		}
180	
181		private static void removeTmpConnection(BlockNode block) {
182			TmpEdgeAttr tmpEdgeAttr = block.get(AType.TMP_EDGE);
183			if (tmpEdgeAttr != null) {
184				// remove temp connection
185				BlockSplitter.removeConnection(tmpEdgeAttr.getBlock(), block);
186				block.remove(AType.TMP_EDGE);
187			}
188		}
189	
190		private static List<TryCatchBlockAttr> prepareTryBlocks(MethodNode mth) {
191			Map<ExceptionHandler, List<BlockNode>> blocksByHandler = new HashMap<>();
192			for (BlockNode block : mth.getBasicBlocks()) {
193				CatchAttr catchAttr = block.get(AType.EXC_CATCH);
194				if (catchAttr != null) {
195					for (ExceptionHandler eh : catchAttr.getHandlers()) {
196						blocksByHandler
197								.computeIfAbsent(eh, c -> new ArrayList<>())
198								.add(block);
199					}
200				}
201			}
202			if (Consts.DEBUG_EXC_HANDLERS) {
203				LOG.debug("Input exception handlers:");
204				blocksByHandler.forEach((eh, blocks) -> LOG.debug(" {}, throw blocks: {}, handler blocks: {}", eh, blocks, eh.getBlocks()));
205			}
206			if (blocksByHandler.isEmpty()) {
207				// no catch blocks -> remove all handlers
208				mth.getExceptionHandlers().forEach(eh -> removeExcHandler(mth, eh));
209			} else {
210				// remove handlers without blocks in catch attribute
211				blocksByHandler.forEach((eh, blocks) -> {
212					if (blocks.isEmpty()) {
213						removeExcHandler(mth, eh);
214					}
215				});
216			}
217			BlockSplitter.detachMarkedBlocks(mth);
218			mth.clearExceptionHandlers();
219			if (mth.isNoExceptionHandlers()) {
220				return Collections.emptyList();
221			}
222	
223			blocksByHandler.forEach((eh, blocks) -> {
224				// remove catches from same handler
225				blocks.removeAll(eh.getBlocks());
226			});
227	
228			List<TryCatchBlockAttr> tryBlocks = new ArrayList<>();
229			blocksByHandler.forEach((eh, blocks) -> {
230				List<ExceptionHandler> handlers = new ArrayList<>(1);
231				handlers.add(eh);
232				tryBlocks.add(new TryCatchBlockAttr(tryBlocks.size(), handlers, blocks));
233			});
234			if (tryBlocks.size() > 1) {
235				// merge or mark as outer/inner
236				while (true) {
237					boolean restart = combineTryCatchBlocks(tryBlocks);
238					if (!restart) {
239						break;
240					}
241				}
242			}
243			checkForMultiCatch(mth, tryBlocks);
244			clearTryBlocks(mth, tryBlocks);
245			sortHandlers(mth, tryBlocks);
246	
247			if (Consts.DEBUG_EXC_HANDLERS) {
248				LOG.debug("Result try-catch blocks:");
249				tryBlocks.forEach(tryBlock -> LOG.debug(" {}", tryBlock));
250			}
251			return tryBlocks;
252		}
253	
254		private static void clearTryBlocks(MethodNode mth, List<TryCatchBlockAttr> tryBlocks) {
255			tryBlocks.forEach(tc -> tc.getBlocks().removeIf(b -> b.contains(AFlag.REMOVE)));
256			tryBlocks.removeIf(tb -> tb.getBlocks().isEmpty() || tb.getHandlers().isEmpty());
257			mth.clearExceptionHandlers();
258			BlockSplitter.detachMarkedBlocks(mth);
259		}
260	
261		private static boolean combineTryCatchBlocks(List<TryCatchBlockAttr> tryBlocks) {
262			for (TryCatchBlockAttr outerTryBlock : tryBlocks) {
263				for (TryCatchBlockAttr innerTryBlock : tryBlocks) {
264					if (outerTryBlock == innerTryBlock || innerTryBlock.getOuterTryBlock() != null) {
265						continue;
266					}
267					if (checkTryCatchRelation(tryBlocks, outerTryBlock, innerTryBlock)) {
268						return true;
269					}
270				}
271			}
272			return false;
273		}
274	
275		private static boolean checkTryCatchRelation(List<TryCatchBlockAttr> tryBlocks,
276				TryCatchBlockAttr outerTryBlock, TryCatchBlockAttr innerTryBlock) {
277			if (outerTryBlock.getBlocks().equals(innerTryBlock.getBlocks())) {
278				// same try blocks -> merge handlers
279				List<ExceptionHandler> handlers = Utils.concatDistinct(outerTryBlock.getHandlers(), innerTryBlock.getHandlers());
280				tryBlocks.add(new TryCatchBlockAttr(tryBlocks.size(), handlers, outerTryBlock.getBlocks()));
281				tryBlocks.remove(outerTryBlock);
282				tryBlocks.remove(innerTryBlock);
283				return true;
284			}
285	
286			Set<BlockNode> handlerBlocks = new HashSet<>();
287			for (ExceptionHandler eh : innerTryBlock.getHandlers()) {
288				handlerBlocks.addAll(eh.getBlocks());
289			}
290			boolean catchInHandler = ListUtils.anyMatch(handlerBlocks, isHandlersIntersects(outerTryBlock));
291			boolean catchInTry = ListUtils.anyMatch(innerTryBlock.getBlocks(), isHandlersIntersects(outerTryBlock));
292			boolean blocksOutsideHandler = ListUtils.anyMatch(outerTryBlock.getBlocks(), b -> !handlerBlocks.contains(b));
293	
294			if (catchInHandler && (catchInTry || blocksOutsideHandler)) {
295				// convert to inner
296				List<BlockNode> mergedBlocks = Utils.concatDistinct(outerTryBlock.getBlocks(), innerTryBlock.getBlocks());
297				innerTryBlock.getHandlers().removeAll(outerTryBlock.getHandlers());
298				innerTryBlock.setOuterTryBlock(outerTryBlock);
299				outerTryBlock.addInnerTryBlock(innerTryBlock);
300				outerTryBlock.setBlocks(mergedBlocks);
301				return false;
302			}
303			Set<ExceptionHandler> innerHandlerSet = new HashSet<>(innerTryBlock.getHandlers());
304			if (innerHandlerSet.containsAll(outerTryBlock.getHandlers())) {
305				// merge
306				List<BlockNode> mergedBlocks = Utils.concatDistinct(outerTryBlock.getBlocks(), innerTryBlock.getBlocks());
307				List<ExceptionHandler> handlers = Utils.concatDistinct(outerTryBlock.getHandlers(), innerTryBlock.getHandlers());
308				tryBlocks.add(new TryCatchBlockAttr(tryBlocks.size(), handlers, mergedBlocks));
309				tryBlocks.remove(outerTryBlock);
310				tryBlocks.remove(innerTryBlock);
311				return true;
312			}
313			return false;
314		}
315	
316		@NotNull
317		private static Predicate<BlockNode> isHandlersIntersects(TryCatchBlockAttr outerTryBlock) {
318			return block -> {
319				CatchAttr catchAttr = block.get(AType.EXC_CATCH);
320				return catchAttr != null && Objects.equals(catchAttr.getHandlers(), outerTryBlock.getHandlers());
321			};
322		}
