329		private static boolean wrapBlocksWithTryCatch(MethodNode mth, TryCatchBlockAttr tryCatchBlock) {
330			List<BlockNode> blocks = tryCatchBlock.getBlocks();
331			BlockNode top = searchTopBlock(mth, blocks);
332			if (top.getPredecessors().isEmpty() && top != mth.getEnterBlock()) {
333				return false;
334			}
335			BlockNode bottom = searchBottomBlock(mth, blocks);
336			BlockNode splitReturn;
337			if (bottom != null && bottom.isReturnBlock()) {
338				if (Consts.DEBUG_EXC_HANDLERS) {
339					LOG.debug("TryCatch #{} bottom block ({}) is return, split", tryCatchBlock.id(), bottom);
340				}
341				splitReturn = bottom;
342				bottom = BlockSplitter.blockSplitTop(mth, bottom);
343				bottom.add(AFlag.SYNTHETIC);
344			} else {
345				splitReturn = null;
346			}
347			if (Consts.DEBUG_EXC_HANDLERS) {
348				LOG.debug("TryCatch #{} split: top {}, bottom: {}", tryCatchBlock.id(), top, bottom);
349			}
350			BlockNode topSplitterBlock = getTopSplitterBlock(mth, top);
351			topSplitterBlock.add(AFlag.EXC_TOP_SPLITTER);
352			topSplitterBlock.add(AFlag.SYNTHETIC);
353	
354			int totalHandlerBlocks = 0;
355			for (ExceptionHandler eh : tryCatchBlock.getHandlers()) {
356				totalHandlerBlocks += eh.getBlocks().size();
357			}
358	
359			BlockNode bottomSplitterBlock;
360			if (bottom == null || totalHandlerBlocks == 0) {
361				bottomSplitterBlock = null;
362			} else {
363				BlockNode existBottomSplitter = BlockUtils.getBlockWithFlag(bottom.getSuccessors(), AFlag.EXC_BOTTOM_SPLITTER);
364				bottomSplitterBlock = existBottomSplitter != null ? existBottomSplitter : BlockSplitter.startNewBlock(mth, -1);
365				bottomSplitterBlock.add(AFlag.EXC_BOTTOM_SPLITTER);
366				bottomSplitterBlock.add(AFlag.SYNTHETIC);
367				BlockSplitter.connect(bottom, bottomSplitterBlock);
368				if (splitReturn != null) {
369					// redirect handler to return block instead synthetic split block to avoid self-loop
370					BlockSet bottomPreds = BlockSet.from(mth, bottom.getPredecessors());
371					for (ExceptionHandler handler : tryCatchBlock.getHandlers()) {
372						if (bottomPreds.intersects(handler.getBlocks())) {
373							BlockNode lastBlock = bottomPreds.intersect(handler.getBlocks()).getOne();
374							if (lastBlock != null) {
375								BlockSplitter.replaceConnection(lastBlock, bottom, splitReturn);
376							}
377						}
378					}
379				}
380			}
381	
382			if (Consts.DEBUG_EXC_HANDLERS) {
383				LOG.debug("TryCatch #{} result splitters: top {}, bottom: {}",
384						tryCatchBlock.id(), topSplitterBlock, bottomSplitterBlock);
385			}
386			connectSplittersAndHandlers(tryCatchBlock, topSplitterBlock, bottomSplitterBlock);
387	
388			// At this point, it's possible that a cross edge to the original bottom has been turned into a back
389			// edge by the insertion of the new bottom. This causes problems because back edges usually signifiy
390			// loops, but this is not a loop. To fix this, predecessors of the bottom that also have a path from
391			// the bottom are rewritten to point to the original path crossing point (before synthetic blocks).
392			if (bottom != null && bottom.contains(AType.EXC_SPLIT_CROSS)) {
393				List<BlockNode> convertBlocks = new ArrayList<>();
394				for (BlockNode b : bottom.getPredecessors()) {
395					if (BlockUtils.isAnyPathExists(bottom, b)) {
396						convertBlocks.add(b);
397					}
398				}
399				for (BlockNode b : convertBlocks) {
400					// The connection can't be replaced during the first loop because it would modify the preds list.
401					BlockSplitter.replaceConnection(b, bottom, bottom.get(AType.EXC_SPLIT_CROSS).getOriginalPathCross());
402				}
403			}
404	
405			for (BlockNode block : blocks) {
406				TryCatchBlockAttr currentTCBAttr = block.get(AType.TRY_BLOCK);
407				if (currentTCBAttr == null || currentTCBAttr.getInnerTryBlocks().contains(tryCatchBlock)) {
408					block.addAttr(tryCatchBlock);
409				}
410			}
411			tryCatchBlock.setTopSplitter(topSplitterBlock);
412	
413			topSplitterBlock.updateCleanSuccessors();
414			if (bottomSplitterBlock != null) {
415				bottomSplitterBlock.updateCleanSuccessors();
416			}
417			return true;
418		}
419	
420		private static BlockNode getTopSplitterBlock(MethodNode mth, BlockNode top) {
421			if (top == mth.getEnterBlock()) {
422				BlockNode fixedTop = mth.getEnterBlock().getSuccessors().get(0);
423				return BlockSplitter.blockSplitTop(mth, fixedTop);
424			}
425			BlockNode existPredTopSplitter = BlockUtils.getBlockWithFlag(top.getPredecessors(), AFlag.EXC_TOP_SPLITTER);
426			if (existPredTopSplitter != null) {
427				return existPredTopSplitter;
428			}
429			// try to reuse exists splitter on empty simple path below top block
430			if (top.getCleanSuccessors().size() == 1 && top.getInstructions().isEmpty()) {
431				BlockNode otherTopSplitter = BlockUtils.getBlockWithFlag(top.getCleanSuccessors(), AFlag.EXC_TOP_SPLITTER);
432				if (otherTopSplitter != null && otherTopSplitter.getPredecessors().size() == 1) {
433					return otherTopSplitter;
434				}
435			}
436			return BlockSplitter.blockSplitTop(mth, top);
437		}
438	
439		private static BlockNode searchTopBlock(MethodNode mth, List<BlockNode> blocks) {
440			BlockNode top = BlockUtils.getTopBlock(blocks);
441			if (top != null) {
442				return adjustTopBlock(top);
443			}
444			BlockNode topDom = BlockUtils.getCommonDominator(mth, blocks);
445			if (topDom != null) {
446				// dominator always return one up block if blocks already contains dominator, use successor instead
447				if (topDom.getSuccessors().size() == 1) {
448					BlockNode upBlock = topDom.getSuccessors().get(0);
449					if (blocks.contains(upBlock)) {
450						return upBlock;
451					}
452				}
453				return adjustTopBlock(topDom);
454			}
455			throw new JadxRuntimeException("Failed to find top block for try-catch from: " + blocks);
456		}
457	
458		private static BlockNode adjustTopBlock(BlockNode topBlock) {
459			if (topBlock.getSuccessors().size() == 1 && !topBlock.contains(AType.EXC_CATCH)) {
460				// top block can be lifted by other exception handlers included in blocks list, trying to undo that
461				return topBlock.getSuccessors().get(0);
462			}
463			return topBlock;
464		}
465	
466		@Nullable
467		private static BlockNode searchBottomBlock(MethodNode mth, List<BlockNode> blocks) {
468			// search common post-dominator block inside input set
469			BlockNode bottom = BlockUtils.getBottomBlock(blocks);
470			if (bottom != null) {
471				return bottom;
472			}
473			// not found -> blocks don't have same dominator
474			// try to search common cross block outside input set
475			// NOTE: bottom block not needed for exit nodes (no data flow from them)
476			BlockNode pathCross = BlockUtils.getPathCross(mth, blocks);
477			if (pathCross == null) {
478				return null;
479			}
480			List<BlockNode> preds = new ArrayList<>(pathCross.getPredecessors());
481			preds.removeAll(blocks);
482			List<BlockNode> outsidePredecessors = ListUtils.filter(preds, p -> !BlockUtils.atLeastOnePathExists(blocks, p));
483			// if we have no predecessors or every predecessor is outside (which would mean that inserting the
484			// new synthetic block does nothing), just return the existing path cross instead.
485			if (outsidePredecessors.isEmpty() || outsidePredecessors.size() == pathCross.getPredecessors().size()) {
486				return pathCross;
487			}
488			// some predecessors outside of input set paths -> split block only for input set
489			BlockNode splitCross = BlockSplitter.blockSplitTop(mth, pathCross);
490			splitCross.add(AFlag.SYNTHETIC);
491			splitCross.addAttr(new ExcSplitCrossAttr(pathCross));
492			for (BlockNode outsidePredecessor : outsidePredecessors) {
493				// return predecessors to split bottom block (original)
494				BlockSplitter.replaceConnection(outsidePredecessor, splitCross, pathCross);
495			}
496			return splitCross;
497		}
498	
499		private static void connectSplittersAndHandlers(TryCatchBlockAttr tryCatchBlock, BlockNode topSplitterBlock,
500				@Nullable BlockNode bottomSplitterBlock) {
501			for (ExceptionHandler handler : tryCatchBlock.getHandlers()) {
502				BlockNode handlerBlock = handler.getHandlerBlock();
503				BlockSplitter.connect(topSplitterBlock, handlerBlock);
504				if (bottomSplitterBlock != null) {
505					BlockSplitter.connect(bottomSplitterBlock, handlerBlock);
506				}
507			}
508			TryCatchBlockAttr outerTryBlock = tryCatchBlock.getOuterTryBlock();
509			if (outerTryBlock != null) {
510				connectSplittersAndHandlers(outerTryBlock, topSplitterBlock, bottomSplitterBlock);
511			}
512		}
