514		private static void fixMoveExceptionInsn(BlockNode block, ExcHandlerAttr excHandlerAttr) {
515			ExceptionHandler excHandler = excHandlerAttr.getHandler();
516			ArgType argType = excHandler.getArgType();
517			InsnNode me = BlockUtils.getLastInsn(block);
518			if (me != null && me.getType() == InsnType.MOVE_EXCEPTION) {
519				// set correct type for 'move-exception' operation
520				RegisterArg resArg = InsnArg.reg(me.getResult().getRegNum(), argType);
521				resArg.copyAttributesFrom(me);
522				me.setResult(resArg);
523				me.add(AFlag.DONT_INLINE);
524				resArg.add(AFlag.CUSTOM_DECLARE);
525				excHandler.setArg(resArg);
526				me.addAttr(excHandlerAttr);
527				return;
528			}
529			// handler arguments not used
530			excHandler.setArg(new NamedArg("unused", argType));
531		}
532	
533		private static void removeMonitorExitFromExcHandler(MethodNode mth, ExceptionHandler excHandler) {
534			for (BlockNode excBlock : excHandler.getBlocks()) {
535				InsnRemover remover = new InsnRemover(mth, excBlock);
536				for (InsnNode insn : excBlock.getInstructions()) {
537					if (insn.getType() == InsnType.MONITOR_ENTER) {
538						break;
539					}
540					if (insn.getType() == InsnType.MONITOR_EXIT) {
541						remover.addAndUnbind(insn);
542					}
543				}
544				remover.perform();
545			}
546		}
