548		private static void checkForMultiCatch(MethodNode mth, List<TryCatchBlockAttr> tryBlocks) {
549			boolean merged = false;
550			for (TryCatchBlockAttr tryBlock : tryBlocks) {
551				if (mergeMultiCatch(mth, tryBlock)) {
552					merged = true;
553				}
554			}
555			if (merged) {
556				BlockSplitter.detachMarkedBlocks(mth);
557				mth.clearExceptionHandlers();
558			}
559		}
560	
561		private static boolean mergeMultiCatch(MethodNode mth, TryCatchBlockAttr tryCatch) {
562			if (tryCatch.getHandlers().size() < 2) {
563				return false;
564			}
565			for (ExceptionHandler handler : tryCatch.getHandlers()) {
566				if (handler.getBlocks().size() != 1) {
567					return false;
568				}
569				BlockNode block = handler.getHandlerBlock();
570				if (block.getInstructions().size() != 1
571						|| !BlockUtils.checkLastInsnType(block, InsnType.MOVE_EXCEPTION)) {
572					return false;
573				}
574			}
575			List<BlockNode> handlerBlocks = ListUtils.map(tryCatch.getHandlers(), ExceptionHandler::getHandlerBlock);
576			Set<BlockNode> successorSet = new LinkedHashSet<>();
577			for (BlockNode h : handlerBlocks) {
578				successorSet.addAll(h.getSuccessors());
579			}
580			List<BlockNode> successorBlocks = new ArrayList<>(successorSet);
581			if (successorBlocks.size() != 1) {
582				return false;
583			}
584			BlockNode successorBlock = successorBlocks.get(0);
585			if (!ListUtils.unorderedEquals(successorBlock.getPredecessors(), handlerBlocks)) {
586				return false;
587			}
588			Set<RegisterArg> regsSet = new LinkedHashSet<>();
589			for (ExceptionHandler h : tryCatch.getHandlers()) {
590				regsSet.add(Objects.requireNonNull(BlockUtils.getLastInsn(h.getHandlerBlock())).getResult());
591			}
592			List<RegisterArg> regs = new ArrayList<>(regsSet);
593			if (regs.size() != 1) {
594				return false;
595			}
596	
597			// merge confirm, leave only first handler, remove others
598			ExceptionHandler resultHandler = tryCatch.getHandlers().get(0);
599			tryCatch.getHandlers().removeIf(handler -> {
600				if (handler == resultHandler) {
601					return false;
602				}
603				resultHandler.addCatchTypes(mth, handler.getCatchTypes());
604				handler.markForRemove();
605				return true;
606			});
607			return true;
608		}
609	
610		private static void sortHandlers(MethodNode mth, List<TryCatchBlockAttr> tryBlocks) {
611			TypeCompare typeCompare = mth.root().getTypeCompare();
612			Comparator<ArgType> comparator = typeCompare.getReversedComparator();
613			for (TryCatchBlockAttr tryBlock : tryBlocks) {
614				for (ExceptionHandler handler : tryBlock.getHandlers()) {
615					handler.getCatchTypes().sort((first, second) -> compareByTypeAndName(comparator, first, second));
616				}
617				tryBlock.getHandlers().sort((first, second) -> {
618					if (first.equals(second)) {
619						throw new JadxRuntimeException("Same handlers in try block: " + tryBlock);
620					}
621					if (first.isCatchAll()) {
622						return 1;
623					}
624					if (second.isCatchAll()) {
625						return -1;
626					}
627					return compareByTypeAndName(comparator,
628							ListUtils.first(first.getCatchTypes()), ListUtils.first(second.getCatchTypes()));
629				});
630			}
631		}
632	
633		@SuppressWarnings("ComparatorResultComparison")
634		private static int compareByTypeAndName(Comparator<ArgType> comparator, ClassInfo first, ClassInfo second) {
635			int r = comparator.compare(first.getType(), second.getType());
636			if (r == -2) {
637				// on conflict sort by name
638				return first.compareTo(second);
639			}
640			return r;
641		}
