643		/**
644		 * Remove excHandlers that were not used when connecting.
645		 * Check first if the blocks are unreachable.
646		 */
647		private static void removeUnusedExcHandlers(MethodNode mth, List<TryCatchBlockAttr> tryBlocks, BlockSet blocks) {
648			for (ExceptionHandler eh : mth.getExceptionHandlers()) {
649				boolean notProcessed = true;
650				BlockNode handlerBlock = eh.getHandlerBlock();
651				if (handlerBlock == null || blocks.contains(handlerBlock)) {
652					continue;
653				}
654				for (TryCatchBlockAttr tcb : tryBlocks) {
655					if (tcb.getHandlers().contains(eh)) {
656						notProcessed = false;
657						break;
658					}
659				}
660				if (notProcessed) {
661					BlockProcessor.removeUnreachableBlock(handlerBlock, mth);
662				}
663			}
664		}
665	}
