1	package jadx.core.dex.visitors.blocks;
2	
3	import java.util.ArrayList;
4	import java.util.BitSet;
5	import java.util.List;
6	import java.util.function.Function;
7	
8	import jadx.core.dex.nodes.BlockNode;
9	import jadx.core.dex.nodes.MethodNode;
10	import jadx.core.utils.BlockUtils;
11	import jadx.core.utils.EmptyBitSet;
12	import jadx.core.utils.exceptions.JadxRuntimeException;
13	
14	/**
15	 * Build dominator tree based on the algorithm described in paper:
16	 * Cooper, Keith D.; Harvey, Timothy J; Kennedy, Ken (2001).
17	 * "A Simple, Fast Dominance Algorithm"
18	 * http://www.hipersoft.rice.edu/grads/publications/dom14.pdf
19	 */
20	@SuppressWarnings("JavadocLinkAsPlainText")
21	public class DominatorTree {
22	
23		public static void compute(MethodNode mth) {
24			List<BlockNode> sorted = sortBlocks(mth);
25			BlockNode[] doms = build(sorted, BlockNode::getPredecessors);
26			apply(sorted, doms);
27		}
28	
29		private static List<BlockNode> sortBlocks(MethodNode mth) {
30			int blocksCount = mth.getBasicBlocks().size();
31			List<BlockNode> sorted = new ArrayList<>(blocksCount);
32			BlockUtils.visitDFS(mth, sorted::add);
33			if (sorted.size() != blocksCount) {
34				throw new JadxRuntimeException("Found unreachable blocks");
35			}
36			mth.setBasicBlocks(sorted);
37			return sorted;
38		}
39	
40		static BlockNode[] build(List<BlockNode> sorted, Function<BlockNode, List<BlockNode>> predFunc) {
41			int blocksCount = sorted.size();
42			BlockNode[] doms = new BlockNode[blocksCount];
43			doms[0] = sorted.get(0);
44			boolean changed = true;
45			while (changed) {
46				changed = false;
47				for (int blockId = 1; blockId < blocksCount; blockId++) {
48					BlockNode b = sorted.get(blockId);
49					List<BlockNode> preds = predFunc.apply(b);
50					int pickedPred = -1;
51					BlockNode newIDom = null;
52					for (BlockNode pred : preds) {
53						int id = pred.getId();
54						if (doms[id] != null) {
55							newIDom = pred;
56							pickedPred = id;
57							break;
58						}
59					}
60					if (newIDom == null) {
61						throw new JadxRuntimeException("No immediate dominator for block: " + b);
62					}
63					for (BlockNode predBlock : preds) {
64						int predId = predBlock.getId();
65						if (predId == pickedPred) {
66							continue;
67						}
68						if (doms[predId] != null) {
69							newIDom = intersect(sorted, doms, predBlock, newIDom);
70						}
71					}
72					if (doms[blockId] != newIDom) {
73						doms[blockId] = newIDom;
74						changed = true;
75					}
76				}
77			}
78			return doms;
79		}
80	
81		private static BlockNode intersect(List<BlockNode> sorted, BlockNode[] doms, BlockNode b1, BlockNode b2) {
82			int f1 = b1.getId();
83			int f2 = b2.getId();
84			while (f1 != f2) {
85				while (f1 > f2) {
86					f1 = doms[f1].getId();
87				}
88				while (f2 > f1) {
89					f2 = doms[f2].getId();
90				}
91			}
92			return sorted.get(f1);
93		}
94	
95		private static void apply(List<BlockNode> sorted, BlockNode[] doms) {
96			BlockNode enterBlock = sorted.get(0);
97			enterBlock.setDoms(EmptyBitSet.EMPTY);
98			enterBlock.setIDom(null);
99			int blocksCount = sorted.size();
100			for (int i = 1; i < blocksCount; i++) {
101				BlockNode block = sorted.get(i);
102				BlockNode idom = doms[i];
103				block.setIDom(idom);
104				idom.addDominatesOn(block);
105				BitSet domBS = collectDoms(doms, idom);
106				domBS.clear(i);
107				block.setDoms(domBS);
108			}
109		}
110	
111		static BitSet collectDoms(BlockNode[] doms, BlockNode idom) {
112			BitSet domBS = new BitSet(doms.length);
113			BlockNode nextIDom = idom;
114			while (true) {
115				int id = nextIDom.getId();
116				if (domBS.get(id)) {
117					break;
118				}
119				domBS.set(id);
120				BitSet curDoms = nextIDom.getDoms();
121				if (curDoms != null) {
122					// use already collected set
123					domBS.or(curDoms);
124					break;
125				}
126				nextIDom = doms[id];
127			}
128			return domBS;
129		}
130	
131		public static void computeDominanceFrontier(MethodNode mth) {
132			List<BlockNode> blocks = mth.getBasicBlocks();
133			for (BlockNode block : blocks) {
134				block.setDomFrontier(null);
135			}
136			int blocksCount = blocks.size();
137			for (BlockNode block : blocks) {
138				List<BlockNode> preds = block.getPredecessors();
139				if (preds.size() >= 2) {
140					BlockNode idom = block.getIDom();
141					for (BlockNode pred : preds) {
142						BlockNode runner = pred;
143						while (runner != idom) {
144							addToDF(runner, block, blocksCount);
145							runner = runner.getIDom();
146						}
147					}
148				}
149			}
150			for (BlockNode block : blocks) {
151				BitSet df = block.getDomFrontier();
152				if (df == null || df.isEmpty()) {
153					block.setDomFrontier(EmptyBitSet.EMPTY);
154				}
155			}
156		}
157	
158		private static void addToDF(BlockNode block, BlockNode dfBlock, int blocksCount) {
159			BitSet df = block.getDomFrontier();
160			if (df == null) {
161				df = new BitSet(blocksCount);
162				block.setDomFrontier(df);
163			}
164			df.set(dfBlock.getId());
165		}
166	}
