1	package jadx.core.dex.visitors.blocks;
2	
3	import java.util.Arrays;
4	import java.util.List;
5	
6	import jadx.core.dex.attributes.AType;
7	import jadx.core.dex.attributes.nodes.SpecialEdgeAttr;
8	import jadx.core.dex.attributes.nodes.SpecialEdgeAttr.SpecialEdgeType;
9	import jadx.core.dex.nodes.BlockNode;
10	import jadx.core.dex.nodes.MethodNode;
11	import jadx.core.utils.ListUtils;
12	
13	public class FixMultiEntryLoops {
14	
15		public static boolean process(MethodNode mth) {
16			try {
17				detectSpecialEdges(mth);
18			} catch (Exception e) {
19				mth.addWarnComment("Failed to detect multi-entry loops", e);
20				return false;
21			}
22			List<SpecialEdgeAttr> specialEdges = mth.getAll(AType.SPECIAL_EDGE);
23			List<SpecialEdgeAttr> multiEntryLoops = ListUtils.filter(specialEdges,
24					e -> e.getType() == SpecialEdgeType.BACK_EDGE && !isSingleEntryLoop(e));
25			if (multiEntryLoops.isEmpty()) {
26				return false;
27			}
28			try {
29				List<SpecialEdgeAttr> crossEdges = ListUtils.filter(specialEdges, e -> e.getType() == SpecialEdgeType.CROSS_EDGE);
30				boolean changed = false;
31				for (SpecialEdgeAttr backEdge : multiEntryLoops) {
32					changed |= fixLoop(mth, backEdge, crossEdges);
33				}
34				return changed;
35			} catch (Exception e) {
36				mth.addWarnComment("Failed to fix multi-entry loops", e);
37				return false;
38			}
39		}
40	
41		private static boolean fixLoop(MethodNode mth, SpecialEdgeAttr backEdge, List<SpecialEdgeAttr> crossEdges) {
42			if (isHeaderSuccessorEntry(mth, backEdge, crossEdges)) {
43				return true;
44			}
45			if (isEndBlockEntry(mth, backEdge, crossEdges)) {
46				return true;
47			}
48			mth.addWarnComment("Unsupported multi-entry loop pattern (" + backEdge + "). Please report as a decompilation issue!!!");
49			return false;
50		}
51	
52		private static boolean isHeaderSuccessorEntry(MethodNode mth, SpecialEdgeAttr backEdge, List<SpecialEdgeAttr> crossEdges) {
53			BlockNode header = backEdge.getEnd();
54			BlockNode headerIDom = header.getIDom();
55			SpecialEdgeAttr subEntry = ListUtils.filterOnlyOne(crossEdges, e -> e.getStart() == headerIDom);
56			if (subEntry == null || !ListUtils.isSingleElement(header.getSuccessors(), subEntry.getEnd())) {
57				return false;
58			}
59			BlockNode loopEnd = backEdge.getStart();
60			BlockNode subEntryBlock = subEntry.getEnd();
61			BlockNode copyHeader = BlockSplitter.insertBlockBetween(mth, loopEnd, header);
62			BlockSplitter.copyBlockData(header, copyHeader);
63			BlockSplitter.replaceConnection(copyHeader, header, subEntryBlock);
64			mth.addDebugComment("Duplicate block (" + header + ") to fix multi-entry loop: " + backEdge);
65			return true;
66		}
67	
68		private static boolean isEndBlockEntry(MethodNode mth, SpecialEdgeAttr backEdge, List<SpecialEdgeAttr> crossEdges) {
69			BlockNode loopEnd = backEdge.getStart();
70			SpecialEdgeAttr subEntry = ListUtils.filterOnlyOne(crossEdges, e -> e.getEnd() == loopEnd);
71			if (subEntry == null) {
72				return false;
73			}
74			dupPath(mth, subEntry.getStart(), loopEnd, backEdge.getEnd());
75			mth.addDebugComment("Duplicate block (" + loopEnd + ") to fix multi-entry loop: " + backEdge);
76			return true;
77		}
78	
79		/**
80		 * Duplicate 'center' block on path from 'start' to 'end'
81		 */
82		private static void dupPath(MethodNode mth, BlockNode start, BlockNode center, BlockNode end) {
83			BlockNode copyCenter = BlockSplitter.insertBlockBetween(mth, start, end);
84			BlockSplitter.copyBlockData(center, copyCenter);
85			BlockSplitter.removeConnection(start, center);
86		}
87	
88		private static boolean isSingleEntryLoop(SpecialEdgeAttr e) {
89			BlockNode header = e.getEnd();
90			BlockNode loopEnd = e.getStart();
91			return header == loopEnd
92					|| loopEnd.getDoms().get(header.getId()); // header dominates loop end
93		}
94	
95		private enum BlockColor {
96			WHITE, GRAY, BLACK
97		}
98	
99		private static void detectSpecialEdges(MethodNode mth) {
100			BlockColor[] colors = new BlockColor[mth.getBasicBlocks().size()];
101			Arrays.fill(colors, BlockColor.WHITE);
102			colorDFS(mth, colors, mth.getEnterBlock());
103		}
104	
105		// TODO: transform to non-recursive form
106		private static void colorDFS(MethodNode mth, BlockColor[] colors, BlockNode block) {
107			colors[block.getId()] = BlockColor.GRAY;
108			for (BlockNode v : block.getSuccessors()) {
109				switch (colors[v.getId()]) {
110					case WHITE:
111						colorDFS(mth, colors, v);
112						break;
113					case GRAY:
114						mth.addAttr(AType.SPECIAL_EDGE, new SpecialEdgeAttr(SpecialEdgeType.BACK_EDGE, block, v));
115						break;
116					case BLACK:
117						mth.addAttr(AType.SPECIAL_EDGE, new SpecialEdgeAttr(SpecialEdgeType.CROSS_EDGE, block, v));
118						break;
119				}
120			}
121			colors[block.getId()] = BlockColor.BLACK;
122		}
123	}
