1	package jadx.core.dex.visitors.blocks;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jadx.core.dex.instructions.InsnType;
7	import jadx.core.dex.instructions.args.InsnArg;
8	import jadx.core.dex.instructions.args.RegisterArg;
9	import jadx.core.dex.nodes.BlockNode;
10	import jadx.core.dex.nodes.InsnNode;
11	import jadx.core.dex.nodes.MethodNode;
12	import jadx.core.utils.BlockUtils;
13	import jadx.core.utils.ListUtils;
14	import jadx.core.utils.exceptions.JadxRuntimeException;
15	
16	/**
17	 * Duplicate code to resolve java jsr/ret.
18	 * JSR (jump subroutine) allows executing the same code from different places.
19	 * Used mostly for 'finally' blocks, deprecated in Java 7.
20	 */
21	public class ResolveJavaJSR {
22	
23		public static void process(MethodNode mth) {
24			int blocksCount = mth.getBasicBlocks().size();
25			int k = 0;
26			while (true) {
27				boolean changed = resolve(mth);
28				if (!changed) {
29					break;
30				}
31				if (k++ > blocksCount) {
32					throw new JadxRuntimeException("Fail to resolve jsr instructions");
33				}
34			}
35		}
36	
37		private static boolean resolve(MethodNode mth) {
38			List<BlockNode> blocks = mth.getBasicBlocks();
39			int blocksCount = blocks.size();
40			for (BlockNode block : blocks) {
41				if (BlockUtils.checkLastInsnType(block, InsnType.JAVA_RET)) {
42					resolveForRetBlock(mth, block);
43					if (blocksCount != mth.getBasicBlocks().size()) {
44						return true;
45					}
46				}
47			}
48			return false;
49		}
50	
51		private static void resolveForRetBlock(MethodNode mth, BlockNode retBlock) {
52			BlockUtils.visitPredecessorsUntil(mth, retBlock, startBlock -> {
53				List<BlockNode> preds = startBlock.getPredecessors();
54				if (preds.size() > 1
55						&& ListUtils.allMatch(preds, p -> BlockUtils.checkLastInsnType(p, InsnType.JAVA_JSR))) {
56					List<BlockNode> jsrBlocks = new ArrayList<>(preds);
57					List<BlockNode> dupBlocks = BlockUtils.collectAllSuccessors(mth, startBlock, false);
58					removeInsns(retBlock, startBlock, jsrBlocks);
59					processBlocks(mth, retBlock, startBlock, jsrBlocks, dupBlocks);
60					return true;
61				}
62				return false;
63			});
64		}
65	
66		private static void removeInsns(BlockNode retBlock, BlockNode startBlock, List<BlockNode> jsrBlocks) {
67			InsnNode retInsn = ListUtils.removeLast(retBlock.getInstructions());
68			if (retInsn != null && retInsn.getType() == InsnType.JAVA_RET) {
69				InsnArg retArg = retInsn.getArg(0);
70				if (retArg.isRegister()) {
71					int regNum = ((RegisterArg) retArg).getRegNum();
72					InsnNode startInsn = BlockUtils.getFirstInsn(startBlock);
73					if (startInsn != null
74							&& startInsn.getType() == InsnType.MOVE
75							&& startInsn.getResult().getRegNum() == regNum) {
76						startBlock.getInstructions().remove(0);
77					}
78				}
79			}
80			jsrBlocks.forEach(p -> ListUtils.removeLast(p.getInstructions()));
81		}
82	
83		private static void processBlocks(MethodNode mth, BlockNode retBlock, BlockNode startBlock,
84				List<BlockNode> jsrBlocks, List<BlockNode> dupBlocks) {
85			BlockNode first = null;
86			for (BlockNode jsrBlock : jsrBlocks) {
87				if (first == null) {
88					first = jsrBlock;
89				} else {
90					BlockNode pathBlock = BlockUtils.selectOther(startBlock, jsrBlock.getSuccessors());
91					BlockSplitter.removeConnection(jsrBlock, startBlock);
92					BlockSplitter.removeConnection(jsrBlock, pathBlock);
93					List<BlockNode> newBlocks = BlockSplitter.copyBlocksTree(mth, dupBlocks);
94					BlockNode newStart = newBlocks.get(dupBlocks.indexOf(startBlock));
95					BlockNode newRetBlock = newBlocks.get(dupBlocks.indexOf(retBlock));
96					BlockSplitter.connect(jsrBlock, newStart);
97					BlockSplitter.connect(newRetBlock, pathBlock);
98				}
99			}
100			if (first != null) {
101				BlockNode pathBlock = BlockUtils.selectOther(startBlock, first.getSuccessors());
102				BlockSplitter.removeConnection(first, pathBlock);
103				BlockSplitter.connect(retBlock, pathBlock);
104			}
105		}
106	}
