1	package jadx.core.dex.visitors;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.Set;
6	
7	import org.jetbrains.annotations.Nullable;
8	
9	import jadx.core.Consts;
10	import jadx.core.deobf.NameMapper;
11	import jadx.core.dex.attributes.AFlag;
12	import jadx.core.dex.info.ClassInfo;
13	import jadx.core.dex.info.MethodInfo;
14	import jadx.core.dex.instructions.InvokeNode;
15	import jadx.core.dex.instructions.args.ArgType;
16	import jadx.core.dex.instructions.args.CodeVar;
17	import jadx.core.dex.instructions.args.InsnArg;
18	import jadx.core.dex.instructions.args.InsnWrapArg;
19	import jadx.core.dex.instructions.args.RegisterArg;
20	import jadx.core.dex.instructions.args.SSAVar;
21	import jadx.core.dex.instructions.mods.ConstructorInsn;
22	import jadx.core.dex.nodes.InsnNode;
23	import jadx.core.dex.nodes.MethodNode;
24	import jadx.core.dex.nodes.RootNode;
25	import jadx.core.dex.visitors.regions.variables.ProcessVariables;
26	import jadx.core.utils.ListUtils;
27	import jadx.core.utils.StringUtils;
28	import jadx.core.utils.Utils;
29	import jadx.core.utils.exceptions.JadxException;
30	
31	@JadxVisitor(
32			name = "ApplyVariableNames",
33			desc = "Try to guess variable name from usage",
34			runAfter = {
35					ProcessVariables.class
36			}
37	)
38	public class ApplyVariableNames extends AbstractVisitor {
39	
40		private static final Map<String, String> OBJ_ALIAS = Utils.newConstStringMap(
41				Consts.CLASS_STRING, "str",
42				Consts.CLASS_CLASS, "cls",
43				Consts.CLASS_THROWABLE, "th",
44				Consts.CLASS_OBJECT, "obj",
45				"java.util.Iterator", "it",
46				"java.util.HashMap", "map",
47				"java.lang.Boolean", "bool",
48				"java.lang.Short", "sh",
49				"java.lang.Integer", "num",
50				"java.lang.Character", "ch",
51				"java.lang.Byte", "b",
52				"java.lang.Float", "f",
53				"java.lang.Long", "l",
54				"java.lang.Double", "d",
55				"java.lang.StringBuilder", "sb",
56				"java.lang.Exception", "exc");
57	
58		private static final Set<String> GOOD_VAR_NAMES = Set.of(
59				"size", "length", "list", "map", "next");
60		private static final List<String> INVOKE_PREFIXES = List.of(
61				"get", "set", "to", "parse", "read", "format");
62	
63		private RootNode root;
64	
65		@Override
66		public void init(RootNode root) throws JadxException {
67			this.root = root;
68		}
69	
70		@Override
71		public void visit(MethodNode mth) throws JadxException {
72			for (SSAVar ssaVar : mth.getSVars()) {
73				CodeVar codeVar = ssaVar.getCodeVar();
74				String newName = guessName(codeVar);
75				if (newName != null) {
76					codeVar.setName(newName);
77				}
78			}
79		}
80	
81		private @Nullable String guessName(CodeVar var) {
82			if (var.isThis()) {
83				return RegisterArg.THIS_ARG_NAME;
84			}
85			if (!var.isDeclared()) {
86				// name is not used in code
87				return null;
88			}
89			if (NameMapper.isValidAndPrintable(var.getName())) {
90				// the current name is valid, keep it
91				return null;
92			}
93			List<SSAVar> ssaVars = var.getSsaVars();
94			if (Utils.notEmpty(ssaVars)) {
95				boolean mthArg = ListUtils.anyMatch(ssaVars, ssaVar -> ssaVar.getAssign().contains(AFlag.METHOD_ARGUMENT));
96				if (mthArg) {
97					// for method args use defined type and ignore usage
98					return makeNameForType(var.getType());
99				}
100				for (SSAVar ssaVar : ssaVars) {
101					String name = makeNameForSSAVar(ssaVar);
102					if (name != null) {
103						return name;
104					}
105				}
106			}
107			return makeNameForType(var.getType());
108		}
109	
110		private @Nullable String makeNameForSSAVar(SSAVar ssaVar) {
111			String ssaVarName = ssaVar.getName();
112			if (ssaVarName != null) {
113				return ssaVarName;
114			}
115			InsnNode assignInsn = ssaVar.getAssignInsn();
116			if (assignInsn != null) {
117				String name = makeNameFromInsn(ssaVar, assignInsn);
118				if (NameMapper.isValidAndPrintable(name)) {
119					return name;
120				}
121			}
122			return null;
123		}
124	
125		private String makeNameFromInsn(SSAVar ssaVar, InsnNode insn) {
126			switch (insn.getType()) {
127				case INVOKE:
128					return makeNameFromInvoke(ssaVar, (InvokeNode) insn);
129	
130				case CONSTRUCTOR:
131					ConstructorInsn co = (ConstructorInsn) insn;
132					MethodNode callMth = root.getMethodUtils().resolveMethod(co);
133					if (callMth != null && callMth.contains(AFlag.ANONYMOUS_CONSTRUCTOR)) {
134						// don't use name of anonymous class
135						return null;
136					}
137					return makeNameForClass(co.getClassType());
138	
139				case ARRAY_LENGTH:
140					return "length";
141	
142				case ARITH:
143				case TERNARY:
144				case CAST:
145					for (InsnArg arg : insn.getArguments()) {
146						if (arg.isInsnWrap()) {
147							InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
148							String wName = makeNameFromInsn(ssaVar, wrapInsn);
149							if (wName != null) {
150								return wName;
151							}
152						}
153					}
154					break;
155	
156				default:
157					break;
158			}
159			return null;
160		}
161	
162		private String makeNameForType(ArgType type) {
163			if (type.isPrimitive()) {
164				return type.getPrimitiveType().getShortName().toLowerCase();
165			}
166			if (type.isArray()) {
167				return makeNameForType(type.getArrayRootElement()) + "Arr";
168			}
169			return makeNameForObject(type);
170		}
171	
172		private String makeNameForObject(ArgType type) {
173			if (type.isGenericType()) {
174				return StringUtils.escape(type.getObject().toLowerCase());
175			}
176			if (type.isObject()) {
177				String alias = getAliasForObject(type.getObject());
178				if (alias != null) {
179					return alias;
180				}
181				return makeNameForCheckedClass(ClassInfo.fromType(root, type));
182			}
183			return StringUtils.escape(type.toString());
184		}
185	
186		private String makeNameForCheckedClass(ClassInfo classInfo) {
187			String shortName = classInfo.getAliasShortName();
188			String vName = fromName(shortName);
189			if (vName != null) {
190				return vName;
191			}
192			String lower = StringUtils.escape(shortName.toLowerCase());
193			if (shortName.equals(lower)) {
194				return lower + "Var";
195			}
196			return lower;
197		}
198	
199		private String makeNameForClass(ClassInfo classInfo) {
200			String alias = getAliasForObject(classInfo.getFullName());
201			if (alias != null) {
202				return alias;
203			}
204			return makeNameForCheckedClass(classInfo);
205		}
206	
207		private static String fromName(String name) {
208			if (name == null || name.isEmpty()) {
209				return null;
210			}
211			if (name.chars().allMatch(c -> Character.toUpperCase(c) == c)) {
212				// all characters are upper case
213				return name.toLowerCase();
214			}
215			String v1 = Character.toLowerCase(name.charAt(0)) + name.substring(1);
216			if (!v1.equals(name)) {
217				return v1;
218			}
219			if (name.length() < 3) {
220				return name + "Var";
221			}
222			return null;
223		}
224	
225		private static String getAliasForObject(String name) {
226			return OBJ_ALIAS.get(name);
227		}
228	
229		private String makeNameFromInvoke(SSAVar ssaVar, InvokeNode inv) {
230			MethodInfo callMth = inv.getCallMth();
231			String name = callMth.getAlias();
232			ClassInfo declClass = callMth.getDeclClass();
233			if ("getInstance".equals(name)) {
234				// e.g. Cipher.getInstance
235				return makeNameForClass(declClass);
236			}
237			String shortName = cutPrefix(name);
238			if (shortName != null) {
239				return fromName(shortName);
240			}
241			if ("iterator".equals(name)) {
242				return "it";
243			}
244			if ("toString".equals(name)) {
245				return makeNameForClass(declClass);
246			}
247			if ("forName".equals(name) && declClass.getType().equals(ArgType.CLASS)) {
248				return OBJ_ALIAS.get(Consts.CLASS_CLASS);
249			}
250			// use method name as a variable name not the best idea in most cases
251			if (!GOOD_VAR_NAMES.contains(name)) {
252				String typeName = makeNameForType(ssaVar.getCodeVar().getType());
253				if (!typeName.equalsIgnoreCase(name)) {
254					return typeName + StringUtils.capitalizeFirstChar(name);
255				}
256			}
257			return name;
258		}
259	
260		private @Nullable String cutPrefix(String name) {
261			for (String prefix : INVOKE_PREFIXES) {
262				if (name.startsWith(prefix)) {
263					return name.substring(prefix.length());
264				}
265			}
266			return null;
267		}
268	
269		@Override
270		public String getName() {
271			return "ApplyVariableNames";
272		}
273	}
