23	import jadx.core.dex.instructions.ArithNode;
24	import jadx.core.dex.instructions.ArithOp;
25	import jadx.core.dex.instructions.IndexInsnNode;
26	import jadx.core.dex.instructions.InsnType;
27	import jadx.core.dex.instructions.InvokeNode;
28	import jadx.core.dex.instructions.args.ArgType;
29	import jadx.core.dex.instructions.args.InsnArg;
30	import jadx.core.dex.instructions.args.InsnWrapArg;
31	import jadx.core.dex.instructions.args.RegisterArg;
32	import jadx.core.dex.instructions.mods.ConstructorInsn;
33	import jadx.core.dex.instructions.mods.TernaryInsn;
34	import jadx.core.dex.nodes.BlockNode;
35	import jadx.core.dex.nodes.ClassNode;
36	import jadx.core.dex.nodes.FieldNode;
37	import jadx.core.dex.nodes.InsnContainer;
38	import jadx.core.dex.nodes.InsnNode;
39	import jadx.core.dex.nodes.MethodNode;
40	import jadx.core.dex.regions.conditions.IfCondition;
41	import jadx.core.dex.regions.conditions.IfCondition.Mode;
42	import jadx.core.dex.visitors.regions.variables.ProcessVariables;
43	import jadx.core.dex.visitors.shrink.CodeShrinkVisitor;
44	import jadx.core.utils.BlockUtils;
45	import jadx.core.utils.InsnList;
46	import jadx.core.utils.exceptions.JadxException;
47	
48	/**
49	 * Prepare instructions for code generation pass,
50	 * most of this modification breaks register dependencies,
51	 * so this pass must be just before CodeGen.
52	 */
53	@JadxVisitor(
54			name = "PrepareForCodeGen",
55			desc = "Prepare instructions for code generation pass",
56			runAfter = { CodeShrinkVisitor.class, ClassModifier.class, ProcessVariables.class }
57	)
58	public class PrepareForCodeGen extends AbstractVisitor {
59	
60		@Override
61		public String getName() {
62			return "PrepareForCodeGen";
63		}
64	
65		@Override
66		public boolean visit(ClassNode cls) throws JadxException {
67			if (cls.root().getArgs().isDebugInfo()) {
68				setClassSourceLine(cls);
69			}
70			collectFieldsUsageInAnnotations(cls);
71			return true;
72		}
73	
74		@Override
75		public void visit(MethodNode mth) throws JadxException {
76			if (mth.isNoCode()) {
77				return;
78			}
79			for (BlockNode block : mth.getBasicBlocks()) {
80				if (block.contains(AFlag.DONT_GENERATE)) {
81					continue;
82				}
83				removeInstructions(block);
84				checkInline(block);
85				removeParenthesis(block);
86				modifyArith(block);
87				checkConstUsage(block);
88				addNullCasts(mth, block);
89			}
90			moveConstructorInConstructor(mth);
91			collectFieldsUsageInAnnotations(mth, mth);
92		}
93	
94		private static void removeInstructions(BlockNode block) {
95			Iterator<InsnNode> it = block.getInstructions().iterator();
96			while (it.hasNext()) {
97				InsnNode insn = it.next();
98				switch (insn.getType()) {
99					case NOP:
100					case MONITOR_ENTER:
101					case MONITOR_EXIT:
102					case MOVE_EXCEPTION:
103						it.remove();
104						break;
105	
106					case CONSTRUCTOR:
107						ConstructorInsn co = (ConstructorInsn) insn;
108						if (co.isSelf()) {
109							it.remove();
110						}
111						break;
112	
113					case MOVE:
114						// remove redundant moves: unused result and same args names (a = a;)
115						RegisterArg result = insn.getResult();
116						if (result.getSVar().getUseCount() == 0
117								&& result.isNameEquals(insn.getArg(0))) {
118							it.remove();
119						}
120						break;
121	
122					default:
123						break;
124				}
125			}
126		}
127	
128		private static void checkInline(BlockNode block) {
129			List<InsnNode> list = block.getInstructions();
130			for (int i = 0; i < list.size(); i++) {
131				InsnNode insn = list.get(i);
132				// replace 'move' with inner wrapped instruction
133				if (insn.getType() == InsnType.MOVE
134						&& insn.getArg(0).isInsnWrap()) {
135					InsnNode wrapInsn = ((InsnWrapArg) insn.getArg(0)).getWrapInsn();
136					wrapInsn.setResult(insn.getResult());
137					wrapInsn.copyAttributesFrom(insn);
138					list.set(i, wrapInsn);
139				}
140			}
141		}
142	
143		/**
144		 * Add explicit type for non int constants
145		 */
146		private static void checkConstUsage(BlockNode block) {
147			for (InsnNode blockInsn : block.getInstructions()) {
148				blockInsn.visitInsns(insn -> {
149					if (forbidExplicitType(insn.getType())) {
150						return;
151					}
152					for (InsnArg arg : insn.getArguments()) {
153						if (arg.isLiteral() && arg.getType() != ArgType.INT) {
154							arg.add(AFlag.EXPLICIT_PRIMITIVE_TYPE);
155						}
156					}
157				});
158			}
159		}
160	
161		private static boolean forbidExplicitType(InsnType type) {
162			switch (type) {
163				case CONST:
164				case CAST:
165				case IF:
166				case FILLED_NEW_ARRAY:
167				case APUT:
168				case ARITH:
169					return true;
170				default:
171					return false;
172			}
173		}
174	
175		private static void removeParenthesis(BlockNode block) {
176			for (InsnNode insn : block.getInstructions()) {
177				removeParenthesis(insn);
178			}
179		}
180	
181		/**
182		 * Remove parenthesis for wrapped insn in arith '+' or '-'
183		 * ('(a + b) +c' => 'a + b + c')
184		 */
185		private static void removeParenthesis(InsnNode insn) {
186			if (insn.getType() == InsnType.ARITH) {
187				ArithNode arith = (ArithNode) insn;
188				ArithOp op = arith.getOp();
189				if (op == ArithOp.ADD || op == ArithOp.MUL || op == ArithOp.AND || op == ArithOp.OR) {
190					for (int i = 0; i < 2; i++) {
191						InsnArg arg = arith.getArg(i);
192						if (arg.isInsnWrap()) {
193							InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
194							if (wrapInsn.getType() == InsnType.ARITH && ((ArithNode) wrapInsn).getOp() == op) {
195								wrapInsn.add(AFlag.DONT_WRAP);
196							}
197							removeParenthesis(wrapInsn);
198						}
199					}
200				}
201			} else {
202				if (insn.getType() == InsnType.TERNARY) {
203					removeParenthesis(((TernaryInsn) insn).getCondition());
204				}
205				for (InsnArg arg : insn.getArguments()) {
206					if (arg.isInsnWrap()) {
207						InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
208						removeParenthesis(wrapInsn);
209					}
210				}
211			}
212		}
213	
214		private static void removeParenthesis(IfCondition cond) {
215			Mode mode = cond.getMode();
216			for (IfCondition c : cond.getArgs()) {
217				if (c.getMode() == mode) {
218					c.add(AFlag.DONT_WRAP);
219				}
220			}
221		}
222	
223		/**
224		 * Replace arithmetic operation with short form
225		 * ('a = a + 2' => 'a += 2')
226		 */
227		private static void modifyArith(BlockNode block) {
228			List<InsnNode> list = block.getInstructions();
229			for (InsnNode insn : list) {
230				if (insn.getType() == InsnType.ARITH
231						&& !insn.contains(AFlag.ARITH_ONEARG)
232						&& !insn.contains(AFlag.DECLARE_VAR)) {
233					RegisterArg res = insn.getResult();
234					InsnArg arg = insn.getArg(0);
235					boolean replace = false;
236					if (res.equals(arg)) {
237						replace = true;
238					} else if (arg.isRegister()) {
239						RegisterArg regArg = (RegisterArg) arg;
240						replace = res.sameCodeVar(regArg);
241					}
242					if (replace) {
243						insn.setResult(null);
244						insn.add(AFlag.ARITH_ONEARG);
245					}
246				}
247			}
248		}
249	
250		/**
251		 * Check that 'super' or 'this' call in constructor is a first instruction.
252		 * Otherwise, move to the top and add a warning.
253		 */
254		private void moveConstructorInConstructor(MethodNode mth) {
255			if (!mth.isConstructor()) {
256				return;
257			}
258			ConstructorInsn ctrInsn = searchConstructorCall(mth);
259			if (ctrInsn == null || ctrInsn.contains(AFlag.DONT_GENERATE)) {
260				return;
261			}
262			boolean firstInsn = BlockUtils.isFirstInsn(mth, ctrInsn);
263			DeclareVariablesAttr declVarsAttr = mth.getRegion().get(AType.DECLARE_VARIABLES);
264			if (firstInsn && declVarsAttr == null) {
265				// move not needed
266				return;
267			}
268			String callType = ctrInsn.getCallType().toString().toLowerCase();
269			BlockNode blockByInsn = BlockUtils.getBlockByInsn(mth, ctrInsn);
270			if (blockByInsn == null) {
271				mth.addWarn("Failed to move " + callType + " instruction to top");
272				return;
273			}
274	
275			if (!firstInsn) {
276				Set<RegisterArg> regArgs = new HashSet<>();
277				ctrInsn.getRegisterArgs(regArgs);
278				regArgs.remove(mth.getThisArg());
279				mth.getArgRegs().forEach(regArgs::remove);
280				if (!regArgs.isEmpty()) {
281					mth.addWarnComment("Illegal instructions before constructor call");
282					return;
283				}
284				mth.addWarnComment("'" + callType + "' call moved to the top of the method (can break code semantics)");
285			}
286	
287			// move confirmed
288			InsnList.remove(blockByInsn, ctrInsn);
289			mth.getRegion().getSubBlocks().add(0, new InsnContainer(ctrInsn));
290		}
291	
292		private @Nullable ConstructorInsn searchConstructorCall(MethodNode mth) {
293			for (BlockNode block : mth.getBasicBlocks()) {
294				for (InsnNode insn : block.getInstructions()) {
295					if (insn.getType() == InsnType.CONSTRUCTOR) {
296						ConstructorInsn ctrInsn = (ConstructorInsn) insn;
297						if (ctrInsn.isSuper() || ctrInsn.isThis()) {
298							return ctrInsn;
299						}
300						return null;
301					}
302				}
303			}
304			return null;
305		}
306	
307		/**
308		 * Use source line from top method
309		 */
310		private void setClassSourceLine(ClassNode cls) {
311			for (ClassNode innerClass : cls.getInnerClasses()) {
312				setClassSourceLine(innerClass);
313			}
314			int minLine = 0;
315			for (LineAttrNode node : cls.getMethods()) {
316				if (!node.contains(AFlag.DONT_GENERATE) && node.getSourceLine() != 0) {
317					int line = node.getSourceLine();
318					if (minLine == 0 || line < minLine) {
319						minLine = line;
320					}
321				}
322			}
323			for (LineAttrNode node : cls.getInnerClasses()) {
324				if (!node.contains(AFlag.DONT_GENERATE) && node.getSourceLine() != 0) {
325					int line = node.getSourceLine();
326					if (minLine == 0 || line < minLine) {
327						minLine = line;
328					}
329				}
330			}
331			for (LineAttrNode node : cls.getFields()) {
332				if (!node.contains(AFlag.DONT_GENERATE) && node.getSourceLine() != 0) {
333					int line = node.getSourceLine();
334					if (minLine == 0 || line < minLine) {
335						minLine = line;
336					}
337				}
338			}
339			if (minLine != 0) {
340				cls.setSourceLine(minLine - 1);
341			}
342		}
343	
344		private void collectFieldsUsageInAnnotations(ClassNode cls) {
345			MethodNode useMth = cls.getDefaultConstructor();
346			if (useMth == null && !cls.getMethods().isEmpty()) {
347				useMth = cls.getMethods().get(0);
348			}
349			if (useMth == null) {
350				return;
351			}
352			collectFieldsUsageInAnnotations(useMth, cls);
353			MethodNode finalUseMth = useMth;
354			cls.getFields().forEach(f -> collectFieldsUsageInAnnotations(finalUseMth, f));
355		}
356	
357		private void collectFieldsUsageInAnnotations(MethodNode mth, AttrNode attrNode) {
358			AnnotationsAttr annotationsList = attrNode.get(JadxAttrType.ANNOTATION_LIST);
359			if (annotationsList == null) {
360				return;
361			}
362			for (IAnnotation annotation : annotationsList.getAll()) {
363				if (annotation.getVisibility() == AnnotationVisibility.SYSTEM) {
364					continue;
365				}
366				for (Map.Entry<String, EncodedValue> entry : annotation.getValues().entrySet()) {
367					checkEncodedValue(mth, entry.getValue());
368				}
369			}
370		}
371	
372		@SuppressWarnings("unchecked")
373		private void checkEncodedValue(MethodNode mth, EncodedValue encodedValue) {
374			switch (encodedValue.getType()) {
375				case ENCODED_FIELD:
376					Object fieldData = encodedValue.getValue();
377					FieldInfo fieldInfo;
378					if (fieldData instanceof IFieldRef) {
379						fieldInfo = FieldInfo.fromRef(mth.root(), (IFieldRef) fieldData);
380					} else {
381						fieldInfo = (FieldInfo) fieldData;
382					}
383					FieldNode fieldNode = mth.root().resolveField(fieldInfo);
384					if (fieldNode != null) {
385						fieldNode.addUseIn(mth);
386					}
387					break;
388	
389				case ENCODED_ANNOTATION:
390					IAnnotation annotation = (IAnnotation) encodedValue.getValue();
391					annotation.getValues().forEach((k, v) -> checkEncodedValue(mth, v));
392					break;
393	
394				case ENCODED_ARRAY:
395					List<EncodedValue> valueList = (List<EncodedValue>) encodedValue.getValue();
396					valueList.forEach(v -> checkEncodedValue(mth, v));
397					break;
398			}
399		}
400	
401		private void addNullCasts(MethodNode mth, BlockNode block) {
402			for (InsnNode insn : block.getInstructions()) {
403				switch (insn.getType()) {
404					case INVOKE:
405						verifyNullCast(mth, ((InvokeNode) insn).getInstanceArg());
406						break;
407	
408					case ARRAY_LENGTH:
409						verifyNullCast(mth, insn.getArg(0));
410						break;
411				}
412			}
413		}
414	
415		private void verifyNullCast(MethodNode mth, InsnArg arg) {
416			if (arg != null && arg.isZeroConst()) {
417				ArgType castType = arg.getType();
418				IndexInsnNode castInsn = new IndexInsnNode(InsnType.CAST, castType, 1);
419				castInsn.addArg(InsnArg.lit(0, castType));
420				arg.wrapInstruction(mth, castInsn);
421			}
422		}
423	}
