48	final class IfRegionMaker {
49		private static final Logger LOG = LoggerFactory.getLogger(IfRegionMaker.class);
50		private final MethodNode mth;
51		private final RegionMaker regionMaker;
52	
53		IfRegionMaker(MethodNode mth, RegionMaker regionMaker) {
54			this.mth = mth;
55			this.regionMaker = regionMaker;
56		}
57	
58		@Nullable
59		BlockNode process(IRegion currentRegion, BlockNode block, IfNode ifnode, RegionStack stack) {
60			if (block.contains(AFlag.ADDED_TO_REGION)) {
61				// block already included in other 'if' region
62				return ifnode.getThenBlock();
63			}
64			IfInfo currentIf = makeIfInfo(mth, block);
65			if (currentIf == null) {
66				return null;
67			}
68			IfInfo mergedIf = mergeNestedIfNodes(currentIf);
69			if (mergedIf != null) {
70				currentIf = mergedIf;
71			} else {
72				// invert simple condition (compiler often do it)
73				// ensure that we only ever invert once, because if multiple regions contain this block
74				// we'll change the block after it's already been included in a region, which can cause
75				// other regions containing the block to believe the condition has been flipped when it
76				// has not, or vice versa.
77				if (!block.contains(AFlag.DONT_INVERT)) {
78					currentIf = IfInfo.invert(currentIf);
79					block.add(AFlag.DONT_INVERT);
80				}
81			}
82			IfInfo modifiedIf = restructureIf(block, currentIf);
83			if (modifiedIf != null) {
84				currentIf = modifiedIf;
85			} else {
86				if (currentIf.getMergedBlocks().size() <= 1) {
87					return null;
88				}
89				currentIf = makeIfInfo(mth, block);
90				currentIf = restructureIf(block, currentIf);
91				if (currentIf == null) {
92					// all attempts failed
93					return null;
94				}
95			}
96			confirmMerge(currentIf);
97	
98			IfRegion ifRegion = new IfRegion(currentRegion);
99			ifRegion.updateCondition(currentIf);
100			currentRegion.getSubBlocks().add(ifRegion);
101	
102			BlockNode outBlock = currentIf.getOutBlock();
103			stack.push(ifRegion);
104			stack.addExit(outBlock);
105	
106			BlockNode thenBlock = currentIf.getThenBlock();
107			if (thenBlock == null) {
108				// empty then block, not normal, but maybe correct
109				ifRegion.setThenRegion(new Region(ifRegion));
110			} else {
111				ifRegion.setThenRegion(regionMaker.makeRegion(thenBlock));
112			}
113			BlockNode elseBlock = currentIf.getElseBlock();
114			if (elseBlock == null || stack.containsExit(elseBlock)) {
115				ifRegion.setElseRegion(null);
116			} else {
117				ifRegion.setElseRegion(regionMaker.makeRegion(elseBlock));
118			}
119	
120			// insert edge insns in new 'else' branch
121			if (ifRegion.getElseRegion() == null && outBlock != null) {
122				List<EdgeInsnAttr> edgeInsnAttrs = outBlock.getAll(AType.EDGE_INSN);
123				if (!edgeInsnAttrs.isEmpty()) {
124					List<InsnNode> instructions = new ArrayList<>();
125					for (EdgeInsnAttr edgeInsnAttr : edgeInsnAttrs) {
126						if (edgeInsnAttr.getEnd().equals(outBlock)) {
127							if (currentIf.getMergedBlocks().contains(followEmptyPath(edgeInsnAttr.getStart(), true))) {
128								instructions.add(edgeInsnAttr.getInsn());
129							}
130						}
131					}
132	
133					if (!instructions.isEmpty()) {
134						Region elseRegion = new Region(ifRegion);
135						InsnContainer newBlock = new InsnContainer(instructions);
136						elseRegion.add(newBlock);
137						ifRegion.setElseRegion(elseRegion);
138					}
139				}
140			}
141	
142			stack.pop();
143			return outBlock;
144		}
145	
146		@NotNull
147		IfInfo buildIfInfo(LoopRegion loopRegion) {
148			IfInfo condInfo = makeIfInfo(mth, loopRegion.getHeader());
149			condInfo = searchNestedIf(condInfo);
150			confirmMerge(condInfo);
151			return condInfo;
152		}
153	
154		@Nullable
155		static IfInfo makeIfInfo(MethodNode mth, BlockNode ifBlock) {
156			InsnNode lastInsn = BlockUtils.getLastInsn(ifBlock);
157			if (lastInsn == null || lastInsn.getType() != InsnType.IF) {
158				return null;
159			}
160			IfNode ifNode = (IfNode) lastInsn;
161			IfCondition condition = IfCondition.fromIfNode(ifNode);
162			IfInfo info = new IfInfo(mth, condition, ifNode.getThenBlock(), ifNode.getElseBlock());
163			info.getMergedBlocks().add(ifBlock);
164			return info;
165		}
166	
167		static IfInfo searchNestedIf(IfInfo info) {
168			IfInfo next = mergeNestedIfNodes(info);
169			if (next != null) {
170				return next;
171			}
172			return info;
173		}
174	
175		IfInfo restructureIf(BlockNode block, IfInfo info) {
176			BlockNode thenBlock = info.getThenBlock();
177			BlockNode elseBlock = info.getElseBlock();
178	
179			if (Objects.equals(thenBlock, elseBlock)) {
180				IfInfo ifInfo = new IfInfo(info, null, null);
181				ifInfo.setOutBlock(thenBlock);
182				return ifInfo;
183			}
184	
185			// select 'then', 'else' and 'exit' blocks
186			if (thenBlock.contains(AFlag.RETURN) && elseBlock.contains(AFlag.RETURN)) {
187				info.setOutBlock(null);
188				return info;
189			}
190			// init outblock, which will be used in isBadBranchBlock to compare with branch block
191			info.setOutBlock(findOutBlock(mth, thenBlock, elseBlock));
192	
193			boolean badThen = isBadBranchBlock(info, thenBlock);
194			boolean badElse = isBadBranchBlock(info, elseBlock);
195			if (badThen && badElse) {
196				if (Consts.DEBUG_RESTRUCTURE) {
197					LOG.debug("Stop processing blocks after 'if': {}, method: {}", info.getMergedBlocks(), mth);
198				}
199				return null;
200			}
201			if (badElse) {
202				info = new IfInfo(info, thenBlock, null);
203				info.setOutBlock(elseBlock);
204			} else if (badThen) {
205				info = IfInfo.invert(info);
206				info = new IfInfo(info, elseBlock, null);
207				info.setOutBlock(thenBlock);
208			}
209	
210			// getPathCross may not find outBlock (e.g. one branch has return, outBlock definitely is
211			// null), so should check further
212			if (info.getOutBlock() == null) {
213				BlockNode scopeOutBlockThen = findScopeOutBlock(info.getThenBlock());
214				BlockNode scopeOutBlockElse = findScopeOutBlock(info.getElseBlock());
215				if (scopeOutBlockThen == null && scopeOutBlockElse != null) {
216					info.setOutBlock(scopeOutBlockElse);
217				} else if (scopeOutBlockThen != null && scopeOutBlockElse == null) {
218					info.setOutBlock(scopeOutBlockThen);
219				} else if (scopeOutBlockThen != null && scopeOutBlockThen == scopeOutBlockElse) {
220					info.setOutBlock(scopeOutBlockThen);
221				}
222			}
223	
224			if (BlockUtils.isBackEdge(block, info.getOutBlock())) {
225				info.setOutBlock(null);
226			}
227			return info;
228		}
229	
230		static @Nullable BlockNode findOutBlock(MethodNode mth, BlockNode thenBlock, BlockNode elseBlock) {
231			if (thenBlock == elseBlock) {
232				return thenBlock;
233			}
234			if (thenBlock == null || elseBlock == null) {
235				return null;
236			}
237	
238			BitSet thenDomFrontier = domFrontierWithSelf(mth, thenBlock);
239			BitSet elseDomFrontier = domFrontierWithSelf(mth, elseBlock);
240	
241			BitSet intersection = newBlocksBitSet(mth);
242			intersection.or(thenDomFrontier);
243			intersection.and(elseDomFrontier);
244	
245			intersection.clear(mth.getExitBlock().getPos());
246			BlockNode oneBlock = bitSetToOneBlock(mth, intersection);
247	
248			// Attempt one: there's a unique block in the intersection of dom frontiers, and no path from
249			// then->else or else->then
250			if (oneBlock != null) {
251				return oneBlock;
252			}
253	
254			BitSet union = newBlocksBitSet(mth);
255			union.or(thenBlock.getDomFrontier());
256			union.or(elseBlock.getDomFrontier());
257			union.clear(mth.getExitBlock().getPos());
258	
259			// Attempt two: look for a suitable block in the union.
260			BitSet candidates = newBlocksBitSet(mth);
261			for (BlockNode candidate : bitSetToBlocks(mth, union)) {
262				if (isCandidateForOutBlock(mth, thenBlock, elseBlock, candidate)) {
263					candidates.set(candidate.getPos());
264				}
265			}
266	
267			BlockNode bottom = getBottomBlock(bitSetToBlocks(mth, candidates), true);
268			if (bottom != null) {
269				return bottom;
270			}
271	
272			// Attempt three: fallback to path cross again
273			return getPathCross(mth, thenBlock, elseBlock);
274		}
275	
276		static boolean isCandidateForOutBlock(MethodNode mth, BlockNode thenBlock, BlockNode elseBlock, BlockNode candidate) {
277			// a candidate block requires:
278			// - >1 predecessor
279			// - each predecessor has a clean path from elseBlock or thenBlock, and there exist predecessors
280			// covering both cases
281			// - inside the union of the two dom frontiers
282	
283			if (candidate.getPredecessors().size() < 2) {
284				return false; // block has only one pred, and so can't be the outblock
285			}
286	
287			BitSet coverageThenPreds = newBlocksBitSet(mth);
288			BitSet coverageElsePreds = newBlocksBitSet(mth);
289	
290			if (candidate == elseBlock) {
291				coverageElsePreds.set(candidate.getPos());
292			}
293			if (candidate == thenBlock) {
294				coverageThenPreds.set(candidate.getPos());
295			}
296	
297			for (BlockNode pred : candidate.getPredecessors()) {
298				if (isPathExists(thenBlock, pred)) {
299					coverageThenPreds.set(pred.getPos());
300				}
301	
302				if (isPathExists(elseBlock, pred)) {
303					coverageElsePreds.set(pred.getPos());
304				}
305			}
306			if (coverageElsePreds.cardinality() == 0 || coverageThenPreds.cardinality() == 0) {
307				return false; // block has no path to both the then and else blocks
308			}
309	
310			BlockNode coverageElsePred = bitSetToOneBlock(mth, coverageElsePreds);
311			BlockNode coverageThenPred = bitSetToOneBlock(mth, coverageThenPreds);
312			if (coverageElsePred != null && coverageElsePred == coverageThenPred) {
313				return false; // the only paths from else and then go through the same block
314			}
315	
316			return true;
317		}
318	
319		private static boolean isBadBranchBlock(IfInfo info, BlockNode block) {
320			// check if block at end of loop edge
321			if (block.contains(AFlag.LOOP_START) && block.getPredecessors().size() == 1) {
322				BlockNode pred = block.getPredecessors().get(0);
323				if (pred.contains(AFlag.LOOP_END)) {
324					List<LoopInfo> startLoops = block.getAll(AType.LOOP);
325					List<LoopInfo> endLoops = pred.getAll(AType.LOOP);
326					// search for same loop
327					for (LoopInfo startLoop : startLoops) {
328						for (LoopInfo endLoop : endLoops) {
329							if (startLoop == endLoop) {
330								return true;
331							}
332						}
333					}
334				}
335			}
336			// if branch block itself is outblock
337			if (info.getOutBlock() != null) {
338				return block == info.getOutBlock();
339			}
340			return !allPathsFromIf(block, info);
341		}
342	
343		private static boolean allPathsFromIf(BlockNode block, IfInfo info) {
344			List<BlockNode> preds = block.getPredecessors();
345			BlockSet ifBlocks = info.getMergedBlocks();
346			for (BlockNode pred : preds) {
347				if (pred.contains(AFlag.LOOP_END)) {
348					// ignore loop back edge
349					continue;
350				}
351				BlockNode top = BlockUtils.skipSyntheticPredecessor(pred);
352				if (!ifBlocks.contains(top)) {
353					return false;
354				}
355			}
356			return true;
357		}
358	
359		/**
360		 * if startBlock is in a (try) scope, find the scope end as outBlock
361		 */
362		private @Nullable BlockNode findScopeOutBlock(BlockNode startBlock) {
363			if (startBlock == null) {
364				return null;
365			}
366			List<BlockNode> domFrontiers = BlockUtils.bitSetToBlocks(mth, startBlock.getDomFrontier());
367			BlockNode scopeOutBlock = null;
368	
369			// find handler from domFrontier(could be scope end), if domFrontier is handler
370			// and its topSplitter dominates branch block, then branch should end
371			for (BlockNode domFrontier : domFrontiers) {
372				ExcHandlerAttr handler = domFrontier.get(AType.EXC_HANDLER);
373				if (handler == null) {
374					continue;
375				}
376				BlockNode topSplitter = handler.getTryBlock().getTopSplitter();
377				if (startBlock.isDominator(topSplitter)) {
378					scopeOutBlock = BlockUtils.getTryAndHandlerCrossBlock(mth, handler.getHandler());
379					break;
380				}
381			}
382			if (scopeOutBlock != null) {
383				// check if out block still inside scope limited by 'exit' blocks
384				for (BlockNode exit : regionMaker.getStack().getExits()) {
385					if (BlockUtils.isPathExists(exit, scopeOutBlock)) {
386						return null;
387					}
388				}
389			}
390			return scopeOutBlock;
