393		static IfInfo mergeNestedIfNodes(IfInfo currentIf) {
394			BlockNode curThen = currentIf.getThenBlock();
395			BlockNode curElse = currentIf.getElseBlock();
396			if (curThen == curElse) {
397				return null;
398			}
399			if (BlockUtils.isFollowBackEdge(curThen)
400					|| BlockUtils.isFollowBackEdge(curElse)) {
401				return null;
402			}
403			boolean followThenBranch;
404			IfInfo nextIf = getNextIf(currentIf, curThen);
405			if (nextIf != null) {
406				followThenBranch = true;
407			} else {
408				nextIf = getNextIf(currentIf, curElse);
409				if (nextIf != null) {
410					followThenBranch = false;
411				} else {
412					return null;
413				}
414			}
415	
416			boolean assignInlineNeeded = !nextIf.getForceInlineInsns().isEmpty();
417			if (assignInlineNeeded) {
418				for (BlockNode mergedBlock : currentIf.getMergedBlocks()) {
419					if (mergedBlock.contains(AFlag.LOOP_START)) {
420						// don't inline assigns into loop condition
421						return currentIf;
422					}
423				}
424			}
425	
426			if (isInversionNeeded(currentIf, nextIf)) {
427				// invert current node for match pattern
428				nextIf = IfInfo.invert(nextIf);
429			}
430			boolean thenPathSame = isEqualPaths(curThen, nextIf.getThenBlock());
431			boolean elsePathSame = isEqualPaths(curElse, nextIf.getElseBlock());
432			if (!thenPathSame && !elsePathSame) {
433				// complex condition, run additional checks
434				if (checkConditionBranches(curThen, curElse)
435						|| checkConditionBranches(curElse, curThen)) {
436					return null;
437				}
438				BlockNode otherBranchBlock = followThenBranch ? curElse : curThen;
439				otherBranchBlock = BlockUtils.followEmptyPath(otherBranchBlock);
440				if (!isPathExists(nextIf.getFirstIfBlock(), otherBranchBlock)) {
441					return checkForTernaryInCondition(currentIf);
442				}
443	
444				// this is nested conditions with different mode (i.e (a && b) || c),
445				// search next condition for merge, get null if failed
446				IfInfo tmpIf = mergeNestedIfNodes(nextIf);
447				if (tmpIf != null) {
448					nextIf = tmpIf;
449					if (isInversionNeeded(currentIf, nextIf)) {
450						nextIf = IfInfo.invert(nextIf);
451					}
452					if (!canMerge(currentIf, nextIf, followThenBranch)) {
453						return currentIf;
454					}
455				} else {
456					return currentIf;
457				}
458			} else {
459				if (assignInlineNeeded) {
460					boolean sameOuts = (thenPathSame && !followThenBranch) || (elsePathSame && followThenBranch);
461					if (!sameOuts) {
462						// don't inline assigns inside simple condition
463						currentIf.resetForceInlineInsns();
464						return currentIf;
465					}
466				}
467			}
468	
469			IfInfo result = mergeIfInfo(currentIf, nextIf, followThenBranch);
470			// search next nested if block
471			return searchNestedIf(result);
472		}
