474		private static IfInfo checkForTernaryInCondition(IfInfo currentIf) {
475			IfInfo nextThen = getNextIf(currentIf, currentIf.getThenBlock());
476			IfInfo nextElse = getNextIf(currentIf, currentIf.getElseBlock());
477			if (nextThen == null || nextElse == null) {
478				return null;
479			}
480			if (!nextThen.getFirstIfBlock().getDomFrontier().equals(nextElse.getFirstIfBlock().getDomFrontier())) {
481				return null;
482			}
483			nextThen = searchNestedIf(nextThen);
484			nextElse = searchNestedIf(nextElse);
485			if (nextThen.getThenBlock() == nextElse.getThenBlock()
486					&& nextThen.getElseBlock() == nextElse.getElseBlock()) {
487				return mergeTernaryConditions(currentIf, nextThen, nextElse);
488			}
489			if (nextThen.getThenBlock() == nextElse.getElseBlock()
490					&& nextThen.getElseBlock() == nextElse.getThenBlock()) {
491				nextElse = IfInfo.invert(nextElse);
492				return mergeTernaryConditions(currentIf, nextThen, nextElse);
493			}
494			return null;
495		}
496	
497		private static IfInfo mergeTernaryConditions(IfInfo currentIf, IfInfo nextThen, IfInfo nextElse) {
498			IfCondition newCondition = IfCondition.ternary(currentIf.getCondition(),
499					nextThen.getCondition(), nextElse.getCondition());
500			IfInfo result = new IfInfo(currentIf.getMth(), newCondition, nextThen.getThenBlock(), nextThen.getElseBlock());
501			result.merge(currentIf, nextThen, nextElse);
502			confirmMerge(result);
503			return result;
504		}
505	
506		private static boolean isInversionNeeded(IfInfo currentIf, IfInfo nextIf) {
507			return isEqualPaths(currentIf.getElseBlock(), nextIf.getThenBlock())
508					|| isEqualPaths(currentIf.getThenBlock(), nextIf.getElseBlock());
509		}
510	
511		private static boolean canMerge(IfInfo a, IfInfo b, boolean followThenBranch) {
512			if (followThenBranch) {
513				return isEqualPaths(a.getElseBlock(), b.getElseBlock());
514			} else {
515				return isEqualPaths(a.getThenBlock(), b.getThenBlock());
516			}
517		}
518	
519		private static boolean checkConditionBranches(BlockNode from, BlockNode to) {
520			return from.getCleanSuccessors().size() == 1 && from.getCleanSuccessors().contains(to);
521		}
522	
523		static IfInfo mergeIfInfo(IfInfo first, IfInfo second, boolean followThenBranch) {
524			MethodNode mth = first.getMth();
525			Set<BlockNode> skipBlocks = first.getSkipBlocks();
526			BlockNode thenBlock;
527			BlockNode elseBlock;
528			if (followThenBranch) {
529				thenBlock = second.getThenBlock();
530				elseBlock = getBranchBlock(first.getElseBlock(), second.getElseBlock(), skipBlocks, mth);
531			} else {
532				thenBlock = getBranchBlock(first.getThenBlock(), second.getThenBlock(), skipBlocks, mth);
533				elseBlock = second.getElseBlock();
534			}
535			IfCondition.Mode mergeOperation = followThenBranch ? IfCondition.Mode.AND : IfCondition.Mode.OR;
536			IfCondition condition = IfCondition.merge(mergeOperation, first.getCondition(), second.getCondition());
537			IfInfo result = new IfInfo(mth, condition, thenBlock, elseBlock);
538			result.merge(first, second);
539			return result;
540		}
