542		private static BlockNode getBranchBlock(BlockNode first, BlockNode second, Set<BlockNode> skipBlocks, MethodNode mth) {
543			if (first == second) {
544				return second;
545			}
546			if (isEqualReturnBlocks(first, second)) {
547				skipBlocks.add(first);
548				return second;
549			}
550			if (BlockUtils.isDuplicateBlockPath(first, second)) {
551				first.add(AFlag.REMOVE);
552				skipBlocks.add(first);
553				return second;
554			}
555			BlockNode cross = BlockUtils.getPathCross(mth, first, second);
556			if (cross != null) {
557				BlockUtils.visitBlocksOnPath(mth, first, cross, skipBlocks::add);
558				BlockUtils.visitBlocksOnPath(mth, second, cross, skipBlocks::add);
559				skipBlocks.remove(cross);
560				return cross;
561			}
562			BlockNode firstSkip = BlockUtils.followEmptyPath(first);
563			BlockNode secondSkip = BlockUtils.followEmptyPath(second);
564			if (firstSkip.equals(secondSkip) || isEqualReturnBlocks(firstSkip, secondSkip)) {
565				skipBlocks.add(first);
566				skipBlocks.add(second);
567				BlockUtils.visitBlocksOnEmptyPath(first, skipBlocks::add);
568				BlockUtils.visitBlocksOnEmptyPath(second, skipBlocks::add);
569				return secondSkip;
570			}
571			throw new JadxRuntimeException("Unexpected merge pattern");
572		}
