574		static void confirmMerge(IfInfo info) {
575			if (info.getMergedBlocks().size() > 1) {
576				for (BlockNode block : info.getMergedBlocks()) {
577					if (block != info.getFirstIfBlock()) {
578						block.add(AFlag.ADDED_TO_REGION);
579					}
580				}
581			}
582			if (!info.getSkipBlocks().isEmpty()) {
583				for (BlockNode block : info.getSkipBlocks()) {
584					block.add(AFlag.ADDED_TO_REGION);
585				}
586				info.getSkipBlocks().clear();
587			}
588			for (InsnNode forceInlineInsn : info.getForceInlineInsns()) {
589				forceInlineInsn.add(AFlag.FORCE_ASSIGN_INLINE);
590			}
591		}
