593		private static IfInfo getNextIf(IfInfo info, BlockNode block) {
594			if (!canSelectNext(info, block)) {
595				return null;
596			}
597			return getNextIfNodeInfo(info, block);
598		}
599	
600		private static boolean canSelectNext(IfInfo info, BlockNode block) {
601			if (block.getPredecessors().size() == 1) {
602				return true;
603			}
604			return info.getMergedBlocks().containsAll(block.getPredecessors());
605		}
606	
607		private static IfInfo getNextIfNodeInfo(IfInfo info, BlockNode block) {
608			if (block == null || block.contains(AType.LOOP) || block.contains(AFlag.ADDED_TO_REGION)) {
609				return null;
610			}
611			InsnNode lastInsn = BlockUtils.getLastInsn(block);
612			if (lastInsn != null && lastInsn.getType() == InsnType.IF) {
613				return makeIfInfo(info.getMth(), block);
614			}
615			BlockNode next = getNextBlockInIfSuccessorChain(block);
616			if (next == null) {
617				return null;
618			}
619			if (next.getPredecessors().size() != 1 || next.contains(AFlag.ADDED_TO_REGION)) {
620				return null;
621			}
622			List<InsnNode> forceInlineInsns = new ArrayList<>();
623			if (!checkInsnsInline(block, next, forceInlineInsns)) {
624				return null;
625			}
626			IfInfo nextInfo = makeIfInfo(info.getMth(), next);
627			if (nextInfo == null) {
628				return getNextIfNodeInfo(info, next);
629			}
630			nextInfo.addInsnsForForcedInline(forceInlineInsns);
631			return nextInfo;
632		}
633	
634		/**
635		 * Allow singular successor to block or 2 successors where one is a EXC_BOTTOM_SPLITTER
636		 */
637		private static @Nullable BlockNode getNextBlockInIfSuccessorChain(BlockNode block) {
638	
639			// skip this block and search in successors chain
640			List<BlockNode> successors = block.getSuccessors();
641			if (successors.size() > 2 || successors.size() == 0) {
642				return null;
643			}
644			// We might have the next IF and a EXC_BOTTOM_SPLITTER block to delimit a try region
645			BlockNode first = successors.get(0);
646			if (successors.size() == 1) {
647				return first;
648			}
649			BlockNode second = successors.get(1);
650			boolean firstIsHandlerPath = first.contains(AFlag.EXC_BOTTOM_SPLITTER);
651			boolean secondIsHandlerPath = second.contains(AFlag.EXC_BOTTOM_SPLITTER);
652			if (!firstIsHandlerPath && !secondIsHandlerPath) {
653				// unknown case
654				return null;
655			}
656			if (firstIsHandlerPath && secondIsHandlerPath) {
657				// unknown case
658				return null;
659			}
660			BlockNode candidate = firstIsHandlerPath ? second : first;
661	
662			// Continue to recurse through blocks as long as none of them have any instructions
663			if (candidate.getInstructions().isEmpty()) {
664				return getNextBlockInIfSuccessorChain(candidate);
665			}
666	
667			return candidate;
668		}
669	
670		/**
671		 * Check that all instructions can be inlined
672		 */
673		private static boolean checkInsnsInline(BlockNode block, BlockNode next, List<InsnNode> forceInlineInsns) {
674			List<InsnNode> insns = block.getInstructions();
675			if (insns.isEmpty()) {
676				return true;
677			}
678			boolean pass = true;
679			for (InsnNode insn : insns) {
680				RegisterArg res = insn.getResult();
681				if (res == null) {
682					return false;
683				}
684				List<RegisterArg> useList = res.getSVar().getUseList();
685				int useCount = useList.size();
686				if (useCount == 0) {
687					// TODO?
688					return false;
689				}
690				InsnArg arg = useList.get(0);
691				InsnNode usePlace = arg.getParentInsn();
692				if (!BlockUtils.blockContains(block, usePlace)
693						&& !BlockUtils.blockContains(next, usePlace)) {
694					return false;
695				}
696				if (useCount > 1) {
697					forceInlineInsns.add(insn);
698				} else {
699					// allow only forced assign inline
700					pass = false;
701				}
702			}
703			return pass;
704		}
