706		private static BitSet domFrontierWithSelf(MethodNode mth, BlockNode block) {
707			BitSet bs = newBlocksBitSet(mth);
708			bs.or(block.getDomFrontier());
709			bs.set(block.getPos());
710			return bs;
711		}
