81		private boolean applyResolvedVars() {
82			List<TypeSearchVarInfo> resolvedVars = state.getResolvedVars();
83			List<TypeSearchVarInfo> updatedVars = new ArrayList<>();
84			for (TypeSearchVarInfo var : resolvedVars) {
85				SSAVar ssaVar = var.getVar();
86				ArgType resolvedType = var.getCurrentType();
87				if (!resolvedType.isTypeKnown()) {
88					// ignore unknown variables
89					continue;
90				}
91				if (resolvedType.equals(ssaVar.getTypeInfo().getType())) {
92					// type already set
93					continue;
94				}
95				ssaVar.setType(resolvedType);
96				updatedVars.add(var);
97			}
98			boolean applySuccess = true;
99			for (TypeSearchVarInfo var : updatedVars) {
100				TypeUpdateResult res = typeUpdate.applyWithWiderIgnSame(mth, var.getVar(), var.getCurrentType());
101				if (res == TypeUpdateResult.REJECT) {
102					mth.addDebugComment("Multi-variable search result rejected for " + var);
103					applySuccess = false;
104				}
105			}
106			return applySuccess;
107		}
