109		private boolean search(List<TypeSearchVarInfo> vars) {
110			int len = vars.size();
111			if (Consts.DEBUG_TYPE_INFERENCE) {
112				LOG.debug("Run multi-variable search for {} vars: ", len);
113				StringBuilder sb = new StringBuilder();
114				long count = 1;
115				for (TypeSearchVarInfo var : vars) {
116					LOG.debug("  {}", var);
117					int size = var.getCandidateTypes().size();
118					sb.append(" * ").append(size);
119					count *= size;
120				}
121				sb.append(" = ").append(count);
122				LOG.debug(" max iterations count = {}", sb);
123			}
124	
125			// prepare vars
126			for (TypeSearchVarInfo var : vars) {
127				var.reset();
128			}
129			// check all types combinations
130			int n = 0;
131			int i = 0;
132			while (!fullCheck(vars)) {
133				TypeSearchVarInfo first = vars.get(i);
134				if (first.nextType()) {
135					int k = i + 1;
136					if (k >= len) {
137						return false;
138					}
139					TypeSearchVarInfo next = vars.get(k);
140					while (true) {
141						if (next.nextType()) {
142							k++;
143							if (k >= len) {
144								return false;
145							}
146							next = vars.get(k);
147						} else {
148							break;
149						}
150					}
151				}
152				n++;
153				if (n > SEARCH_ITERATION_LIMIT) {
154					if (Consts.DEBUG_TYPE_INFERENCE) {
155						LOG.debug(" > iterations limit reached: {}", SEARCH_ITERATION_LIMIT);
156					}
157					return false;
158				}
159			}
160			if (Consts.DEBUG_TYPE_INFERENCE) {
161				LOG.debug(" > done after {} iterations", n);
162			}
163			// mark all vars as resolved
164			for (TypeSearchVarInfo var : vars) {
165				var.setTypeResolved(true);
166			}
167			return true;
168		}
