54		@Override
55		public boolean visit(ClassNode cls) throws JadxException {
56			if (cls.contains(AFlag.PACKAGE_INFO)) {
57				return false;
58			}
59			for (ClassNode inner : cls.getInnerClasses()) {
60				visit(inner);
61			}
62			if (isEmptySyntheticClass(cls)) {
63				cls.add(AFlag.DONT_GENERATE);
64				return false;
65			}
66			removeSyntheticFields(cls);
67			cls.getMethods().forEach(ClassModifier::removeSyntheticMethods);
68			cls.getMethods().forEach(ClassModifier::removeEmptyMethods);
69			return false;
70		}
