82		private static void removeSyntheticFields(ClassNode cls) {
83			boolean inline = cls.isAnonymous();
84			if (inline || cls.getClassInfo().isInner()) {
85				for (FieldNode field : cls.getFields()) {
86					ArgType fldType = field.getType();
87					if (field.getAccessFlags().isSynthetic() && fldType.isObject() && !fldType.isGenericType()) {
88						ClassInfo clsInfo = ClassInfo.fromType(cls.root(), fldType);
89						ClassNode fieldsCls = cls.root().resolveClass(clsInfo);
90						ClassInfo parentClass = cls.getClassInfo().getParentClass();
91						if (fieldsCls == null) {
92							continue;
93						}
94						boolean isParentInst = Objects.equals(parentClass, fieldsCls.getClassInfo());
95						if (inline || isParentInst) {
96							int found = 0;
97							for (MethodNode mth : cls.getMethods()) {
98								if (removeFieldUsageFromConstructor(mth, field, fieldsCls)) {
99									found++;
100								}
101							}
102							if (found != 0) {
103								if (isParentInst) {
104									field.addAttr(new FieldReplaceAttr(fieldsCls.getClassInfo()));
105								}
106								field.add(AFlag.DONT_GENERATE);
