114		private static boolean removeFieldUsageFromConstructor(MethodNode mth, FieldNode field, ClassNode fieldsCls) {
115			if (mth.isNoCode() || !mth.getAccessFlags().isConstructor()) {
116				return false;
117			}
118			List<RegisterArg> args = mth.getArgRegs();
119			if (args.isEmpty() || mth.contains(AFlag.SKIP_FIRST_ARG)) {
120				return false;
121			}
122			RegisterArg arg = args.get(0);
123			if (!arg.getType().equals(fieldsCls.getClassInfo().getType())) {
124				return false;
125			}
126			BlockNode block = mth.getEnterBlock().getCleanSuccessors().get(0);
127			List<InsnNode> instructions = block.getInstructions();
128			if (instructions.isEmpty()) {
129				return false;
130			}
131			InsnNode insn = instructions.get(0);
132			if (insn.getType() != InsnType.IPUT) {
133				return false;
134			}
135			IndexInsnNode putInsn = (IndexInsnNode) insn;
136			FieldInfo fieldInfo = (FieldInfo) putInsn.getIndex();
137			if (!fieldInfo.equals(field.getFieldInfo()) || !putInsn.getArg(0).equals(arg)) {
138				return false;
139			}
140			mth.skipFirstArgument();
141			InsnRemover.remove(mth, block, insn);
142			// other arg usage -> wrap with IGET insn
143			if (arg.getSVar().getUseCount() != 0) {
144				InsnNode iget = new IndexInsnNode(InsnType.IGET, fieldInfo, 1);
145				iget.addArg(insn.getArg(1));
146				for (InsnArg insnArg : new ArrayList<>(arg.getSVar().getUseList())) {
147					insnArg.wrapInstruction(mth, iget);
148				}
149			}
150			return true;
151		}
