153		private static void removeSyntheticMethods(MethodNode mth) {
154			if (mth.isNoCode() || mth.contains(AFlag.DONT_GENERATE)) {
155				return;
156			}
157			AccessInfo af = mth.getAccessFlags();
158			if (!af.isSynthetic()) {
159				return;
160			}
161			ClassNode cls = mth.getParentClass();
162			if (removeBridgeMethod(cls, mth)) {
163				if (Consts.DEBUG) {
164					mth.addDebugComment("Removed as synthetic bridge method");
165				} else {
166					mth.add(AFlag.DONT_GENERATE);
167				}
168				return;
169			}
170			// remove synthetic constructor for inner classes
171			if (mth.isConstructor()
172					&& (mth.contains(AFlag.METHOD_CANDIDATE_FOR_INLINE) || mth.contains(AFlag.ANONYMOUS_CONSTRUCTOR))) {
173				InsnNode insn = BlockUtils.getOnlyOneInsnFromMth(mth);
174				if (insn != null) {
175					List<RegisterArg> args = mth.getArgRegs();
176					if (isRemovedClassInArgs(cls, args)) {
177						modifySyntheticMethod(cls, mth, insn, args);
178					}
179				}
180			}
181		}
