183		private static boolean isRemovedClassInArgs(ClassNode cls, List<RegisterArg> mthArgs) {
184			boolean removedFound = false;
185			for (RegisterArg arg : mthArgs) {
186				ArgType argType = arg.getType();
187				if (!argType.isObject()) {
188					continue;
189				}
190				boolean remove = false;
191				ClassNode argCls = cls.root().resolveClass(argType);
192				if (argCls == null) {
193					// check if missing class from current top class
194					ClassInfo argClsInfo = ClassInfo.fromType(cls.root(), argType);
195					if (argClsInfo.getParentClass() != null
196							&& cls.getFullName().startsWith(argClsInfo.getParentClass().getFullName())) {
197						remove = true;
198					}
199				} else {
200					if (argCls.contains(AFlag.DONT_GENERATE) || isEmptySyntheticClass(argCls)) {
201						remove = true;
202					}
203				}
204				if (remove) {
205					arg.add(AFlag.REMOVE);
206					removedFound = true;
207				}
208			}
209			return removedFound;
210		}
