215		private static void modifySyntheticMethod(ClassNode cls, MethodNode mth, InsnNode insn, List<RegisterArg> args) {
216			if (insn.getType() == InsnType.CONSTRUCTOR) {
217				ConstructorInsn constr = (ConstructorInsn) insn;
218				if (constr.isThis() && !args.isEmpty()) {
219					// remove first arg for non-static class (references to outer class)
220					RegisterArg firstArg = args.get(0);
221					if (firstArg.getType().equals(cls.getParentClass().getClassInfo().getType())) {
222						SkipMethodArgsAttr.skipArg(mth, 0);
223					}
224					// remove unused args
225					int argsCount = args.size();
226					for (int i = 0; i < argsCount; i++) {
227						RegisterArg arg = args.get(i);
228						SSAVar sVar = arg.getSVar();
229						if (sVar != null && sVar.getUseCount() == 0) {
230							SkipMethodArgsAttr.skipArg(mth, i);
231						}
232					}
233					MethodInfo callMth = constr.getCallMth();
234					MethodNode callMthNode = cls.root().resolveMethod(callMth);
235					if (callMthNode != null) {
236						mth.addAttr(new MethodReplaceAttr(callMthNode));
237						mth.add(AFlag.DONT_GENERATE);
238						// code generation order should be already fixed for marked methods
239						UsageInfoVisitor.replaceMethodUsage(callMthNode, mth);
240					}
241				}
242			}
243		}
