245		private static boolean removeBridgeMethod(ClassNode cls, MethodNode mth) {
246			if (cls.root().getArgs().isInlineMethods()) { // simple wrapper remove is same as inline
247				List<InsnNode> allInsns = BlockUtils.collectAllInsns(mth.getBasicBlocks());
