191		public static BlockInsnPair getLastInsnWithBlock(IContainer container) {
192			if (container instanceof IBlock) {
193				IBlock block = (IBlock) container;
194				InsnNode lastInsn = ListUtils.last(block.getInstructions());
195				if (lastInsn == null) {
196					return null;
197				}
198				return new BlockInsnPair(block, lastInsn);
199			}
200			if (container instanceof IBranchRegion) {
201				List<IContainer> branches = ((IBranchRegion) container).getBranches();
202				int count = 0;
203				for (IContainer branch : branches) {
204					if (branch != null) {
205						count++;
206					}
207				}
208				if (count == 1) {
209					// single branch
210					for (IContainer branch : branches) {
211						if (branch != null) {
212							return getLastInsnWithBlock(branch);
213						}
214					}
215				}
216				// several last instructions
217				return null;
218			}
219			if (container instanceof IRegion) {
220				IRegion region = (IRegion) container;
221				List<IContainer> blocks = region.getSubBlocks();
222				if (blocks.isEmpty()) {
223					return null;
224				}
225				return getLastInsnWithBlock(ListUtils.last(blocks));
226			}
227			throw new JadxRuntimeException(unknownContainerType(container));
228		}
