263		private static boolean hasExitBlock(IContainer rootContainer, IContainer container) {
264			if (container instanceof BlockNode) {
265				BlockNode blockNode = (BlockNode) container;
266				if (BlockUtils.isExitBlock(blockNode)) {
267					return true;
268				}
269				return isInsnExitContainer(rootContainer, (IBlock) container);
270			}
271			if (container instanceof IBranchRegion) {
272				IBranchRegion branchRegion = (IBranchRegion) container;
273				return ListUtils.allMatch(branchRegion.getBranches(), RegionUtils::hasExitBlock);
274			}
275			if (container instanceof IBlock) {
276				return isInsnExitContainer(rootContainer, (IBlock) container);
277			}
278			if (container instanceof IRegion) {
279				List<IContainer> blocks = ((IRegion) container).getSubBlocks();
280				return !blocks.isEmpty()
281						&& hasExitBlock(rootContainer, blocks.get(blocks.size() - 1));
282			}
283			throw new JadxRuntimeException(unknownContainerType(container));
284		}
