309		private static boolean registersAndCastsOnly(InsnArg arg) {
310			if (arg.isRegister()) {
311				return true;
312			}
313			if (arg.isInsnWrap()) {
314				InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
315				if (wrapInsn.getType() == InsnType.CHECK_CAST) {
316					return registersAndCastsOnly(wrapInsn.getArg(0));
317				}
318			}
319			return false;
320		}
