322		/**
323		 * Remove public empty constructors (static or default)
324		 */
325		private static void removeEmptyMethods(MethodNode mth) {
326			if (!mth.getArgRegs().isEmpty()) {
327				return;
328			}
329			AccessInfo af = mth.getAccessFlags();
330			boolean publicConstructor = mth.isConstructor() && af.isPublic();
331			boolean enumDefConstructor = mth.isConstructor() && mth.getParentClass().contains(AFlag.CONVERTED_ENUM);
332			boolean clsInit = mth.getMethodInfo().isClassInit() && af.isStatic();
333			if (publicConstructor || enumDefConstructor || clsInit) {
334				if (!BlockUtils.isAllBlocksEmpty(mth.getBasicBlocks())) {
335					return;
336				}
337				if (clsInit) {
338					mth.add(AFlag.DONT_GENERATE);
339				} else {
340					// don't remove default constructor if other constructors exists or constructor has annotations
341					if (mth.isDefaultConstructor()
342							&& !isNonDefaultConstructorExists(mth)
343							&& !mth.contains(JadxAttrType.ANNOTATION_LIST)) {
344						mth.add(AFlag.DONT_GENERATE);
345					}
346				}
347			}
348		}
