350		private static boolean isNonDefaultConstructorExists(MethodNode defCtor) {
351			ClassNode parentClass = defCtor.getParentClass();
352			return ListUtils.anyMatch(parentClass.getMethods(),
353					mth -> mth != defCtor && mth.isConstructor() && !mth.isDefaultConstructor());
354		}
