439		public static boolean visitBlocksOnPath(MethodNode mth, BlockNode start, BlockNode end, Consumer<BlockNode> visitor) {
440			visitor.accept(start);
441			if (start == end) {
442				return true;
443			}
444			if (start.getCleanSuccessors().contains(end)) {
445				visitor.accept(end);
446				return true;
447			}
448			// DFS on clean successors
449			BitSet visited = newBlocksBitSet(mth);
450			Deque<BlockNode> queue = new ArrayDeque<>();
451			queue.addLast(start);
452			while (true) {
453				BlockNode current = queue.peekLast();
454				if (current == null) {
455					return false;
456				}
457				boolean added = false;
458				for (BlockNode next : current.getCleanSuccessors()) {
459					if (next == end) {
460						queue.removeFirst(); // start already visited
461						queue.addLast(next);
462						queue.forEach(visitor);
463						return true;
464					}
465					int id = next.getId();
466					if (!visited.get(id)) {
467						visited.set(id);
468						queue.addLast(next);
469						added = true;
470						break;
471					}
472				}
473				if (!added) {
474					queue.pollLast();
475					if (queue.isEmpty()) {
476						return false;
477					}
478				}
479			}
