102			if (allowableOutputArguments.isEmpty()) {
103				return false;
104			}
105			List<RegisterArg> registerArgs = new ArrayList<>();
106			for (InsnArg arg : insn.getArgList()) {
107				if (arg instanceof RegisterArg) {
108					registerArgs.add((RegisterArg) arg);
109				}
110			}
111			return !registerArgs.isEmpty() && allowableOutputArguments.containsAll(registerArgs);
