38			private static boolean canRemoveRegion(IContainer container) {
39				if (container.contains(AFlag.DONT_GENERATE)) {
40					return true;
41				}
42				if (container instanceof BlockNode) {
43					BlockNode block = (BlockNode) container;
44					return block.getInstructions().isEmpty();
45				}
46				if (container instanceof LoopRegion) {
47					LoopRegion loopRegion = (LoopRegion) container;
48					if (loopRegion.isEndless()) {
49						// keep empty endless loops
50						return false;
51					}
52				}
53				if (container instanceof IRegion) {
54					List<IContainer> subBlocks = ((IRegion) container).getSubBlocks();
55					for (IContainer subBlock : subBlocks) {
56						if (!canRemoveRegion(subBlock)) {
57							return false;
58						}
59					}
60					return true;
61				}
62				return false;
63			}
