private boolean isMethodVisibleInCls(MethodNode superMth, ClassNode cls) {
	AccessInfo accessFlags = superMth.getAccessFlags();
	if (accessFlags.isPrivate()) {
		return false;
	}
	if (accessFlags.isPublic() || accessFlags.isProtected()) {
		return true;
	}

