11	import jadx.core.dex.visitors.regions.CheckRegions;
12	import jadx.core.dex.visitors.regions.DepthRegionTraversal;
13	import jadx.core.dex.visitors.regions.IRegionVisitor;
14	import jadx.core.utils.exceptions.JadxException;
15	
16	@JadxVisitor(
17			name = "FixInstructionsVisitor",
18			desc = "Verify and fix instructions (args, casts, compiler inference)",
19			runAfter = {
20					SimplifyVisitor.class, // run STR_CONCAT fix after conversion from StringBuilder
21					CheckRegions.class // work with Regions IR
22			}
23	)
24	public class FixInstructionsVisitor extends AbstractVisitor implements IRegionVisitor {
25	
26		@Override
27		public void visit(MethodNode mth) throws JadxException {
28			if (mth.isNoCode()) {
29				return;
30			}
31			DepthRegionTraversal.traverse(mth, this);
32		}
33	
34		@Override
35		public void processBlock(MethodNode mth, IBlock container) {
36			for (InsnNode insn : container.getInstructions()) {
37				insn.visitInsns(this::fixInsn);
38			}
39		}
40	
41		private void fixInsn(InsnNode insn) {
42			if (insn.getType() == InsnType.STR_CONCAT) {
43				// check if we need to insert empty string arg to force '+' to use string concatenation
44				if (forceStringConcat(insn)) {
45					insn.getArgList().add(0, InsnArg.wrapInsnIntoArg(new ConstStringNode("")));
46				}
47			}
48		}
49	
50		private static boolean forceStringConcat(InsnNode insn) {
51			if (insn.getArgsCount() < 2) {
52				return false;
53			}
54			return !insn.getArg(0).getType().equals(ArgType.STRING)
55					&& !insn.getArg(1).getType().equals(ArgType.STRING);
56		}
57	
58		@Override
59		public boolean enterRegion(MethodNode mth, IRegion region) {
60			return true;
61		}
62	
63		@Override
64		public void leaveRegion(MethodNode mth, IRegion region) {
65		}
66	}
