129		private InsnNode simplifyInsn(MethodNode mth, InsnNode insn, @Nullable InsnNode parentInsn) {
130			if (insn.contains(AFlag.DONT_GENERATE)) {
131				return null;
132			}
133			simplifyArgs(mth, insn);
134			switch (insn.getType()) {
135				case ARITH:
136					return simplifyArith((ArithNode) insn);
137	
138				case IF:
139					simplifyIf(mth, (IfNode) insn);
140					break;
141				case TERNARY:
142					simplifyTernary(mth, (TernaryInsn) insn);
143					break;
144	
145				case INVOKE:
146					return convertInvoke(mth, (InvokeNode) insn);
147	
148				case IPUT:
149				case SPUT:
150					return convertFieldArith(mth, insn);
151	
152				case CAST:
153				case CHECK_CAST:
154					return processCast(mth, (IndexInsnNode) insn, parentInsn);
155	
156				case MOVE:
157					InsnArg firstArg = insn.getArg(0);
158					if (firstArg.isLiteral()) {
159						InsnNode constInsn = new InsnNode(InsnType.CONST, 1);
160						constInsn.setResult(insn.getResult());
161						constInsn.addArg(firstArg);
162						constInsn.copyAttributesFrom(insn);
163						return constInsn;
164					}
165					break;
166	
167				case CONSTRUCTOR:
168					return simplifyStringConstructor(mth, (ConstructorInsn) insn);
169	
170				default:
171					break;
172			}
173			return null;
174		}
175	
176		private InsnNode simplifyStringConstructor(MethodNode mth, ConstructorInsn insn) {
177			if (insn.getCallMth().getDeclClass().getType().equals(ArgType.STRING)
178					&& insn.getArgsCount() != 0
179					&& insn.getArg(0).isInsnWrap()) {
180				InsnNode arrInsn = ((InsnWrapArg) insn.getArg(0)).getWrapInsn();
181				if (arrInsn.getType() == InsnType.FILLED_NEW_ARRAY
182						&& arrInsn.getArgsCount() != 0) {
183					ArgType elemType = ((FilledNewArrayNode) arrInsn).getElemType();
184					if (elemType == ArgType.BYTE || elemType == ArgType.CHAR) {
185						int printable = 0;
186						byte[] arr = new byte[arrInsn.getArgsCount()];
187						for (int i = 0; i < arr.length; i++) {
188							InsnArg arrArg = arrInsn.getArg(i);
189							if (!arrArg.isLiteral()) {
190								return null;
191							}
192							arr[i] = (byte) ((LiteralArg) arrArg).getLiteral();
193							if (NameMapper.isPrintableChar((char) arr[i])) {
194								printable++;
195							}
196						}
197						if (printable >= arr.length - printable) {
198							InsnNode constStr = new ConstStringNode(new String(arr));
199							if (insn.getArgsCount() == 1) {
200								constStr.setResult(insn.getResult());
201								constStr.copyAttributesFrom(insn);
202								InsnRemover.unbindArgUsage(mth, insn.getArg(0));
203								return constStr;
204							} else {
205								InvokeNode in = new InvokeNode(stringGetBytesMth, InvokeType.VIRTUAL, 1);
206								in.addArg(InsnArg.wrapArg(constStr));
207								InsnArg bytesArg = InsnArg.wrapArg(in);
208								bytesArg.setType(stringGetBytesMth.getReturnType());
209								insn.setArg(0, bytesArg);
210								return null;
211							}
212						}
213					}
214				}
215			}
216			return null;
217		}
