219		private static InsnNode processCast(MethodNode mth, IndexInsnNode castInsn, @Nullable InsnNode parentInsn) {
220			if (castInsn.contains(AFlag.EXPLICIT_CAST)) {
221				return null;
222			}
223			InsnArg castArg = castInsn.getArg(0);
224			ArgType argType = castArg.getType();
225	
226			// Don't removes CHECK_CAST for wrapped INVOKE if invoked method returns different type
227			if (castArg.isInsnWrap()) {
228				InsnNode wrapInsn = ((InsnWrapArg) castArg).getWrapInsn();
229				if (wrapInsn.getType() == InsnType.INVOKE) {
230					argType = ((InvokeNode) wrapInsn).getCallMth().getReturnType();
231				}
232			}
233	
234			ArgType castToType = (ArgType) castInsn.getIndex();
235			if (isArithWideUpCast(parentInsn, argType, castToType)) {
236				return null;
237			}
238			if (!ArgType.isCastNeeded(mth.root(), argType, castToType)
239					|| isCastDuplicate(castInsn)
240					|| shadowedByOuterCast(mth.root(), castToType, parentInsn)) {
241				InsnNode insnNode = new InsnNode(InsnType.MOVE, 1);
242				insnNode.setOffset(castInsn.getOffset());
243				insnNode.setResult(InsnNode.duplicateArg(castInsn.getResult()));
244				insnNode.addArg(castArg.duplicate());
245				return insnNode;
246			}
247			return null;
248		}
249	
250		/**
251		 * Keep cast to wide types in arith instructions,
252		 * because arguments type determine instruction used in result bytecode.
253		 * Example: (long) i << 32 - without 'long' cast will be used 'int shift' instruction and result
254		 * will be incorrect
255		 */
256		private static boolean isArithWideUpCast(@Nullable InsnNode parentInsn, ArgType argType, ArgType castToType) {
257			if (parentInsn != null
258					&& parentInsn.getType() == InsnType.ARITH
259					&& argType.isPrimitive() && castToType.isPrimitive()) {
260				return castToType.getRegCount() > argType.getRegCount();
261			}
262			return false;
263		}
264	
265		private static boolean isCastDuplicate(IndexInsnNode castInsn) {
266			return InsnUtils.isCastDuplicate(castInsn) != null;
267		}
268	
269		private static boolean shadowedByOuterCast(RootNode root, ArgType castType, @Nullable InsnNode parentInsn) {
270			if (parentInsn != null && parentInsn.getType() == InsnType.CAST) {
271				ArgType parentCastType = (ArgType) ((IndexInsnNode) parentInsn).getIndex();
272				TypeCompareEnum result = root.getTypeCompare().compareTypes(parentCastType, castType);
273				return result.isNarrow();
274			}
275			return false;
276		}
