278		/**
279		 * Simplify 'cmp' instruction in if condition
280		 */
281		private static void simplifyIf(MethodNode mth, IfNode insn) {
282			InsnArg f = insn.getArg(0);
283			if (f.isInsnWrap()) {
284				InsnNode wi = ((InsnWrapArg) f).getWrapInsn();
285				if (wi.getType() == InsnType.CMP_L || wi.getType() == InsnType.CMP_G) {
286					if (insn.getArg(1).isZeroLiteral()) {
287						insn.changeCondition(insn.getOp(), wi.getArg(0).duplicate(), wi.getArg(1).duplicate());
288						InsnRemover.unbindInsn(mth, wi);
289					} else {
290						LOG.warn("TODO: cmp {}", insn);
291					}
292				}
293			}
294		}
