297		 * Simplify condition in ternary operation
298		 */
299		private static void simplifyTernary(MethodNode mth, TernaryInsn insn) {
300			IfCondition condition = insn.getCondition();
301			if (condition.isCompare()) {
302				simplifyIf(mth, condition.getCompare().getInsn());
303			} else {
304				insn.simplifyCondition();
305			}
306		}
