308		/**
309		 * Simplify chains of calls to StringBuilder#append() plus constructor of StringBuilder.
310		 * Those chains are usually automatically generated by the Java compiler when you create String
311		 * concatenations like <code>"text " + 1 + " text"</code>.
312		 */
313		private static InsnNode convertInvoke(MethodNode mth, InvokeNode insn) {
314			MethodInfo callMth = insn.getCallMth();
315	
316			if (callMth.getDeclClass().getFullName().equals(Consts.CLASS_STRING_BUILDER)
317					&& callMth.getShortId().equals(Consts.MTH_TOSTRING_SIGNATURE)) {
318				InsnArg instanceArg = insn.getArg(0);
319				if (instanceArg.isInsnWrap()) {
320					// Convert 'new StringBuilder(xxx).append(yyy).append(zzz).toString() to STRING_CONCAT insn
321					List<InsnNode> callChain = flattenInsnChainUntil(insn, InsnType.CONSTRUCTOR);
322					return convertStringBuilderChain(mth, insn, callChain);
323				}
324				if (instanceArg.isRegister()) {
325					// Convert 'StringBuilder sb = new StringBuilder(xxx); sb.append(yyy); String str = sb.toString();'
326					List<InsnNode> useChain = collectUseChain(mth, insn, (RegisterArg) instanceArg);
327					return convertStringBuilderChain(mth, insn, useChain);
328				}
329			}
330			return null;
331		}
332	
333		private static List<InsnNode> collectUseChain(MethodNode mth, InvokeNode insn, RegisterArg instanceArg) {
334			SSAVar sVar = instanceArg.getSVar();
335			if (sVar.isUsedInPhi() || sVar.getUseCount() == 0) {
336				return Collections.emptyList();
337			}
338			List<InsnNode> useChain = new ArrayList<>(sVar.getUseCount() + 1);
339			InsnNode assignInsn = sVar.getAssign().getParentInsn();
340			if (assignInsn == null) {
341				return Collections.emptyList();
342			}
343			useChain.add(assignInsn);
344			for (RegisterArg reg : sVar.getUseList()) {
345				InsnNode parentInsn = reg.getParentInsn();
346				if (parentInsn == null) {
347					return Collections.emptyList();
348				}
349				useChain.add(parentInsn);
350			}
351			int toStrIdx = InsnList.getIndex(useChain, insn);
352			if (useChain.size() - 1 != toStrIdx) {
353				return Collections.emptyList();
354			}
355			useChain.remove(toStrIdx);
356	
357			// all insns must be in one block and sequential
358			BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
359			if (assignBlock == null) {
360				return Collections.emptyList();
361			}
362			List<InsnNode> blockInsns = assignBlock.getInstructions();
363			int assignIdx = InsnList.getIndex(blockInsns, assignInsn);
364			int chainSize = useChain.size();
365			int lastInsn = blockInsns.size() - assignIdx;
366			if (lastInsn < chainSize) {
367				return Collections.emptyList();
368			}
369			for (int i = 1; i < chainSize; i++) {
370				if (blockInsns.get(assignIdx + i) != useChain.get(i)) {
371					return Collections.emptyList();
372				}
373			}
374			return useChain;
375		}
