377		private static InsnNode convertStringBuilderChain(MethodNode mth, InvokeNode toStrInsn, List<InsnNode> chain) {
378			try {
379				int chainSize = chain.size();
380				if (chainSize < 2) {
381					return null;
382				}
383				List<InsnArg> args = new ArrayList<>(chainSize);
384				InsnNode firstInsn = chain.get(0);
385				if (firstInsn.getType() != InsnType.CONSTRUCTOR) {
386					return null;
387				}
388				ConstructorInsn constrInsn = (ConstructorInsn) firstInsn;
389				if (constrInsn.getArgsCount() == 1) {
390					ArgType argType = constrInsn.getCallMth().getArgumentsTypes().get(0);
391					if (!argType.isObject()) {
392						return null;
393					}
394					args.add(constrInsn.getArg(0));
395				}
396				for (int i = 1; i < chainSize; i++) {
397					InsnNode chainInsn = chain.get(i);
398					InsnArg arg = getArgFromAppend(chainInsn);
399					if (arg == null) {
400						return null;
401					}
402					args.add(arg);
403				}
404	
405				// all check passed
406				List<InsnArg> dupArgs = Utils.collectionMap(args, InsnArg::duplicate);
407				List<InsnArg> simplifiedArgs = concatConstArgs(dupArgs);
408				InsnNode concatInsn = new InsnNode(InsnType.STR_CONCAT, simplifiedArgs);
409				concatInsn.add(AFlag.SYNTHETIC);
410				if (toStrInsn.getResult() == null && !toStrInsn.contains(AFlag.WRAPPED)) {
411					// string concat without assign to variable will cause compilation error
412					concatInsn.setResult(mth.makeSyntheticRegArg(ArgType.STRING));
413				} else {
414					concatInsn.setResult(toStrInsn.getResult());
415				}
416				concatInsn.copyAttributesFrom(toStrInsn);
417				removeStringBuilderInsns(mth, toStrInsn, chain);
418				return concatInsn;
419			} catch (Exception e) {
420				mth.addWarnComment("String concatenation convert failed", e);
421			}
422			return null;
423		}
