486		/**
487		 * Remove and unbind all instructions with StringBuilder
488		 */
489		private static void removeStringBuilderInsns(MethodNode mth, InvokeNode toStrInsn, List<InsnNode> chain) {
490			InsnRemover.unbindAllArgs(mth, toStrInsn);
491			for (InsnNode insnNode : chain) {
492				InsnRemover.unbindAllArgs(mth, insnNode);
493			}
494			InsnRemover insnRemover = new InsnRemover(mth);
495			for (InsnNode insnNode : chain) {
496				if (insnNode != toStrInsn) {
497					insnRemover.addAndUnbind(insnNode);
498				}
499			}
500			insnRemover.perform();
501		}
