1	package jadx.core.dex.visitors;
2	
3	import java.util.HashMap;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.function.IntFunction;
7	
8	import org.jetbrains.annotations.Nullable;
9	
10	import jadx.core.dex.attributes.AFlag;
11	import jadx.core.dex.attributes.AType;
12	import jadx.core.dex.attributes.nodes.EnumClassAttr;
13	import jadx.core.dex.attributes.nodes.EnumMapAttr;
14	import jadx.core.dex.attributes.nodes.RegionRefAttr;
15	import jadx.core.dex.info.AccessInfo;
16	import jadx.core.dex.info.FieldInfo;
17	import jadx.core.dex.info.MethodInfo;
18	import jadx.core.dex.instructions.IndexInsnNode;
19	import jadx.core.dex.instructions.InsnType;
20	import jadx.core.dex.instructions.InvokeNode;
21	import jadx.core.dex.instructions.SwitchInsn;
22	import jadx.core.dex.instructions.args.InsnArg;
23	import jadx.core.dex.instructions.args.InsnWrapArg;
24	import jadx.core.dex.instructions.args.LiteralArg;
25	import jadx.core.dex.nodes.BlockNode;
26	import jadx.core.dex.nodes.ClassNode;
27	import jadx.core.dex.nodes.FieldNode;
28	import jadx.core.dex.nodes.InsnNode;
29	import jadx.core.dex.nodes.MethodNode;
30	import jadx.core.dex.nodes.RootNode;
31	import jadx.core.dex.regions.SwitchRegion;
32	import jadx.core.dex.visitors.shrink.CodeShrinkVisitor;
33	import jadx.core.utils.Utils;
34	import jadx.core.utils.exceptions.JadxException;
35	
36	@JadxVisitor(
37			name = "FixSwitchOverEnum",
38			desc = "Simplify synthetic code in switch over enum",
39			runAfter = {
40					CodeShrinkVisitor.class,
41					EnumVisitor.class
42			}
43	)
44	public class FixSwitchOverEnum extends AbstractVisitor {
45	
46		@Override
47		public boolean visit(ClassNode cls) throws JadxException {
48			initClsEnumMap(cls);
49			return true;
50		}
51	
52		@Override
53		public void visit(MethodNode mth) throws JadxException {
54			if (mth.isNoCode()) {
55				return;
56			}
57			boolean changed = false;
58			for (BlockNode block : mth.getBasicBlocks()) {
59				for (InsnNode insn : block.getInstructions()) {
60					if (insn.getType() == InsnType.SWITCH && !insn.contains(AFlag.REMOVE)) {
61						changed |= processEnumSwitch(mth, (SwitchInsn) insn);
62					}
63				}
64			}
65			if (changed) {
66				CodeShrinkVisitor.shrinkMethod(mth);
67			}
68		}
69	
70		private static boolean processEnumSwitch(MethodNode mth, SwitchInsn insn) {
71			InsnArg arg = insn.getArg(0);
72			if (!arg.isInsnWrap()) {
73				return false;
74			}
75			InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
76			switch (wrapInsn.getType()) {
77				case AGET:
78					return processRemappedEnumSwitch(mth, insn, wrapInsn, arg);
79				case INVOKE:
80					return processDirectEnumSwitch(mth, insn, (InvokeNode) wrapInsn, arg);
81			}
82			return false;
83		}
84	
85		private static boolean executeReplace(SwitchInsn swInsn, InsnArg arg, InsnArg invVar, IntFunction<Object> caseReplace) {
86			RegionRefAttr regionRefAttr = swInsn.get(AType.REGION_REF);
87			if (regionRefAttr == null) {
88				return false;
89			}
90			if (!swInsn.replaceArg(arg, invVar)) {
91				return false;
92			}
93			Map<Object, Object> replaceMap = new HashMap<>();
94			int caseCount = swInsn.getKeys().length;
95			for (int i = 0; i < caseCount; i++) {
96				Object key = swInsn.getKey(i);
97				Object replaceObj = caseReplace.apply(i);
98				swInsn.modifyKey(i, replaceObj);
99				replaceMap.put(key, replaceObj);
100			}
101			SwitchRegion region = (SwitchRegion) regionRefAttr.getRegion();
102			for (SwitchRegion.CaseInfo caseInfo : region.getCases()) {
103				caseInfo.getKeys().replaceAll(key -> Utils.getOrElse(replaceMap.get(key), key));
104			}
105			return true;
106		}
107	
108		private static boolean processDirectEnumSwitch(MethodNode mth, SwitchInsn swInsn, InvokeNode invInsn, InsnArg arg) {
109			MethodInfo callMth = invInsn.getCallMth();
110			if (!callMth.getShortId().equals("ordinal()I")) {
111				return false;
112			}
113			InsnArg invVar = invInsn.getArg(0);
114			ClassNode enumCls = mth.root().resolveClass(invVar.getType());
115			if (enumCls == null) {
116				return false;
117			}
118			EnumClassAttr enumClassAttr = enumCls.get(AType.ENUM_CLASS);
119			if (enumClassAttr == null) {
120				return false;
121			}
122			FieldNode[] casesReplaceArr = mapToCases(swInsn, enumClassAttr.getFields());
123			if (casesReplaceArr == null) {
124				return false;
125			}
126			return executeReplace(swInsn, arg, invVar, i -> casesReplaceArr[i]);
127		}
128	
129		private static @Nullable FieldNode[] mapToCases(SwitchInsn swInsn, List<EnumClassAttr.EnumField> fields) {
130			int caseCount = swInsn.getKeys().length;
131			if (fields.size() < caseCount) {
132				return null;
133			}
134			FieldNode[] casesMap = new FieldNode[caseCount];
135			for (int i = 0; i < caseCount; i++) {
136				Object key = swInsn.getKey(i);
137				if (key instanceof Integer) {
138					int ordinal = (Integer) key;
139					try {
140						casesMap[ordinal] = fields.get(ordinal).getField();
141					} catch (Exception e) {
142						return null;
143					}
144				} else {
145					return null;
146				}
147			}
148			return casesMap;
149		}
150	
151		private static boolean processRemappedEnumSwitch(MethodNode mth, SwitchInsn insn, InsnNode wrapInsn, InsnArg arg) {
152			EnumMapInfo enumMapInfo = checkEnumMapAccess(mth.root(), wrapInsn);
153			if (enumMapInfo == null) {
154				return false;
155			}
156			FieldNode enumMapField = enumMapInfo.getMapField();
157			InsnArg invArg = enumMapInfo.getArg();
158	
159			EnumMapAttr.KeyValueMap valueMap = getEnumMap(enumMapField);
160			if (valueMap == null) {
161				return false;
162			}
163			int caseCount = insn.getKeys().length;
164			for (int i = 0; i < caseCount; i++) {
165				Object key = insn.getKey(i);
166				Object newKey = valueMap.get(key);
167				if (newKey == null) {
168					return false;
169				}
170			}
171			if (executeReplace(insn, arg, invArg, i -> valueMap.get(insn.getKey(i)))) {
172				enumMapField.add(AFlag.DONT_GENERATE);
173				checkAndHideClass(enumMapField.getParentClass());
174				return true;
175			}
176			return false;
177		}
178	
179		private static void initClsEnumMap(ClassNode enumCls) {
180			MethodNode clsInitMth = enumCls.getClassInitMth();
181			if (clsInitMth == null || clsInitMth.isNoCode() || clsInitMth.getBasicBlocks() == null) {
182				return;
183			}
184			EnumMapAttr mapAttr = new EnumMapAttr();
185			for (BlockNode block : clsInitMth.getBasicBlocks()) {
186				for (InsnNode insn : block.getInstructions()) {
187					if (insn.getType() == InsnType.APUT) {
188						addToEnumMap(enumCls.root(), mapAttr, insn);
189					}
190				}
191			}
192			if (!mapAttr.isEmpty()) {
193				enumCls.addAttr(mapAttr);
194			}
195		}
196	
197		private static @Nullable EnumMapAttr.KeyValueMap getEnumMap(FieldNode field) {
198			ClassNode syntheticClass = field.getParentClass();
199			EnumMapAttr mapAttr = syntheticClass.get(AType.ENUM_MAP);
200			if (mapAttr == null) {
201				return null;
202			}
203			return mapAttr.getMap(field);
204		}
205	
206		private static void addToEnumMap(RootNode root, EnumMapAttr mapAttr, InsnNode aputInsn) {
207			InsnArg litArg = aputInsn.getArg(2);
208			if (!litArg.isLiteral()) {
209				return;
210			}
211			EnumMapInfo mapInfo = checkEnumMapAccess(root, aputInsn);
212			if (mapInfo == null) {
213				return;
214			}
215			InsnArg enumArg = mapInfo.getArg();
216			FieldNode field = mapInfo.getMapField();
217			if (field == null || !enumArg.isInsnWrap()) {
218				return;
219			}
220			InsnNode sget = ((InsnWrapArg) enumArg).getWrapInsn();
221			if (!(sget instanceof IndexInsnNode)) {
222				return;
223			}
224			Object index = ((IndexInsnNode) sget).getIndex();
225			if (!(index instanceof FieldInfo)) {
226				return;
227			}
228			FieldNode fieldNode = root.resolveField((FieldInfo) index);
229			if (fieldNode == null) {
230				return;
231			}
232			int literal = (int) ((LiteralArg) litArg).getLiteral();
233			mapAttr.add(field, literal, fieldNode);
234		}
235	
236		private static @Nullable EnumMapInfo checkEnumMapAccess(RootNode root, InsnNode checkInsn) {
237			InsnArg sgetArg = checkInsn.getArg(0);
238			InsnArg invArg = checkInsn.getArg(1);
239			if (!sgetArg.isInsnWrap() || !invArg.isInsnWrap()) {
240				return null;
241			}
242			InsnNode invInsn = ((InsnWrapArg) invArg).getWrapInsn();
243			InsnNode sgetInsn = ((InsnWrapArg) sgetArg).getWrapInsn();
244			if (invInsn.getType() != InsnType.INVOKE || sgetInsn.getType() != InsnType.SGET) {
245				return null;
246			}
247			InvokeNode inv = (InvokeNode) invInsn;
248			if (!inv.getCallMth().getShortId().equals("ordinal()I")) {
249				return null;
250			}
251			ClassNode enumCls = root.resolveClass(inv.getCallMth().getDeclClass());
252			if (enumCls == null || !enumCls.isEnum()) {
253				return null;
254			}
255			Object index = ((IndexInsnNode) sgetInsn).getIndex();
256			if (!(index instanceof FieldInfo)) {
257				return null;
258			}
259			FieldNode enumMapField = root.resolveField((FieldInfo) index);
260			if (enumMapField == null || !enumMapField.getAccessFlags().isSynthetic()) {
261				return null;
262			}
263			return new EnumMapInfo(inv.getArg(0), enumMapField);
264		}
265	
266		/**
267		 * If all static final synthetic fields have DONT_GENERATE => hide whole class
268		 */
269		private static void checkAndHideClass(ClassNode cls) {
270			for (FieldNode field : cls.getFields()) {
271				AccessInfo af = field.getAccessFlags();
272				if (af.isSynthetic() && af.isStatic() && af.isFinal()
273						&& !field.contains(AFlag.DONT_GENERATE)) {
274					return;
275				}
276			}
277			cls.add(AFlag.DONT_GENERATE);
278		}
279	
280		private static class EnumMapInfo {
281			private final InsnArg arg;
282			private final FieldNode mapField;
283	
284			public EnumMapInfo(InsnArg arg, FieldNode mapField) {
285				this.arg = arg;
286				this.mapField = mapField;
287			}
288	
289			public InsnArg getArg() {
290				return arg;
291			}
292	
293			public FieldNode getMapField() {
294				return mapField;
295			}
296		}
297	}
