1	package jadx.core.dex.visitors;
2	
3	import java.util.List;
4	
5	import org.jetbrains.annotations.Nullable;
6	
7	import jadx.core.codegen.TypeGen;
8	import jadx.core.dex.attributes.AFlag;
9	import jadx.core.dex.info.ClassInfo;
10	import jadx.core.dex.info.MethodInfo;
11	import jadx.core.dex.instructions.IndexInsnNode;
12	import jadx.core.dex.instructions.InsnType;
13	import jadx.core.dex.instructions.InvokeNode;
14	import jadx.core.dex.instructions.PhiInsn;
15	import jadx.core.dex.instructions.args.ArgType;
16	import jadx.core.dex.instructions.args.InsnArg;
17	import jadx.core.dex.instructions.args.LiteralArg;
18	import jadx.core.dex.instructions.args.RegisterArg;
19	import jadx.core.dex.instructions.mods.ConstructorInsn;
20	import jadx.core.dex.nodes.BlockNode;
21	import jadx.core.dex.nodes.ClassNode;
22	import jadx.core.dex.nodes.InsnNode;
23	import jadx.core.dex.nodes.MethodNode;
24	import jadx.core.dex.visitors.ssa.SSATransform;
25	import jadx.core.dex.visitors.typeinference.TypeInferenceVisitor;
26	import jadx.core.utils.BlockUtils;
27	import jadx.core.utils.InsnRemover;
28	import jadx.core.utils.exceptions.JadxRuntimeException;
29	
30	@JadxVisitor(
31			name = "ConstructorVisitor",
32			desc = "Replace invoke with constructor call",
33			runAfter = { SSATransform.class, MoveInlineVisitor.class },
34			runBefore = TypeInferenceVisitor.class
35	)
36	public class ConstructorVisitor extends AbstractVisitor {
37		@Override
38		public void visit(MethodNode mth) {
39			if (mth.isNoCode()) {
40				return;
41			}
42			if (replaceInvoke(mth)) {
43				MoveInlineVisitor.moveInline(mth);
44			}
45		}
46	
47		private static boolean replaceInvoke(MethodNode mth) {
48			boolean replaced = false;
49			InsnRemover remover = new InsnRemover(mth);
50			for (BlockNode block : mth.getBasicBlocks()) {
51				remover.setBlock(block);
52				int size = block.getInstructions().size();
53				for (int i = 0; i < size; i++) {
54					InsnNode insn = block.getInstructions().get(i);
55					if (insn.getType() == InsnType.INVOKE) {
56						replaced |= processInvoke(mth, block, i, remover);
57					}
58				}
59				remover.perform();
60			}
61			return replaced;
62		}
63	
64		private static boolean processInvoke(MethodNode mth, BlockNode block, int indexInBlock, InsnRemover remover) {
65			InvokeNode inv = (InvokeNode) block.getInstructions().get(indexInBlock);
66			MethodInfo callMth = inv.getCallMth();
67			if (!callMth.isConstructor()) {
68				return false;
69			}
70			ArgType instType = searchInstanceType(inv);
71			if (instType != null && !instType.equals(callMth.getDeclClass().getType())) {
72				ClassInfo instCls = ClassInfo.fromType(mth.root(), instType);
73				callMth = MethodInfo.fromDetails(mth.root(), instCls, callMth.getName(),
74						callMth.getArgumentsTypes(), callMth.getReturnType());
75			}
76			ConstructorInsn co = new ConstructorInsn(mth, inv, callMth);
77			if (canRemoveConstructor(mth, co)) {
78				remover.addAndUnbind(inv);
79				return false;
80			}
81			co.inheritMetadata(inv);
82	
83			RegisterArg instanceArg = (RegisterArg) inv.getArg(0);
84			instanceArg.getSVar().removeUse(instanceArg);
85			if (co.isNewInstance()) {
86				InsnNode assignInsn = instanceArg.getAssignInsn();
87				if (assignInsn != null) {
88					if (assignInsn.getType() == InsnType.CONSTRUCTOR) {
89						// arg already used in another constructor instruction
90						// insert new PHI insn to merge these branched constructors results
91						instanceArg = insertPhiInsn(mth, block, instanceArg, ((ConstructorInsn) assignInsn));
92					} else {
93						InsnNode newInstInsn = removeAssignChain(mth, assignInsn, remover, InsnType.NEW_INSTANCE);
94						if (newInstInsn != null) {
95							co.inheritMetadata(newInstInsn);
96							newInstInsn.add(AFlag.REMOVE);
97							remover.addWithoutUnbind(newInstInsn);
98						}
99					}
100				}
101				// convert instance arg from 'use' to 'assign'
102				co.setResult(instanceArg.duplicate());
103			}
104			co.rebindArgs();
105			ConstructorInsn replace = processConstructor(mth, co);
106			if (replace != null) {
107				remover.addAndUnbind(co);
108				BlockUtils.replaceInsn(mth, block, indexInBlock, replace);
109			} else {
110				BlockUtils.replaceInsn(mth, block, indexInBlock, co);
111			}
112			return true;
113		}
114	
115		private static @Nullable ArgType searchInstanceType(InvokeNode inv) {
116			InsnArg instanceArg = inv.getInstanceArg();
117			if (instanceArg == null || !instanceArg.isRegister()) {
118				return null;
119			}
120			InsnNode assignInsn = ((RegisterArg) instanceArg).getSVar().getAssignInsn();
121			if (assignInsn == null || assignInsn.getType() != InsnType.NEW_INSTANCE) {
122				return null;
123			}
124			return ((IndexInsnNode) assignInsn).getIndexAsType();
125		}
126	
127		private static RegisterArg insertPhiInsn(MethodNode mth, BlockNode curBlock,
128				RegisterArg instArg, ConstructorInsn otherCtr) {
129			BlockNode otherBlock = BlockUtils.getBlockByInsn(mth, otherCtr);
130			if (otherBlock == null) {
131				throw new JadxRuntimeException("Block not found by insn: " + otherCtr);
132			}
133			BlockNode crossBlock = BlockUtils.getPathCross(mth, curBlock, otherBlock);
134			if (crossBlock == null) {
135				// no path cross => PHI insn not needed
136				// use new SSA var on usage from current path
137				RegisterArg newResArg = instArg.duplicateWithNewSSAVar(mth);
138				List<BlockNode> pathBlocks = BlockUtils.collectAllSuccessors(mth, curBlock, true);
139				for (RegisterArg useReg : instArg.getSVar().getUseList()) {
140					InsnNode parentInsn = useReg.getParentInsn();
141					if (parentInsn != null) {
142						BlockNode useBlock = BlockUtils.getBlockByInsn(mth, parentInsn, pathBlocks);
143						if (useBlock != null) {
144							parentInsn.replaceArg(useReg, newResArg.duplicate());
145						}
146					}
147				}
148				return newResArg;
149			}
150			RegisterArg newResArg = instArg.duplicateWithNewSSAVar(mth);
151			RegisterArg useArg = otherCtr.getResult();
152			RegisterArg otherResArg = useArg.duplicateWithNewSSAVar(mth);
153	
154			PhiInsn phiInsn = SSATransform.addPhi(mth, crossBlock, useArg.getRegNum());
155			phiInsn.setResult(useArg.duplicate());
156			phiInsn.bindArg(newResArg.duplicate(), BlockUtils.getPrevBlockOnPath(mth, crossBlock, curBlock));
157			phiInsn.bindArg(otherResArg.duplicate(), BlockUtils.getPrevBlockOnPath(mth, crossBlock, otherBlock));
158			phiInsn.rebindArgs();
159	
160			otherCtr.setResult(otherResArg.duplicate());
161			otherCtr.rebindArgs();
162			return newResArg;
163		}
164	
165		private static boolean canRemoveConstructor(MethodNode mth, ConstructorInsn co) {
166			ClassNode parentClass = mth.getParentClass();
167			if (co.isSuper() && co.getArgsCount() == 0) {
168				return true;
169			}
170			if (co.isThis() && co.getArgsCount() == 0) {
171				MethodNode defCo = parentClass.searchMethodByShortId(co.getCallMth().getShortId());
172				if (defCo == null || defCo.isNoCode()) {
173					// default constructor not implemented
174					return true;
175				}
176			}
177			// remove super() call in instance initializer
178			return parentClass.isAnonymous() && mth.isDefaultConstructor() && co.isSuper();
179		}
180	
181		/**
182		 * Replace call of synthetic constructor with all 'null' args
183		 * to a non-synthetic or default constructor if possible.
184		 *
185		 * @return insn for replacement or null if replace not needed or not possible.
186		 */
187		@Nullable
188		private static ConstructorInsn processConstructor(MethodNode mth, ConstructorInsn co) {
189			MethodNode callMth = mth.root().resolveMethod(co.getCallMth());
190			if (callMth == null
191					|| !callMth.getAccessFlags().isSynthetic()
192					|| !allArgsNull(co)) {
193				return null;
194			}
195			ClassNode classNode = mth.root().resolveClass(callMth.getParentClass().getClassInfo());
196			if (classNode == null) {
197				return null;
198			}
199			RegisterArg instanceArg = co.getResult();
200			if (instanceArg == null) {
201				return null;
202			}
203			boolean passThis = instanceArg.isThis();
204			String ctrId = "<init>(" + (passThis ? TypeGen.signature(instanceArg.getInitType()) : "") + ")V";
205			MethodNode defCtr = classNode.searchMethodByShortId(ctrId);
206			if (defCtr == null || defCtr.equals(callMth) || defCtr.getAccessFlags().isSynthetic()) {
207				return null;
208			}
209			ConstructorInsn newInsn = new ConstructorInsn(defCtr.getMethodInfo(), co.getCallType());
210			newInsn.setResult(co.getResult().duplicate());
211			newInsn.inheritMetadata(co);
212			return newInsn;
213		}
214	
215		private static boolean allArgsNull(ConstructorInsn insn) {
216			for (InsnArg insnArg : insn.getArguments()) {
217				if (insnArg.isLiteral()) {
218					LiteralArg lit = (LiteralArg) insnArg;
219					if (lit.getLiteral() != 0) {
220						return false;
221					}
222				} else {
223					return false;
224				}
225			}
226			return true;
227		}
228	
229		/**
230		 * Remove instructions on 'move' chain until instruction with type 'insnType'
231		 */
232		private static InsnNode removeAssignChain(MethodNode mth, InsnNode insn, InsnRemover remover, InsnType insnType) {
233			if (insn == null) {
234				return null;
235			}
236			InsnType type = insn.getType();
237			if (type == insnType) {
238				return insn;
239			}
240			if (insn.isAttrStorageEmpty()) {
241				remover.addWithoutUnbind(insn);
242			} else {
243				BlockUtils.replaceInsn(mth, insn, new InsnNode(InsnType.NOP, 0));
244			}
245			if (type == InsnType.MOVE) {
246				RegisterArg arg = (RegisterArg) insn.getArg(0);
247				return removeAssignChain(mth, arg.getAssignInsn(), remover, insnType);
248			}
249			return null;
250		}
251	}
