29	@JadxVisitor(
30			name = "ShadowFieldVisitor",
31			desc = "Fix shadowed field access",
32			runAfter = TypeInferenceVisitor.class,
33			runBefore = CodeShrinkVisitor.class
34	)
35	public class ShadowFieldVisitor extends AbstractVisitor {
36		private Map<String, FieldFixInfo> fixInfoMap;
37	
38		@Override
39		public void init(RootNode root) {
40			Map<String, FieldFixInfo> map = new HashMap<>();
41			for (ClassNode cls : root.getClasses(true)) {
42				Map<FieldInfo, FieldFixType> fieldFixMap = searchShadowedFields(cls);
43				if (!fieldFixMap.isEmpty()) {
44					FieldFixInfo fixInfo = new FieldFixInfo();
45					fixInfo.fieldFixMap = fieldFixMap;
46					map.put(cls.getRawName(), fixInfo);
47				}
48			}
49			this.fixInfoMap = map;
50		}
51	
52		@Override
53		public void visit(MethodNode mth) throws JadxException {
54			if (mth.isNoCode()) {
55				return;
56			}
57			fixShadowFieldAccess(mth, fixInfoMap);
58		}
59	
60		private static class FieldFixInfo {
61			Map<FieldInfo, FieldFixType> fieldFixMap;
62		}
63	
64		private enum FieldFixType {
65			SUPER,
66			CAST
67		}
68	
69		private static Map<FieldInfo, FieldFixType> searchShadowedFields(ClassNode thisCls) {
70			List<FieldNode> allFields = collectAllInstanceFields(thisCls);
71			if (allFields.isEmpty()) {
72				return Collections.emptyMap();
73			}
74			Map<String, List<FieldNode>> mapByName = groupByName(allFields);
75			mapByName.entrySet().removeIf(entry -> entry.getValue().size() == 1);
76			if (mapByName.isEmpty()) {
77				return Collections.emptyMap();
78			}
79			Map<FieldInfo, FieldFixType> fixMap = new HashMap<>();
80			for (List<FieldNode> fields : mapByName.values()) {
81				boolean fromThisCls = fields.get(0).getParentClass() == thisCls;
82				if (fromThisCls && fields.size() == 2) {
83					// only one super class contains same field => can use super
84					FieldNode otherField = fields.get(1);
85					if (otherField.getParentClass() != thisCls) {
86						fixMap.put(otherField.getFieldInfo(), FieldFixType.SUPER);
87					}
88				} else {
89					// several super classes contains same field => can't use super, need cast to exact class
90					for (FieldNode field : fields) {
91						if (field.getParentClass() != thisCls) {
92							fixMap.put(field.getFieldInfo(), FieldFixType.CAST);
93						}
94					}
95				}
96			}
97			return fixMap;
98		}
99	
100		private static Map<String, List<FieldNode>> groupByName(List<FieldNode> allFields) {
101			Map<String, List<FieldNode>> groupByName = new HashMap<>(allFields.size());
102			for (FieldNode field : allFields) {
103				groupByName
104						.computeIfAbsent(field.getName(), k -> new ArrayList<>())
105						.add(field);
106			}
107			return groupByName;
108		}
109	
110		private static List<FieldNode> collectAllInstanceFields(ClassNode cls) {
111			List<FieldNode> fieldsList = new ArrayList<>();
112			Set<ClassNode> visited = new HashSet<>();
113			ClassNode currentClass = cls;
114			while (currentClass != null) {
115				if (!visited.add(currentClass)) {
116					String msg = "Found 'super' loop in classes: " + visited;
117					visited.forEach(c -> c.addWarnComment(msg));
118					return fieldsList;
119				}
120				for (FieldNode field : currentClass.getFields()) {
121					if (!field.getAccessFlags().isStatic()) {
122						fieldsList.add(field);
123					}
124				}
125				ArgType superClass = currentClass.getSuperClass();
126				if (superClass == null) {
127					break;
128				}
129				currentClass = cls.root().resolveClass(superClass);
130			}
131			return fieldsList;
132		}
133	
134		private static void fixShadowFieldAccess(MethodNode mth, Map<String, FieldFixInfo> fixInfoMap) {
135			for (BlockNode block : mth.getBasicBlocks()) {
136				for (InsnNode insn : block.getInstructions()) {
137					processInsn(mth, insn, fixInfoMap);
138				}
139			}
140		}
141	
142		private static void processInsn(MethodNode mth, InsnNode insn, Map<String, FieldFixInfo> fixInfoMap) {
143			FieldInfo fieldInfo = getFieldInfo(insn);
144			if (fieldInfo == null) {
145				return;
146			}
147			InsnArg arg = insn.getArg(insn.getArgsCount() - 1);
148			ArgType type = arg.getType();
149			if (!type.isTypeKnown() || !type.isObject()) {
150				return;
151			}
152			FieldFixInfo fieldFixInfo = fixInfoMap.get(type.getObject());
153			if (fieldFixInfo == null) {
154				return;
155			}
156			FieldFixType fieldFixType = fieldFixInfo.fieldFixMap.get(fieldInfo);
157			if (fieldFixType == null) {
158				return;
159			}
160			fixFieldAccess(mth, fieldInfo, fieldFixType, arg);
161		}
162	
163		@Nullable
164		private static FieldInfo getFieldInfo(InsnNode insn) {
165			switch (insn.getType()) {
166				case IPUT:
167				case IGET:
168					return (FieldInfo) ((IndexInsnNode) insn).getIndex();
169				default:
170					return null;
171			}
172		}
173	
174		private static void fixFieldAccess(MethodNode mth, FieldInfo fieldInfo, FieldFixType fieldFixType, InsnArg arg) {
175			if (fieldFixType == FieldFixType.SUPER) {
176				if (arg.isThis()) {
177					// convert 'this' to 'super'
178					arg.add(AFlag.SUPER);
179					return;
180				}
181			}
182			// apply cast
183			InsnNode castInsn = new IndexInsnNode(InsnType.CAST, fieldInfo.getDeclClass().getType(), 1);
184			castInsn.addArg(arg.duplicate());
185			castInsn.add(AFlag.SYNTHETIC);
186			castInsn.add(AFlag.EXPLICIT_CAST);
187			arg.wrapInstruction(mth, castInsn, false);
188		}
189	}
