		return false;
	}

	public static boolean containsVar(InsnArg insnArg, RegisterArg arg) {
		if (insnArg.isRegister()) {
			return ((RegisterArg) insnArg).sameRegAndSVar(arg);
		}
		if (insnArg.isInsnWrap()) {
			InsnNode wrapInsn = ((InsnWrapArg) insnArg).getWrapInsn();
			return containsVar(wrapInsn, arg);
		}
		return false;
	}

	public static boolean contains(InsnNode insn, AFlag flag) {
		return insn != null && insn.contains(flag);
	}

	@Nullable
	public static InsnNode isCastDuplicate(IndexInsnNode castInsn) {
		InsnArg arg = castInsn.getArg(0);
		if (arg.isRegister()) {
			SSAVar sVar = ((RegisterArg) arg).getSVar();
			if (sVar != null && sVar.getUseCount() == 1 && !sVar.isUsedInPhi()) {
				InsnNode assignInsn = sVar.getAssign().getParentInsn();
				if (assignInsn != null && assignInsn.getType() == InsnType.CHECK_CAST) {
					ArgType assignCastType = (ArgType) ((IndexInsnNode) assignInsn).getIndex();
					if (assignCastType.equals(castInsn.getIndex())) {
						return assignInsn;
					}
				}
			}
		}
		return null;
	}
}

