129		private void mergeAnonymousDeps(RootNode root) {
130			// Collect edges to build bidirectional tree:
131			// inline edge: anonymous -> outer (one-to-one)
132			// use edges: outer -> *anonymous (one-to-many)
133			Map<ClassNode, ClassNode> inlineMap = new HashMap<>();
134			Map<ClassNode, List<ClassNode>> useMap = new HashMap<>();
135			for (ClassNode anonymousCls : root.getClasses()) {
136				AnonymousClassAttr attr = anonymousCls.get(AType.ANONYMOUS_CLASS);
137				if (attr != null) {
138					ClassNode outerCls = attr.getOuterCls();
139					List<ClassNode> list = useMap.get(outerCls);
140					if (list == null || list.isEmpty()) {
141						list = new ArrayList<>(2);
142						useMap.put(outerCls, list);
143					}
144					list.add(anonymousCls);
145					useMap.putIfAbsent(anonymousCls, Collections.emptyList()); // put leaf explicitly
146					inlineMap.put(anonymousCls, outerCls);
147				}
148			}
149			if (inlineMap.isEmpty()) {
150				return;
151			}
152			// starting from leaf process deps in nodes up to root
153			Set<ClassNode> added = new HashSet<>();
