599		private void removeEnumMethods(ClassNode cls, FieldNode valuesField) {
600			ArgType clsType = cls.getClassInfo().getType();
601			String valuesMethodShortId = "values()" + TypeGen.signature(ArgType.array(clsType));
602			MethodNode valuesMethod = null;
603			// remove compiler generated methods
604			for (MethodNode mth : cls.getMethods()) {
605				MethodInfo mi = mth.getMethodInfo();
606				if (mi.isClassInit() || mth.isNoCode()) {
607					continue;
608				}
609				String shortId = mi.getShortId();
610				if (mi.isConstructor()) {
611					markArgsForSkip(mth);
612					// remove super constructor call
613					ConstructorInsn superCtrInsn = searchEnumSuperCtrInsn(mth);
614					if (superCtrInsn != null) {
615						superCtrInsn.add(AFlag.DONT_GENERATE);
616						InsnRemover.remove(mth, superCtrInsn);
617					}
618					if (isDefaultConstructor(mth, shortId)) {
619						mth.add(AFlag.DONT_GENERATE);
620					}
621				} else if (mi.getShortId().equals(valuesMethodShortId)) {
622					if (isValuesMethod(mth, clsType)) {
623						valuesMethod = mth;
624						mth.add(AFlag.DONT_GENERATE);
625					} else {
626						// custom values method => rename to resolve conflict with enum method
627						mth.getMethodInfo().setAlias("valuesCustom");
628						mth.addAttr(new RenameReasonAttr(mth).append("to resolve conflict with enum method"));
629					}
630				} else if (isValuesMethod(mth, clsType)) {
631					if (!mth.getMethodInfo().getAlias().equals("values") && !mth.getUseIn().isEmpty()) {
