301		private static InsnArg foundWrappedInsn(InsnNode container, InsnNode insn) {
302			for (InsnArg arg : container.getArguments()) {
303				if (arg.isInsnWrap()) {
304					InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
305					if (wrapInsn == insn) {
306						return arg;
307					}
308					InsnArg res = foundWrappedInsn(wrapInsn, insn);
309					if (res != null) {
310						return res;
311					}
312				}
313			}
314			if (container instanceof TernaryInsn) {
315				return foundWrappedInsnInCondition(((TernaryInsn) container).getCondition(), insn);
316			}
317			return null;
318		}
