320		private static InsnArg foundWrappedInsnInCondition(IfCondition cond, InsnNode insn) {
321			if (cond.isCompare()) {
322				IfNode cmpInsn = cond.getCompare().getInsn();
323				return foundWrappedInsn(cmpInsn, insn);
324			}
325			for (IfCondition nestedCond : cond.getArgs()) {
326				InsnArg res = foundWrappedInsnInCondition(nestedCond, insn);
327				if (res != null) {
328					return res;
329				}
330			}
331			return null;
332		}
