private static boolean isSplitByJump(InsnNode prevInsn, InsnNode currentInsn) {
	int prevOffset = prevInsn.getOffset();
	if (ListUtils.anyMatch(prevInsn.getAll(AType.JUMP), jump -> jump.getSrc() == prevOffset)) {
		return true;
	}
	int curOffset = currentInsn.getOffset();
	return ListUtils.anyMatch(currentInsn.getAll(AType.JUMP), jump -> jump.getDest() == curOffset);
}

