public boolean canReorder() {
	if (contains(AFlag.DONT_GENERATE)) {
		return getType() != InsnType.MONITOR_EXIT;
	}
	for (InsnArg arg : getArguments()) {
		if (arg.isInsnWrap()) {
			InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
			if (!wrapInsn.canReorder()) {
				return false;
			}
		}
	}

	switch (getType()) {
		case CONST:
		case CONST_STR:
		case CONST_CLASS:
		case CAST:
		case MOVE:
		case ARITH:
		case NEG:
		case CMP_L:
		case CMP_G:
		case CHECK_CAST:
		case INSTANCE_OF:
		case FILL_ARRAY:
		case FILLED_NEW_ARRAY:
		case NEW_ARRAY:
		case STR_CONCAT:
			return true;

		case SGET:
		case IGET:
			// TODO: allow to move final fields
			return false;

		default:
			return false;
	}
}

public boolean containsWrappedInsn() {
	return ListUtils.anyMatch(getArguments(), InsnArg::isInsnWrap);
}

/**
 * Visit this instruction and all inner (wrapped) instructions
 */
public void visitInsns(Consumer<InsnNode> visitor) {
	visitor.accept(this);
	for (InsnArg arg : this.getArguments()) {
		if (arg.isInsnWrap()) {
			((InsnWrapArg) arg).getWrapInsn().visitInsns(visitor);
		}
	}
}

