                var = s[0]
                if var.endswith(' = null;') or var.endswith('= null;'):
                    found.append(f'{fpath}:{i+1}: {var} | {s[1]}')

for f in found[:15]:
    print(f)
print(f'\nTotal: {len(found)}')
