				javaName = Utils.cleanObjectName(descString).replace('$', '.');
				break;
			case '[':
				javaName = smaliNameToJavaName(descString.substring(1)) + "[]";
				break;
			default:
				javaName = descString;
				break;
		}
		return javaName;
	}

	public static String javaNameToSmaliName(String descString) {
		if (descString.isEmpty()) {
			return descString;
		}

		if (descString.endsWith("[]")) {
			return '[' + javaNameToSmaliName(descString.substring(0, descString.length() - 2));
		}

		String javaName;
		switch (descString) {
			case "void":
				javaName = "V";
				break;
			case "boolean":
				javaName = "Z";
				break;
			case "char":
				javaName = "C";
				break;
			case "byte":
				javaName = "B";
				break;
			case "short":
				javaName = "S";
				break;
			case "int":
				javaName = "I";
				break;
			case "float":
				javaName = "F";
				break;
			case "long":
				javaName = "J";
				break;
			case "double":
				javaName = "D";
				break;
			default:
				javaName = Utils.makeQualifiedObjectName(descString);
				break;
		}
		return javaName;
	}

	@SuppressWarnings("StringRepeatCanBeUsed")
	public static String strRepeat(String str, int count) {
		if (count < 1) {
			return "";
		}
		if (count == 1) {
			return str;
		}
		StringBuilder sb = new StringBuilder(str.length() * count);
		for (int i = 0; i < count; i++) {
			sb.append(str);
		}
		return sb.toString();
	}

