	boolean changed;
	do {
		changed = false;
		for (BlockNode block : mth.getBasicBlocks()) {
			for (InsnNode insn : block.getInstructions()) {
				if (insn.getType() == InsnType.MOVE
						&& insn.isAttrStorageEmpty()
						&& isResultArgNotUsed(insn)) {
					InsnRemover.remove(mth, block, insn);
					changed = true;
					break;
				}
			}
		}
	} while (changed);
}

